FUNCTION_BLOCK "FB_OLED_Evaporation_Controller"
{ S7_Optimized_Access := 'TRUE' }
AUTHOR : 'Lumina Elite'
FAMILY : 'Semiconductor'
VERSION : 2.0
// Lead Semiconductor Engineer - OLED Vacuum Evaporation Controller
// Evolved from a standard PID block to a highly complex, cascaded control system
// Features: QCM Feedback, Cascaded Crucible Heating, and Substrate Sync.

VAR_INPUT
    // QCM Feedback
    ir_QCM_Thickness_nm : REAL;       // Current thickness measured by QCM [nm]
    ir_QCM_DepRate_nm_s : REAL;       // Current deposition rate [nm/s]
    ir_Target_DepRate_nm_s : REAL;    // Target deposition rate [nm/s]
    ir_Target_Thickness_nm : REAL;    // Target final thickness [nm]
    ir_Crystal_Life_Pct : REAL;       // QCM crystal remaining life [%]

    // Vacuum System
    ir_Chamber_Pressure_mBar : REAL;  // Chamber pressure [mBar]
    ir_Vacuum_Interlock_Threshold : REAL := 1.0E-6; // Minimum vacuum required [mBar]

    // Crucible & Heating
    ir_Crucible_Temp_C : REAL;        // Actual Crucible Temperature [C]
    ir_Crucible_Max_Temp_C : REAL := 1200.0; // Over-temperature limit

    // Substrate Rotation
    ir_Substrate_Speed_RPM : REAL;    // Actual substrate rotation [RPM]
    ir_Target_Substrate_RPM : REAL := 60.0;

    // Control Params
    ir_OuterLoop_Kp : REAL := 10.0;
    ir_OuterLoop_Ti : REAL := 5.0;
    ir_InnerLoop_Kp : REAL := 2.5;
    ir_InnerLoop_Ti : REAL := 2.0;
    ir_InnerLoop_Td : REAL := 0.5;

    ib_System_Enable : BOOL;
    ib_Reset_Faults : BOOL;
END_VAR

VAR_OUTPUT
    or_Crucible_Heater_PWM : REAL;    // Output to thyristor/heater [0.0 - 100.0 %]
    or_Substrate_Motor_Speed : REAL;  // Output to rotation servo [0.0 - 100.0 %]
    ob_Shutter_Open : BOOL;           // Source shutter control
    ob_Process_Complete : BOOL;
    ob_Fault_Active : BOOL;
    odw_Fault_Code : DWORD;
    or_Calculated_Temp_Setpoint : REAL; // Output of the outer rate loop
END_VAR

VAR
    // Outer Loop (Rate -> Temp)
    stat_Outer_Integral : REAL;
    stat_Outer_Prev_Error : REAL;

    // Inner Loop (Temp -> PWM)
    stat_Inner_Integral : REAL;
    stat_Inner_Prev_Error : REAL;
    stat_Inner_Prev_Temp : REAL;

    // Timers & Cycle time
    stat_LastCycleTime : LREAL;
    stat_DeltaTime_s : REAL;

    // States
    stat_Process_State : INT := 0; // 0=Idle, 1=Pumpdown, 2=Soak, 3=Deposition, 4=Cooldown
    stat_Shutter_Delay {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
    stat_Soak_Timer {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;

    // Filter
    stat_QCM_Rate_Filtered : REAL;

    // Constants
    MAX_TEMP_SETPOINT : REAL := 950.0;
    MIN_TEMP_SETPOINT : REAL := 20.0;
END_VAR

BEGIN
    // Calculate Cycle Time
    stat_DeltaTime_s := LREAL_TO_REAL(RUNTIME(stat_LastCycleTime));
    IF stat_DeltaTime_s <= 0.0 OR stat_DeltaTime_s > 1.0 THEN
        stat_DeltaTime_s := 0.1; // Default to 100ms if out of bounds
    END_IF;

    // Fault Reset
    IF ib_Reset_Faults THEN
        ob_Fault_Active := FALSE;
        odw_Fault_Code := 16#0000_0000;
    END_IF;

    // Fault Detection
    IF ir_Chamber_Pressure_mBar > ir_Vacuum_Interlock_Threshold AND ib_System_Enable AND stat_Process_State >= 2 THEN
        ob_Fault_Active := TRUE;
        odw_Fault_Code := odw_Fault_Code OR 16#0000_0001; // Vacuum Loss
    END_IF;
    IF ir_Crucible_Temp_C > ir_Crucible_Max_Temp_C THEN
        ob_Fault_Active := TRUE;
        odw_Fault_Code := odw_Fault_Code OR 16#0000_0002; // Over-temperature
    END_IF;
    IF ir_Crystal_Life_Pct < 5.0 THEN
        ob_Fault_Active := TRUE;
        odw_Fault_Code := odw_Fault_Code OR 16#0000_0004; // QCM Crystal Depleted
    END_IF;

    IF ob_Fault_Active OR NOT ib_System_Enable THEN
        stat_Process_State := 0;
        or_Crucible_Heater_PWM := 0.0;
        ob_Shutter_Open := FALSE;
        or_Substrate_Motor_Speed := 0.0;
        stat_Outer_Integral := 0.0;
        stat_Inner_Integral := 0.0;
        ob_Process_Complete := FALSE;
        RETURN;
    END_IF;

    // Substrate Rotation Control (Simple P-control for sync)
    or_Substrate_Motor_Speed := LIMIT(MN:=0.0, IN:=(ir_Target_Substrate_RPM * 1.2), MX:=100.0);

    // Process State Machine
    CASE stat_Process_State OF
        0: // Idle
            IF ib_System_Enable AND ir_Chamber_Pressure_mBar <= ir_Vacuum_Interlock_Threshold THEN
                stat_Process_State := 1; // Start Pre-heat
            END_IF;
            ob_Shutter_Open := FALSE;

        1: // Pre-heat / Soak
            // Set fixed temp setpoint for material soak
            or_Calculated_Temp_Setpoint := 300.0; 
            stat_Soak_Timer(IN:= (ir_Crucible_Temp_C >= 290.0), PT:=T#5m);
            IF stat_Soak_Timer.Q THEN
                stat_Process_State := 2; // Transition to deposition
            END_IF;
            ob_Shutter_Open := FALSE;

        2: // Deposition
            // Exponential moving average filter for QCM rate
            stat_QCM_Rate_Filtered := stat_QCM_Rate_Filtered * 0.8 + ir_QCM_DepRate_nm_s * 0.2;

            // Outer Loop PID: Rate -> Target Temp
            stat_Outer_Integral := stat_Outer_Integral + (ir_OuterLoop_Kp / ir_OuterLoop_Ti) * (ir_Target_DepRate_nm_s - stat_QCM_Rate_Filtered) * stat_DeltaTime_s;
            // Anti-windup
            stat_Outer_Integral := LIMIT(MN:=MIN_TEMP_SETPOINT, IN:=stat_Outer_Integral, MX:=MAX_TEMP_SETPOINT);

            or_Calculated_Temp_Setpoint := LIMIT(MN:=MIN_TEMP_SETPOINT, IN:=((ir_OuterLoop_Kp * (ir_Target_DepRate_nm_s - stat_QCM_Rate_Filtered)) + stat_Outer_Integral), MX:=MAX_TEMP_SETPOINT);

            // Shutter Logic: Open when rate is stable and within 5% of target
            IF ABS(ir_Target_DepRate_nm_s - stat_QCM_Rate_Filtered) < (ir_Target_DepRate_nm_s * 0.05) THEN
                stat_Shutter_Delay(IN:=TRUE, PT:=T#2s);
            ELSE
                stat_Shutter_Delay(IN:=FALSE, PT:=T#2s);
            END_IF;

            IF stat_Shutter_Delay.Q THEN
                ob_Shutter_Open := TRUE;
            END_IF;

            // Completion Check
            IF ir_QCM_Thickness_nm >= ir_Target_Thickness_nm AND ob_Shutter_Open THEN
                ob_Process_Complete := TRUE;
                stat_Process_State := 3; // Cooldown
            END_IF;

        3: // Cooldown
            ob_Shutter_Open := FALSE;
            or_Calculated_Temp_Setpoint := 0.0;
            IF ir_Crucible_Temp_C < 50.0 THEN
                stat_Process_State := 0;
            END_IF;
    END_CASE;

    // Inner Loop PID: Target Temp -> PWM
    IF ir_InnerLoop_Ti > 0.0 THEN
        stat_Inner_Integral := stat_Inner_Integral + (ir_InnerLoop_Kp / ir_InnerLoop_Ti) * (or_Calculated_Temp_Setpoint - ir_Crucible_Temp_C) * stat_DeltaTime_s;
        stat_Inner_Integral := LIMIT(MN:=0.0, IN:=stat_Inner_Integral, MX:=100.0);
    END_IF;

    IF stat_Process_State > 0 AND stat_Process_State < 3 THEN
        or_Crucible_Heater_PWM := LIMIT(MN:=0.0, IN:=((ir_InnerLoop_Kp * (or_Calculated_Temp_Setpoint - ir_Crucible_Temp_C)) + stat_Inner_Integral - (ir_InnerLoop_Td * (ir_Crucible_Temp_C - stat_Inner_Prev_Temp) / stat_DeltaTime_s)), MX:=100.0);
    ELSE
        or_Crucible_Heater_PWM := 0.0;
        stat_Inner_Integral := 0.0;
    END_IF;

    stat_Inner_Prev_Temp := ir_Crucible_Temp_C;

END_FUNCTION_BLOCK

