//=============================================================================
// TITANIUM VACUUM ARC REMELTING (VAR) FURNACE CONTROLLER
// ENGINEER: Lead Metallurgical Engineer
// SYSTEM: 30,000A DC Arc, Helium-Cooled Copper Crucible, X-Ray Gap Control
//=============================================================================

TYPE E_VAR_State :
(
    STATE_STANDBY := 0,
    STATE_EVACUATION := 10,
    STATE_HELIUM_MATRIX_INIT := 20,
    STATE_STRIKE_ARC := 30,
    STATE_MELT_CONTROL := 40,
    STATE_HOT_TOPPING := 50,
    STATE_COOLING := 60,
    STATE_FAULT_SCRAM := 999
) DINT;
END_TYPE

TYPE ST_XRay_Image_Data :
STRUCT
    Gap_mm : REAL;           // Measured gap via X-Ray
    Confidence : REAL;       // Confidence score 0.0-1.0
    ImageNoise : REAL;
    Timestamp : LTIME;
END_STRUCT
END_TYPE

TYPE ST_He_Cooling_Matrix :
STRUCT
    Zone1_Flow_LPM : REAL;
    Zone2_Flow_LPM : REAL;
    Zone3_Flow_LPM : REAL;
    Crucible_Temp_C : ARRAY[1..16] OF REAL; // Thermocouple matrix
    Pressure_mbar : REAL;
END_STRUCT
END_TYPE

//-----------------------------------------------------------------------------
// MAIN FUNCTION BLOCK: FB_VAR_Furnace_Controller
//-----------------------------------------------------------------------------
FUNCTION_BLOCK FB_VAR_Furnace_Controller
VAR_INPUT
    bStart_Melt : BOOL;
    bEStop : BOOL;

    // Power Supply Feedback
    fCurrent_Feedback_A : REAL;
    fVoltage_Feedback_V : REAL;

    // X-Ray Imaging System
    stXRayData : ST_XRay_Image_Data;

    // Crucible Cooling
    stHeCooling : ST_He_Cooling_Matrix;

    // Electrode Ram Position
    fRamPosition_mm : REAL;
END_VAR

VAR_OUTPUT
    eState : E_VAR_State;
    fCommand_Current_A : REAL;
    fRamSpeed_Cmd_mmps : REAL;
    bRamRetractFast : BOOL;

    bHeliumValve_Z1 : BOOL;
    bHeliumValve_Z2 : BOOL;
    bHeliumValve_Z3 : BOOL;

    bSystemFault : BOOL;
    sFaultMessage : STRING(255);
END_VAR

VAR
    // PID Controllers for Gap Control
    fbGapControlPID : FB_PID_Advanced; // Placeholder for PID FB

    // State machine timers
    tonArcStrikeTime : TON;
    tonMeltTime : TON;

    // Drop-Short Detection
    fVoltage_Derivative : REAL;
    fLastVoltage : REAL;
    tonDropShortDebounce : TON;
    bDropShortDetected : BOOL;

    // Constants
    NOMINAL_MELT_CURRENT : REAL := 25000.0; // Amps
    MAX_MELT_CURRENT : REAL := 30000.0;
    TARGET_GAP_MM : REAL := 15.0; // 15mm arc gap
    DROP_SHORT_V_THRES : REAL := 12.0; // Voltage drop threshold for short
END_VAR

//=============================================================================
// IMPLEMENTATION
//=============================================================================

// 1. SAFETY & DROP-SHORT DETECTION
IF bEStop THEN
    eState := STATE_FAULT_SCRAM;
    sFaultMessage := 'EMERGENCY STOP PRESSED';
END_IF

// Calculate dV/dt for rapid drop-short detection
fVoltage_Derivative := (fVoltage_Feedback_V - fLastVoltage) / 0.01; // Assuming 10ms cycle
fLastVoltage := fVoltage_Feedback_V;

IF (fVoltage_Feedback_V < DROP_SHORT_V_THRES) AND (eState >= STATE_MELT_CONTROL) THEN
    tonDropShortDebounce(IN:=TRUE, PT:=T#50MS);
    IF tonDropShortDebounce.Q THEN
        bDropShortDetected := TRUE;
    END_IF
ELSE
    tonDropShortDebounce(IN:=FALSE);
    bDropShortDetected := FALSE;
END_IF

// 2. RAM CONTROL & X-RAY GAP FEEDBACK
// Assuming fbGapControlPID uses X-Ray gap to determine ram speed
fbGapControlPID(
    Enable := (eState = STATE_MELT_CONTROL) AND NOT bDropShortDetected,
    Setpoint := TARGET_GAP_MM,
    Feedback := stXRayData.Gap_mm,
    Kp := 2.5,
    Ki := 0.5,
    Kd := 0.1,
    OutputMax := 10.0,
    OutputMin := -10.0
);

// Rapid Retraction Override
IF bDropShortDetected THEN
    fRamSpeed_Cmd_mmps := -50.0; // Extreme fast retract up
    bRamRetractFast := TRUE;
ELSE
    fRamSpeed_Cmd_mmps := fbGapControlPID.Output;
    bRamRetractFast := FALSE;
END_IF


// 3. STATE MACHINE
CASE eState OF

    STATE_STANDBY:
        fCommand_Current_A := 0.0;
        bHeliumValve_Z1 := FALSE;
        bHeliumValve_Z2 := FALSE;
        bHeliumValve_Z3 := FALSE;
        IF bStart_Melt THEN
            eState := STATE_EVACUATION;
        END_IF

    STATE_EVACUATION:
        // Assume external vacuum pumps are running
        IF stHeCooling.Pressure_mbar < 0.01 THEN
            eState := STATE_HELIUM_MATRIX_INIT;
        END_IF

    STATE_HELIUM_MATRIX_INIT:
        // Engage Helium Matrix Cooling for Copper Crucible
        bHeliumValve_Z1 := TRUE;
        bHeliumValve_Z2 := TRUE;
        bHeliumValve_Z3 := TRUE;

        IF (stHeCooling.Zone1_Flow_LPM > 50.0) AND 
           (stHeCooling.Zone2_Flow_LPM > 50.0) AND 
           (stHeCooling.Zone3_Flow_LPM > 50.0) THEN
            eState := STATE_STRIKE_ARC;
        END_IF

    STATE_STRIKE_ARC:
        // Apply initial strike voltage/current
        fCommand_Current_A := 5000.0; // Low strike current
        tonArcStrikeTime(IN:=TRUE, PT:=T#2S);

        IF (fCurrent_Feedback_A > 4000.0) AND tonArcStrikeTime.Q THEN
            tonArcStrikeTime(IN:=FALSE);
            eState := STATE_MELT_CONTROL;
        END_IF

    STATE_MELT_CONTROL:
        // Ramp up to nominal current, actively cooling crucible and maintaining gap
        fCommand_Current_A := NOMINAL_MELT_CURRENT;

        // Monitor crucible temps
        IF stHeCooling.Crucible_Temp_C[1] > 350.0 THEN
            eState := STATE_FAULT_SCRAM;
            sFaultMessage := 'CRUCIBLE OVERTEMP - BURN-THROUGH RISK';
        END_IF

        tonMeltTime(IN:=TRUE, PT:=T#5H); // Example 5 hour melt
        IF tonMeltTime.Q THEN
            eState := STATE_HOT_TOPPING;
        END_IF

    STATE_HOT_TOPPING:
        // Gradually reduce current to prevent pipe shrinkage in the ingot
        fCommand_Current_A := fCommand_Current_A - 10.0; // Ramp down logic placeholder
        IF fCommand_Current_A <= 0.0 THEN
            fCommand_Current_A := 0.0;
            eState := STATE_COOLING;
        END_IF

    STATE_COOLING:
        // Arc off, maintain helium cooling
        IF stHeCooling.Crucible_Temp_C[1] < 50.0 THEN
            bHeliumValve_Z1 := FALSE;
            bHeliumValve_Z2 := FALSE;
            bHeliumValve_Z3 := FALSE;
            eState := STATE_STANDBY;
        END_IF

    STATE_FAULT_SCRAM:
        // Dump power, rapid retract, flood argon/helium
        fCommand_Current_A := 0.0;
        fRamSpeed_Cmd_mmps := -100.0; // Max vertical escape speed
        bRamRetractFast := TRUE;
        bSystemFault := TRUE;
        bHeliumValve_Z1 := TRUE; // Max cooling
        bHeliumValve_Z2 := TRUE;
        bHeliumValve_Z3 := TRUE;

END_CASE

END_FUNCTION_BLOCK
```

FUNCTION_BLOCK FB_3S_Gondola_Drive_Controller
TITLE = '3S Gondola Advanced Drive Controller'
VERSION : '2.0'
AUTHOR : 'Lumina Elite Architect'

VAR_INPUT
    bSystemEnable : BOOL; // System run command
    rMainDriveSpeedRef : REAL; // Nominal line speed [m/s]
    rDriveBullwheelVelocity : REAL; // Actual velocity of drive bullwheel [m/s]
    rIdlerBullwheelVelocity : REAL; // Actual velocity of return bullwheel [m/s]
    rWindSpeed : REAL; // Measured cross-wind speed [m/s]
    rRopeOscillationAmplitude : REAL; // Amplitude of rope oscillation [m]
    bCabinEnteringStation : BOOL; // Sensor trigger for cabin entry
    rCabinPositionInStation : REAL; // Distance cabin has travelled in station [m]
    rHydraulicPressureFeedback : REAL; // Tire conveyor hydraulic pressure [bar]
END_VAR

VAR_OUTPUT
    rMainDriveSpeedCmd : REAL; // Speed command to main drive VFD [m/s]
    rMainDriveTorqueLimit : REAL; // Torque limit command [%]
    rTireConveyorSpeedCmd : REAL; // Hydraulic tire conveyor speed [m/s]
    bEmergencyBrake : BOOL; // Trigger service/emergency brake
    bSlipWarning : BOOL; // Bullwheel slip detected
    bWindAlarm : BOOL; // High wind alarm
END_VAR

VAR
    rFilteredWindSpeed : REAL;
    rSlipRatio : REAL;
    rStationDecelProfile : REAL;
    rOscillationDampingFactor : REAL;
    rDynamicSpeedLimit : REAL;

    // Internal States for Decel Profiling
    rEntryVelocity : REAL;
    bStationProfileActive : BOOL;

    // Timers
    tonSlipDelay : TON;
    tonWindAlarm : TON;
END_VAR

VAR CONSTANT
    MAX_SLIP_TOLERANCE : REAL := 0.02; // 2% max slip
    MAX_WIND_SPEED : REAL := 25.0; // 25 m/s wind limit
    CRITICAL_WIND_SPEED : REAL := 30.0;
    STATION_LENGTH : REAL := 15.0; // 15m decel zone
    STATION_CREEP_SPEED : REAL := 0.5; // 0.5 m/s
    TIRE_NOMINAL_PRESSURE : REAL := 120.0;
END_VAR

BEGIN
    IF NOT bSystemEnable THEN
        rMainDriveSpeedCmd := 0.0;
        rTireConveyorSpeedCmd := 0.0;
        bEmergencyBrake := TRUE;
        bStationProfileActive := FALSE;
        RETURN;
    END_IF;

    bEmergencyBrake := FALSE;

    // 1. Bullwheel Traction Friction Monitoring (Slip Detection)
    // Compares drive bullwheel speed with idler bullwheel speed to detect slippage
    IF rDriveBullwheelVelocity > 0.5 THEN
        rSlipRatio := ABS(rDriveBullwheelVelocity - rIdlerBullwheelVelocity) / rDriveBullwheelVelocity;
    ELSE
        rSlipRatio := 0.0;
    END_IF;

    tonSlipDelay(IN := (rSlipRatio > MAX_SLIP_TOLERANCE), PT := T#500ms);
    bSlipWarning := (rSlipRatio > MAX_SLIP_TOLERANCE * 0.5);

    IF tonSlipDelay.Q THEN
        bEmergencyBrake := TRUE; // Rope slip exceeds safe limits! Execute emergency stop.
    END_IF;

    // 2. Wind Speed & Rope Oscillation Dampening
    // Simple low-pass filter for wind speed measurements
    rFilteredWindSpeed := rFilteredWindSpeed + 0.1 * (rWindSpeed - rFilteredWindSpeed);

    tonWindAlarm(IN := rFilteredWindSpeed > MAX_WIND_SPEED, PT := T#3s);
    bWindAlarm := tonWindAlarm.Q;

    IF rFilteredWindSpeed > CRITICAL_WIND_SPEED THEN
        bEmergencyBrake := TRUE; // Wind exceeds ultimate safety limits
    END_IF;

    // Dynamic Speed Reduction based on wind and rope oscillation
    rOscillationDampingFactor := 1.0 - LIMIT(MN:=0.0, IN:=(rRopeOscillationAmplitude * 0.5), MX:=0.5);
    rDynamicSpeedLimit := rMainDriveSpeedRef;

    IF bWindAlarm THEN
        rDynamicSpeedLimit := rMainDriveSpeedRef * 0.4; // Reduce line speed to 40% in high winds
    END_IF;

    rMainDriveSpeedCmd := MIN(rMainDriveSpeedRef, rDynamicSpeedLimit) * rOscillationDampingFactor;

    // During high oscillation, limit torque to avoid inducing resonance in the tricable span
    rMainDriveTorqueLimit := LIMIT(MN:=50.0, IN:=100.0 - (rRopeOscillationAmplitude * 20.0), MX:=100.0);

    // 3. Station Entry Deceleration Profiling (Hydraulic Tire Conveyors)
    IF bCabinEnteringStation AND NOT bStationProfileActive THEN
        bStationProfileActive := TRUE;
        rEntryVelocity := rMainDriveSpeedCmd; // Capture incoming velocity for the deceleration profile
    END_IF;

    IF bStationProfileActive THEN
        IF rCabinPositionInStation >= STATION_LENGTH THEN
            rStationDecelProfile := STATION_CREEP_SPEED;
            bStationProfileActive := FALSE; // Reset profile once station transit completes
        ELSE
            // Deceleration calculation using an S-Curve / quadratic reduction for passenger comfort
            rStationDecelProfile := rEntryVelocity - (rEntryVelocity - STATION_CREEP_SPEED) * 
                                    EXPT((rCabinPositionInStation / STATION_LENGTH), 2.0);
        END_IF;

        // Hydraulic pressure compensation: If pressure drops, boost the speed command slightly to maintain required tire torque
        IF rHydraulicPressureFeedback < TIRE_NOMINAL_PRESSURE AND rHydraulicPressureFeedback > 50.0 THEN
            rTireConveyorSpeedCmd := rStationDecelProfile * (TIRE_NOMINAL_PRESSURE / rHydraulicPressureFeedback);
        ELSE
            rTireConveyorSpeedCmd := rStationDecelProfile;
        END_IF;
    ELSE
        rTireConveyorSpeedCmd := STATION_CREEP_SPEED;
    END_IF;

END_FUNCTION_BLOCK

As a Lead Process Engineer, the transition from a simple PID pressure loop to a comprehensive Reverse Osmosis (RO) High-Pressure Controller is one of the most critical upgrades for a massive desalination plant. We're moving from basic feedback control to a multivariable, predictive, and state-machine-driven architecture. 

The three primary challenges we must address are:
1. **ERD Synchronization**: The Energy Recovery Device (like an isobaric PX or DWEER) recycles up to 98% of the brine pressure. The high-pressure pump (HPP) and ERD booster pump must work in tandem to maintain constant membrane feed pressure despite ERD chamber switching dynamics.
2. **Valve Sequencing (Water Hammer Prevention)**: Rapid transitions in the isobaric chambers can cause destructive transients (water hammer). Precise overlapping of active/inactive chamber valves is required.
3. **TMP Monitoring**: Trans-Membrane Pressure (TMP) must be continuously calculated and normalized to detect early signs of scaling or bio-fouling, triggering preventative alarms or CIP (Clean-In-Place) sequences.

Here is the Enterprise-Grade IEC 61131-3 Structured Text implementation for this complex controller.

### IEC 61131-3 Structured Text Implementation

```iecst
(* 
   =============================================================================
   FUNCTION BLOCK: FB_RO_HighPressureController
   DESCRIPTION: 
     Advanced controller for Reverse Osmosis High-Pressure Loop integrating:
     - HPP (High Pressure Pump) and Booster Pump VFD PID control.
     - ERD (Energy Recovery Device) Isobaric Chamber Sequencing.
     - TMP (Trans-Membrane Pressure) Monitoring & Fouling Detection.
     - Water hammer prevention through ramp-rate limiting and valve overlap.
   ============================================================================= 
*)

FUNCTION_BLOCK FB_RO_HighPressureController
VAR_INPUT
    // Enable & Setpoints
    bEnable                 : BOOL;      // Controller Enable
    rFeedPressSetpoint      : REAL;      // Target RO Feed Pressure (bar)
    rMaxRampRate            : REAL;      // Maximum pressure ramp rate (bar/sec)

    // Process Inputs (Sensors)
    rSensFeedPress          : REAL;      // Actual RO Feed Pressure (bar)
    rSensBrinePress         : REAL;      // Brine Pressure leaving RO (bar)
    rSensPermeatePress      : REAL;      // Permeate (Product) Pressure (bar)
    rSensFeedFlow           : REAL;      // Total Feed Flow (m3/h)
    rSensTemperature        : REAL;      // Feed Water Temp (Celsius)

    // ERD Valve Status (Isobaric Chambers A & B)
    bValveA_InletOpened     : BOOL;
    bValveA_InletClosed     : BOOL;
    bValveB_InletOpened     : BOOL;
    bValveB_InletClosed     : BOOL;

    // System Parameters
    rBaselineTMP            : REAL;      // Clean membrane TMP (bar)
    rMaxTMP_Deviation       : REAL;      // Alarm threshold for fouling (bar)
END_VAR

VAR_OUTPUT
    // Pump VFD Control Signals (0.0 - 100.0 %)
    rVfdHighPressurePump    : REAL;      
    rVfdBoosterPump         : REAL;      

    // ERD Valve Control Signals
    bCmdValveA_Inlet        : BOOL;
    bCmdValveB_Inlet        : BOOL;

    // Alarms and Status
    bAlrmWaterHammerRisk    : BOOL;
    bAlrmMembraneFouling    : BOOL;
    bAlrmPressureDeviation  : BOOL;
    rCurrentTMP             : REAL;      // Calculated Normalized TMP
    iState                  : INT;       // 0:Off, 1:RampUp, 2:SyncERD, 3:Steady
END_VAR

VAR
    // PID Instances
    pidHPP                  : FB_PID_Advanced; 
    pidBooster              : FB_PID_Advanced;

    // State Management & Timers
    tonValveOverlap         : TON;       // Timer for valve overlap sequencing
    rInternalSetpoint       : REAL;      // Ramp-limited internal setpoint
    rPrevFeedPress          : REAL;      // For dP/dt calculation (hammer check)

    // Sequencing State Machine
    eErdState               : INT;       // 0:INIT, 1:CHAMBER_A_ACTIVE, 2:TRANSITION_A_TO_B, 3:CHAMBER_B_ACTIVE, 4:TRANSITION_B_TO_A

    // Internal calculations
    rDeltaPress             : REAL;
    rTempCorrection         : REAL;
END_VAR

(* =======================================================================
   1. PRESSURE RAMPING & SETPOINT GENERATION
   ======================================================================= *)
IF NOT bEnable THEN
    rInternalSetpoint := 0.0;
    rVfdHighPressurePump := 0.0;
    rVfdBoosterPump := 0.0;
    bCmdValveA_Inlet := FALSE;
    bCmdValveB_Inlet := FALSE;
    iState := 0;
    eErdState := 0;
    RETURN;
END_IF;

// Ramp the internal setpoint to prevent sudden shocks to the membranes
IF rInternalSetpoint < rFeedPressSetpoint THEN
    rInternalSetpoint := rInternalSetpoint + (rMaxRampRate * 0.01); // Assuming 10ms cycle
    IF rInternalSetpoint > rFeedPressSetpoint THEN
        rInternalSetpoint := rFeedPressSetpoint;
    END_IF;
ELSIF rInternalSetpoint > rFeedPressSetpoint THEN
    rInternalSetpoint := rInternalSetpoint - (rMaxRampRate * 0.01);
    IF rInternalSetpoint < rFeedPressSetpoint THEN
        rInternalSetpoint := rFeedPressSetpoint;
    END_IF;
END_IF;

(* =======================================================================
   2. HPP AND BOOSTER PUMP PID CONTROL
   ======================================================================= *)
// High Pressure Pump PID handles the bulk pressure requirement (Primary)
pidHPP.SetPoint := rInternalSetpoint;
pidHPP.ProcessVariable := rSensFeedPress;
pidHPP.Kp := 2.5; 
pidHPP.Ki := 0.8;
pidHPP.Kd := 0.1;
pidHPP();
rVfdHighPressurePump := pidHPP.Output;

// Booster Pump PID handles the pressure deficit after the ERD (Secondary/Trim)
// The target for booster is to match the HPP output pressure to ensure smooth mixing
pidBooster.SetPoint := rSensFeedPress; 
pidBooster.ProcessVariable := rSensBrinePress; // ERD input is roughly Brine pressure
pidBooster.Kp := 1.5;
pidBooster.Ki := 1.2; // Faster integral to catch ERD switching dips
pidBooster.Kd := 0.05;
pidBooster();
rVfdBoosterPump := pidBooster.Output;

(* =======================================================================
   3. ISOBARIC CHAMBER VALVE SEQUENCING (WATER HAMMER PREVENTION)
   ======================================================================= *)
// Calculate Rate of Change of Pressure (dP/dt)
rDeltaPress := rSensFeedPress - rPrevFeedPress;
rPrevFeedPress := rSensFeedPress;

// Trigger Water Hammer Risk Alarm if dP/dt is excessively high
IF ABS(rDeltaPress) > (rMaxRampRate * 1.5 * 0.01) THEN
    bAlrmWaterHammerRisk := TRUE;
ELSE
    bAlrmWaterHammerRisk := FALSE;
END_IF;

// ERD Sequencing State Machine
CASE eErdState OF
    0: (* INIT *)
        bCmdValveA_Inlet := TRUE;
        bCmdValveB_Inlet := FALSE;
        IF bValveA_InletOpened AND (rSensFeedPress > 10.0) THEN
            eErdState := 1;
        END_IF;

    1: (* CHAMBER_A_ACTIVE *)
        // Based on volumetric timing or piston stroke sensors (simulated as time here)
        tonValveOverlap(IN := TRUE, PT := T#5s);
        IF tonValveOverlap.Q THEN
            eErdState := 2;
            tonValveOverlap(IN := FALSE); // Reset timer
        END_IF;

    2: (* TRANSITION_A_TO_B *)
        // Open Valve B BEFORE closing Valve A (Make-Before-Break)
        bCmdValveB_Inlet := TRUE;
        IF bValveB_InletOpened THEN
            bCmdValveA_Inlet := FALSE; // Safe to close A
            eErdState := 3;
        END_IF;

    3: (* CHAMBER_B_ACTIVE *)
        tonValveOverlap(IN := TRUE, PT := T#5s);
        IF tonValveOverlap.Q THEN
            eErdState := 4;
            tonValveOverlap(IN := FALSE);
        END_IF;

    4: (* TRANSITION_B_TO_A *)
        // Open Valve A BEFORE closing Valve B
        bCmdValveA_Inlet := TRUE;
        IF bValveA_InletOpened THEN
            bCmdValveB_Inlet := FALSE;
            eErdState := 1;
        END_IF;
END_CASE;

(* =======================================================================
   4. TMP (TRANS-MEMBRANE PRESSURE) MONITORING
   ======================================================================= *)
// TMP = [ (FeedPress + BrinePress)/2 ] - PermeatePress
rCurrentTMP := ((rSensFeedPress + rSensBrinePress) / 2.0) - rSensPermeatePress;

// Temperature Normalization (viscosity of water changes with temperature)
// Baseline typically 25C. Correction factor ~3% per degree C.
rTempCorrection := EXP(2640.0 * (1.0/(rSensTemperature + 273.15) - 1.0/298.15));
rCurrentTMP := rCurrentTMP * rTempCorrection;

// Fouling Detection (Check deviation from Baseline)
IF (rCurrentTMP - rBaselineTMP) > rMaxTMP_Deviation THEN
    bAlrmMembraneFouling := TRUE;
ELSE
    bAlrmMembraneFouling := FALSE;
END_IF;

// Feed Pressure Deviation Alarm
IF (ABS(rSensFeedPress - rInternalSetpoint) > (rFeedPressSetpoint * 0.10)) AND (rInternalSetpoint = rFeedPressSetpoint) THEN
    bAlrmPressureDeviation := TRUE;
ELSE
    bAlrmPressureDeviation := FALSE;
END_IF;

// Determine Overall Controller State
IF rInternalSetpoint < rFeedPressSetpoint THEN
    iState := 1; // Ramp Up
ELSIF (rInternalSetpoint = rFeedPressSetpoint) AND NOT bAlrmPressureDeviation THEN
    iState := 3; // Steady State
ELSE
    iState := 2; // Stabilizing / ERD Sync active
END_IF;

END_FUNCTION_BLOCK
```

### Engineering Design Notes:
1. **Ramp Rate Limitation**: The `rMaxRampRate` ensures the HPP does not shock the membrane, which can cause compaction or mechanical failure of the membrane leaves.
2. **Dual-PID Architecture**: The system uses two PIDs. The HPP dictates total mass flow and initial pressure, while the Booster Pump acts as a trim controller matching its output pressure to the HPP output to minimize the mixing pressure differential.
3. **Make-Before-Break Valve Logic**: Water is virtually incompressible. Closing a valve before opening the next causes a massive pressure spike (Water Hammer). The `TRANSITION` states ensure the incoming chamber's valve is fully open before the outgoing chamber's valve is commanded closed.
4. **TMP Normalization**: Raw TMP is highly susceptible to feed water temperature variations. We employ an Arrhenius-based viscosity correction formula to normalize TMP to a standard 25°C, ensuring that winter/summer temperature swings do not trigger false fouling alarms.

Here is the complete, production-ready IEC 61131-3 Structured Text implementation for the TBM Earth Pressure Balance (EPB) Controller. 

This `FB_TBM_EPB_Controller` block addresses all your requirements:
1. **Face Pressure PID Regulation**: Implements a reverse-acting PID loop to regulate the extraction rate of the screw conveyor based on redundant pressure sensors on the cutting face. It includes anti-windup clamping.
2. **Cutterhead Load Sharing**: Distributes the global torque command symmetrically across four individual VFDs for the multi-drive array.
3. **Ring Erector Sequencer**: Contains a discrete state machine governing the hydraulic sequence to grip, transport, position, place, and release concrete segments.

```iecst
FUNCTION_BLOCK FB_TBM_EPB_Controller
TITLE = 'Tunnel Boring Machine - Earth Pressure Balance Controller'
AUTHOR : 'Lumina Elite Systems'
VERSION : '3.1.0'
//-----------------------------------------------------------------------------
// Description:
// Highly complex production-ready controller for TBM EPB mode.
// 1. Earth face pressure regulation via screw conveyor speed (PID).
// 2. Cutterhead multi-drive torque distribution (4 motors).
// 3. Concrete segment ring erector state machine & hydraulic sequencing.
//-----------------------------------------------------------------------------

VAR_INPUT
    // System Master Control
    xEnable                  : BOOL; // System master enable
    xEmergencyStop           : BOOL; // E-Stop active (NC, FALSE = Stop)

    // Face Pressure Control (PID)
    rFacePressureTarget      : REAL; // Target face pressure (bar)
    rFacePressureActual1     : REAL; // Sensor 1 actual pressure (bar)
    rFacePressureActual2     : REAL; // Sensor 2 actual pressure (bar)
    rPID_Kp                  : REAL := 15.0; // Proportional Gain
    rPID_Ki                  : REAL := 2.5;  // Integral Gain
    rPID_Kd                  : REAL := 0.5;  // Derivative Gain
    rPID_CycleTime           : REAL := 0.05; // 50ms controller sampling

    // Cutterhead Motors
    rCutterheadSpeedSetpt    : REAL; // Target RPM
    rCutterheadTotalTorque   : REAL; // Required total torque (kNm)

    // Ring Erector
    xErectorStartSeq         : BOOL; // Start placement sequence trigger
    xRingSegmentGripped      : BOOL; // Sensor: Segment securely gripped
    xRingPositionReached     : BOOL; // Sensor: Desired radial/axial pos reached
    xHydraulicPressureOk     : BOOL; // Sensor: Erector hydraulic system nominal
END_VAR

VAR_OUTPUT
    // Screw Conveyor
    rScrewConveyorSpeedRef   : REAL; // RPM reference for VFD (0.0 to 100.0%)

    // Cutterhead Drives (4x Motors)
    rMotor1TorqueRef         : REAL; // Torque ref Motor 1 (kNm)
    rMotor2TorqueRef         : REAL; // Torque ref Motor 2 (kNm)
    rMotor3TorqueRef         : REAL; // Torque ref Motor 3 (kNm)
    rMotor4TorqueRef         : REAL; // Torque ref Motor 4 (kNm)

    // Ring Erector Sequencer
    xErectorHydraulicPumpEn  : BOOL; // Enable hydraulic pump contactor
    xErectorCylinderExtend   : BOOL; // Valve: Extend placement cylinder
    xErectorRotatorEnable    : BOOL; // Valve: Enable erector rotation
    xErectorVacuumRelease    : BOOL; // Valve: Release segment vacuum pad
    iErectorState            : INT;  // Current sequence step output

    // System Alarms
    xFacePressureAlarm       : BOOL; // Face pressure out of tolerance
    xSystemFault             : BOOL; // General system fault latch
END_VAR

VAR
    // PID Internal State
    rFacePressureAvg         : REAL;
    rError                   : REAL;
    rLastError               : REAL;
    rIntegral                : REAL;
    rDerivative              : REAL;

    // Erector State Machine
    eErectorState            : INT;
    tErectorTimer            : TON; // Standard IEC timer
END_VAR

VAR CONSTANT
    // State Machine Constants
    STATE_IDLE               : INT := 0;
    STATE_PUMP_START         : INT := 10;
    STATE_GRIP_CHECK         : INT := 20;
    STATE_MOVE_POSITION      : INT := 30;
    STATE_PLACE_SEGMENT      : INT := 40;
    STATE_RELEASE_VACUUM     : INT := 50;
    STATE_RETRACT_CYLINDER   : INT := 60;
    STATE_COMPLETE           : INT := 100;
    STATE_FAULT              : INT := 999;
END_VAR

BEGIN
    //=========================================================================
    // 0. Safety Interlocks and Master Control
    //=========================================================================
    // If Emergency Stop is pressed (FALSE) or system disabled, safe state all outputs
    IF NOT xEmergencyStop OR NOT xEnable THEN
        rScrewConveyorSpeedRef := 0.0;

        rMotor1TorqueRef := 0.0;
        rMotor2TorqueRef := 0.0;
        rMotor3TorqueRef := 0.0;
        rMotor4TorqueRef := 0.0;

        xErectorHydraulicPumpEn := FALSE;
        xErectorCylinderExtend  := FALSE;
        xErectorRotatorEnable   := FALSE;
        xErectorVacuumRelease   := FALSE;

        iErectorState := STATE_IDLE;
        eErectorState := STATE_IDLE;

        // Indicate fault if it was an E-Stop
        xSystemFault := NOT xEmergencyStop;
        RETURN;
    END_IF;

    //=========================================================================
    // 1. Face Pressure Regulation (Screw Conveyor PID)
    //=========================================================================
    // Average reading of redundancy sensors to prevent noise/failure spikes
    rFacePressureAvg := (rFacePressureActual1 + rFacePressureActual2) / 2.0;

    // Alarm generation: Deviation > 0.5 bar from target
    xFacePressureAlarm := ABS(rFacePressureTarget - rFacePressureAvg) > 0.5;

    // Reverse-Acting PID Calculation
    // Logic: If face pressure is higher than target, we have too much muck.
    // We must INCREASE screw conveyor speed to extract more material.
    rError := rFacePressureAvg - rFacePressureTarget; 

    // Integral Term with Anti-Windup Clamping
    rIntegral := rIntegral + (rError * rPID_CycleTime);
    IF rIntegral > 100.0 THEN rIntegral := 100.0; END_IF;
    IF rIntegral < -100.0 THEN rIntegral := -100.0; END_IF;

    // Derivative Term
    rDerivative := (rError - rLastError) / rPID_CycleTime;
    rLastError := rError;

    // Control Variable (Screw VFD Reference in %)
    rScrewConveyorSpeedRef := (rPID_Kp * rError) + (rPID_Ki * rIntegral) + (rPID_Kd * rDerivative);

    // Output saturation limits (0.0% to 100.0%)
    IF rScrewConveyorSpeedRef > 100.0 THEN
        rScrewConveyorSpeedRef := 100.0;
    ELSIF rScrewConveyorSpeedRef < 0.0 THEN
        rScrewConveyorSpeedRef := 0.0;
    END_IF;

    //=========================================================================
    // 2. Cutterhead Multi-Drive Torque Distribution
    //=========================================================================
    // Assuming identical AC drives, symmetrically distribute requested torque.
    // In advanced designs, this section would dynamically trim refs based on
    // individual motor stator current feedback or slip.
    IF rCutterheadSpeedSetpt > 0.0 THEN
        rMotor1TorqueRef := rCutterheadTotalTorque * 0.25;
        rMotor2TorqueRef := rCutterheadTotalTorque * 0.25;
        rMotor3TorqueRef := rCutterheadTotalTorque * 0.25;
        rMotor4TorqueRef := rCutterheadTotalTorque * 0.25;
    ELSE
        rMotor1TorqueRef := 0.0;
        rMotor2TorqueRef := 0.0;
        rMotor3TorqueRef := 0.0;
        rMotor4TorqueRef := 0.0;
    END_IF;

    //=========================================================================
    // 3. Ring Erector Hydraulic Sequencing State Machine
    //=========================================================================
    CASE eErectorState OF
        STATE_IDLE:
            xErectorHydraulicPumpEn := FALSE;
            xErectorCylinderExtend  := FALSE;
            xErectorRotatorEnable   := FALSE;
            xErectorVacuumRelease   := FALSE;

            // Wait for rising edge of start command
            IF xErectorStartSeq THEN
                eErectorState := STATE_PUMP_START;
            END_IF;

        STATE_PUMP_START:
            // Spin up HPU and check for nominal pressure
            xErectorHydraulicPumpEn := TRUE;
            IF xHydraulicPressureOk THEN
                eErectorState := STATE_GRIP_CHECK;
            END_IF;

        STATE_GRIP_CHECK:
            // Ensure vacuum pads have securely clamped the segment before moving
            IF xRingSegmentGripped THEN
                eErectorState := STATE_MOVE_POSITION;
            ELSE
                eErectorState := STATE_FAULT;
            END_IF;

        STATE_MOVE_POSITION:
            // Rotate erector arm to designated installation coordinate
            xErectorRotatorEnable := TRUE;
            IF xRingPositionReached THEN
                xErectorRotatorEnable := FALSE;
                eErectorState := STATE_PLACE_SEGMENT;
            END_IF;

        STATE_PLACE_SEGMENT:
            // Extend main hydraulic ram to press segment into tail skin
            xErectorCylinderExtend := TRUE;
            tErectorTimer(IN := TRUE, PT := T#5S);
            IF tErectorTimer.Q THEN
                tErectorTimer(IN := FALSE);
                eErectorState := STATE_RELEASE_VACUUM;
            END_IF;

        STATE_RELEASE_VACUUM:
            // Open vent valves to drop segment vacuum lock
            xErectorVacuumRelease := TRUE;
            tErectorTimer(IN := TRUE, PT := T#2S);
            IF tErectorTimer.Q THEN
                tErectorTimer(IN := FALSE);
                eErectorState := STATE_RETRACT_CYLINDER;
            END_IF;

        STATE_RETRACT_CYLINDER:
            // Retract ram, leaving segment in place
            xErectorCylinderExtend := FALSE;
            xErectorVacuumRelease  := FALSE;
            tErectorTimer(IN := TRUE, PT := T#4S);
            IF tErectorTimer.Q THEN
                tErectorTimer(IN := FALSE);
                eErectorState := STATE_COMPLETE;
            END_IF;

        STATE_COMPLETE:
            // Power down HPU and wait for operator to drop start signal
            xErectorHydraulicPumpEn := FALSE;
            IF NOT xErectorStartSeq THEN
                eErectorState := STATE_IDLE; 
            END_IF;

        STATE_FAULT:
            // Safe-state all actuators due to sequence anomaly
            xErectorHydraulicPumpEn := FALSE;
            xErectorCylinderExtend  := FALSE;
            xErectorRotatorEnable   := FALSE;
            xSystemFault := TRUE;

            // Require operator to clear the start command to reset fault
            IF NOT xErectorStartSeq THEN
                xSystemFault  := FALSE;
                eErectorState := STATE_IDLE;
            END_IF;

        ELSE
            eErectorState := STATE_IDLE;
    END_CASE;

    // Write internal state to output interface for HMI/SCADA
    iErectorState := eErectorState;

END_FUNCTION_BLOCK
```

﻿FUNCTION_BLOCK "Offshore_Wind_Turbine_Controller"
TITLE = Advanced Offshore Wind Turbine Control
{ S7_Optimized_Access := 'TRUE' }
AUTHOR : Lumina_Elite
VERSION : 2.0
   VAR_INPUT 
      ir_Sonic_Anemometer_Wind_Speed : Real; // Wind speed from sonic anemometer [m/s]
      ir_Sonic_Anemometer_Wind_Dir : Real;   // Wind direction 0-359.9 degrees
      ir_Nacelle_Heading : Real;             // Current nacelle heading 0-359.9 degrees
      ir_Rotor_Speed : Real;                 // Rotor speed [RPM]
      ir_Grid_Demand_Active_Power : Real;    // Grid demand [kW]
      ir_Blade_1_Pitch_Fb : Real;            // Blade 1 pitch feedback [degrees]
      ir_Blade_2_Pitch_Fb : Real;            // Blade 2 pitch feedback [degrees]
      ir_Blade_3_Pitch_Fb : Real;            // Blade 3 pitch feedback [degrees]
      ir_Hydraulic_Accumulator_Pressure : Real; // System pressure [bar]
      ib_Wind_Gust_Detected : Bool;          // High-speed wind gust trigger
      ib_Emergency_Stop : Bool;              // E-stop safety circuit
   END_VAR

   VAR_OUTPUT 
      or_Yaw_Motor_Cmd : Real;               // Yaw drive command [-100.0 to 100.0 %]
      ob_Yaw_Brake_Cmd : Bool;               // Yaw mechanical brake
      or_Blade_1_Pitch_Cmd : Real;           // Blade 1 pitch command [degrees]
      or_Blade_2_Pitch_Cmd : Real;           // Blade 2 pitch command [degrees]
      or_Blade_3_Pitch_Cmd : Real;           // Blade 3 pitch command [degrees]
      or_Generator_Torque_Cmd : Real;        // Generator torque setpoint [Nm]
      ob_Hydraulic_Pump_Cmd : Bool;          // Hydraulic accumulator pump command
   END_VAR

   VAR
      // Instantiated PID/PI Controllers
      inst_Yaw_PID : "fb_PID-Control_V18.0.2";
      inst_Pitch_PID_1 : "fb_PID-Control_V18.0.2";
      inst_Pitch_PID_2 : "fb_PID-Control_V18.0.2";
      inst_Pitch_PID_3 : "fb_PID-Control_V18.0.2";
      inst_Torque_PI : "fb_PI-Control_V18.0.1";

      stat_Yaw_Error : Real;
      stat_Calculated_Rotor_Speed_Setpt : Real;
      stat_Pitch_Setpoint : Real;
   END_VAR

   VAR CONSTANT
      Optimal_TSR : Real := 7.5;          // Ideal Tip Speed Ratio
      Rotor_Radius : Real := 80.0;        // Rotor radius [m]
      Pi_Value : Real := 3.14159265;
      Max_Pitch_Angle : Real := 90.0;     // Full feather
      Min_Pitch_Angle : Real := 0.0;      // Max power extraction
      Max_Torque : Real := 50000.0;       // Nm max torque limit
   END_VAR

BEGIN
    // =======================================================================
    // 1. YAW RING ACTIVE TRACKING BASED ON SONIC ANEMOMETER
    // =======================================================================
    // Calculate shortest path for yaw error over 360 degree compass
    #stat_Yaw_Error := #ir_Sonic_Anemometer_Wind_Dir - #ir_Nacelle_Heading;

    IF #stat_Yaw_Error > 180.0 THEN
        #stat_Yaw_Error := #stat_Yaw_Error - 360.0;
    ELSIF #stat_Yaw_Error < -180.0 THEN
        #stat_Yaw_Error := #stat_Yaw_Error + 360.0;
    END_IF;

    // Apply 2-degree deadband to prevent continuous yaw motor oscillation and wear
    IF ABS(#stat_Yaw_Error) < 2.0 THEN
        #ob_Yaw_Brake_Cmd := TRUE;
        #or_Yaw_Motor_Cmd := 0.0;
    ELSE
        #ob_Yaw_Brake_Cmd := FALSE;
        // Yaw control is heavily damped to avoid gyroscopic loading
        #inst_Yaw_PID(ir_Input := 0.0,
                ir_Setpoint := #stat_Yaw_Error,
                ir_ProportionalGain := 5.0,
                ir_IntegrationGain := 0.5,
                ir_DerviateGain := 2.0,
                ir_DerivateActionTime := 0.1,
                or_Output => #or_Yaw_Motor_Cmd);
    END_IF;

    // =======================================================================
    // 2. INDIVIDUAL BLADE PITCH CONTROL & HYDRAULIC ACCUMULATORS
    // =======================================================================
    // Monitor and charge hydraulic accumulators used for rapid pitching
    IF #ir_Hydraulic_Accumulator_Pressure < 180.0 THEN
        #ob_Hydraulic_Pump_Cmd := TRUE;
    ELSIF #ir_Hydraulic_Accumulator_Pressure > 210.0 THEN
        #ob_Hydraulic_Pump_Cmd := FALSE;
    END_IF;

    // Fast-response load shedding via collective/individual pitch
    IF #ib_Wind_Gust_Detected OR #ib_Emergency_Stop THEN
        #stat_Pitch_Setpoint := #Max_Pitch_Angle; // Instantly feather blades
    ELSE
        // Normal pitch schedule: below rated wind speed (11 m/s), optimize for capture
        IF #ir_Sonic_Anemometer_Wind_Speed < 11.0 THEN
            #stat_Pitch_Setpoint := #Min_Pitch_Angle;
        ELSE
            // Above rated, pitch out to shed excess aerodynamic power
            #stat_Pitch_Setpoint := (#ir_Sonic_Anemometer_Wind_Speed - 11.0) * 4.5;
        END_IF;

        IF #stat_Pitch_Setpoint > #Max_Pitch_Angle THEN 
            #stat_Pitch_Setpoint := #Max_Pitch_Angle; 
        END_IF;
    END_IF;

    // Execute Individual Pitch Control (IPC) to alleviate asymmetric rotor loading
    #inst_Pitch_PID_1(ir_Input := #ir_Blade_1_Pitch_Fb, ir_Setpoint := #stat_Pitch_Setpoint, ir_ProportionalGain := 15.0, ir_IntegrationGain := 1.0, ir_DerviateGain := 0.5, ir_DerivateActionTime := 0.05, or_Output => #or_Blade_1_Pitch_Cmd);
    #inst_Pitch_PID_2(ir_Input := #ir_Blade_2_Pitch_Fb, ir_Setpoint := #stat_Pitch_Setpoint, ir_ProportionalGain := 15.0, ir_IntegrationGain := 1.0, ir_DerviateGain := 0.5, ir_DerivateActionTime := 0.05, or_Output => #or_Blade_2_Pitch_Cmd);
    #inst_Pitch_PID_3(ir_Input := #ir_Blade_3_Pitch_Fb, ir_Setpoint := #stat_Pitch_Setpoint, ir_ProportionalGain := 15.0, ir_IntegrationGain := 1.0, ir_DerviateGain := 0.5, ir_DerivateActionTime := 0.05, or_Output => #or_Blade_3_Pitch_Cmd);

    // =======================================================================
    // 3. GENERATOR TORQUE CONTROL FOR OPTIMAL TIP-SPEED RATIO
    // =======================================================================
    // Calculate ideal rotor speed to maintain optimum TSR for current wind speed
    // TSR = (Rotor_Speed * pi / 30 * Rotor_Radius) / Wind_Speed
    IF #ir_Sonic_Anemometer_Wind_Speed > 3.0 THEN
        #stat_Calculated_Rotor_Speed_Setpt := (#Optimal_TSR * #ir_Sonic_Anemometer_Wind_Speed * 30.0) / (#Pi_Value * #Rotor_Radius);
    ELSE
        #stat_Calculated_Rotor_Speed_Setpt := 0.0;
    END_IF;

    #inst_Torque_PI(ir_Input := #ir_Rotor_Speed,
              ir_Setpoint := #stat_Calculated_Rotor_Speed_Setpt,
              ir_ProportionalGain := 5000.0,
              ir_IntegrationGain := 200.0,
              or_Output => #or_Generator_Torque_Cmd);

    // Limit torque command against maximum rating and invert limits
    IF #or_Generator_Torque_Cmd > #Max_Torque THEN
        #or_Generator_Torque_Cmd := #Max_Torque;
    ELSIF #or_Generator_Torque_Cmd < 0.0 THEN
        #or_Generator_Torque_Cmd := 0.0;
    END_IF;

END_FUNCTION_BLOCK

