FUNCTION_BLOCK ACAS_X_CORE
VAR_INPUT
    Ownship_Alt         : REAL;   (* Ownship Altitude (MSL in feet) *)
    Ownship_Vert_Rate   : REAL;   (* Ownship Vertical Rate (ft/min) *)

    (* Mode S Transponder Interface *)
    Targets             : ARRAY[1..10] OF MODE_S_TARGET; 

    (* TAWS Interlock Interface *)
