END_VAR

VAR_OUTPUT
    System_Status       : STRING[20];
    Highest_Threat      : ACAS_ADVISORY_TYPE;
    Commanded_V_Speed   : REAL;   (* Recommended Vertical Speed in ft/min *)
    Aural_Warning       : STRING[50];
END_VAR

VAR
    i                   : INT;
    Tau                 : REAL;   (* Time to closest point of approach (seconds) *)
    Current_Advisory    : ACAS_ADVISORY_TYPE;
    Most_Critical_Tau   : REAL;

    (* Configurable Thresholds *)
    TA_TAU_LIMIT        : REAL := 48.0; (* Seconds to TA *)
    RA_TAU_LIMIT        : REAL := 35.0; (* Seconds to RA *)
    TA_ALT_THRESH       : REAL := 1200.0; (* Feet *)
    RA_ALT_THRESH       : REAL := 800.0; (* Feet *)
    RA_CLIMB_RATE       : REAL := 1500.0; (* ft/min *)
    RA_DESCEND_RATE     : REAL := -1500.0; (* ft/min *)
END_VAR

(* 1. Initialize Baseline Status *)
Most_Critical_Tau := 9999.0;
Highest_Threat := CLEAR_OF_CONFLICT;
Aural_Warning := '';
System_Status := 'ACAS X ACTIVE';
Commanded_V_Speed := Ownship_Vert_Rate; (* Default to current trajectory *)

(* 2. Evaluate Mode S Transponder Targets *)
FOR i := 1 TO 10 DO
    IF Targets[i].Active THEN

        (* Calculate horizontal Tau (Seconds to CPA) *)
        IF Targets[i].Closure_Rate > 0.0 THEN
            (* Convert Closure_Rate (Knots) to NM/sec (1 Kt = 1/3600 NM/sec) *)
            Tau := Targets[i].Distance_NM / (Targets[i].Closure_Rate / 3600.0);
        ELSE
            Tau := 9999.0; (* Diverging or parallel *)
        END_IF;

        (* Evaluate Threat Level *)
        IF Tau < Most_Critical_Tau THEN

            (* Check for TA conditions *)
            IF Tau <= TA_TAU_LIMIT AND ABS(Targets[i].Rel_Altitude) <= TA_ALT_THRESH THEN

                (* Check for RA conditions *)
                IF Tau <= RA_TAU_LIMIT AND ABS(Targets[i].Rel_Altitude) <= RA_ALT_THRESH THEN

                    Most_Critical_Tau := Tau;

                    (* Resolution Advisory Logic Matrix *)
                    IF Targets[i].Rel_Altitude > 0.0 THEN
                        (* Threat is above us -> We should DESCEND *)
                        Highest_Threat := RA_DESCEND;
                        Commanded_V_Speed := RA_DESCEND_RATE;
                        Aural_Warning := 'DESCEND, DESCEND';
                    ELSE
                        (* Threat is below us -> We should CLIMB *)
                        Highest_Threat := RA_CLIMB;
                        Commanded_V_Speed := RA_CLIMB_RATE;
                        Aural_Warning := 'CLIMB, CLIMB';
                    END_IF;

                ELSIF Highest_Threat = CLEAR_OF_CONFLICT THEN
                    (* Only set TA if no RA is active *)
                    Most_Critical_Tau := Tau;
                    Highest_Threat := TRAFFIC_ADVISORY;
                    Aural_Warning := 'TRAFFIC, TRAFFIC';
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_FOR;

(* 3. TAWS (Terrain Avoidance and Warning System) Interlock Integration *)
(* 
   Prevents ACAS from issuing a DESCEND RA that would drive the aircraft into terrain.
*)
IF Highest_Threat = RA_DESCEND THEN
    (* Check against absolute safe altitude and AGL limits *)
    IF TAWS_Active AND ((Ownship_Alt + (Commanded_V_Speed / 60.0 * 15.0) <= TAWS_Min_Safe_Alt) OR (Radar_Alt_AGL < 1000.0)) THEN

        (* TAWS Override: Modifying RA to LEVEL OFF or CLIMB *)
        Highest_Threat := RA_LEVEL_OFF;
        Commanded_V_Speed := 0.0; (* Command 0 ft/min vertical rate *)
        Aural_Warning := 'MONITOR VERTICAL SPEED, TERRAIN';
        System_Status := 'TAWS INHIBIT DES';

    END_IF;
END_IF;

(* Reversion back to clear of conflict *)
IF Highest_Threat = CLEAR_OF_CONFLICT THEN
    Aural_Warning := 'CLEAR OF CONFLICT';
END_IF;

END_FUNCTION_BLOCK
