`iecst
(*
  Grid-Scale Synchronous Condenser Controller
  Description:
  Provides dynamic reactive power compensation, automated voltage regulation (AVR),
  and synthetic inertia utilizing a massive 200-ton spinning rotor. Features an 
  integrated hydrogen cooling casing loop with leak detection.
*)
FUNCTION_BLOCK FB_SyncCondenser_Controller

VAR_INPUT
    Enable : BOOL;
    Grid_Freq_Hz : REAL; (* Current Grid Frequency, nominal 60Hz/50Hz *)
    Grid_Volts_kV : REAL; (* Current Grid Voltage *)
    Rotor_Speed_RPM : REAL; (* Measured Rotor Speed *)
    H2_Purity_Pct : REAL; (* Hydrogen Purity %, critical for cooling and explosion prevention *)
    H2_Press_Bar : REAL; (* Hydrogen Pressure *)
    H2_Temp_C : REAL; (* Hydrogen Temperature *)
    AVR_Setpoint_kV : REAL := 13.8;
END_VAR

VAR_OUTPUT
    Field_Excitation_V : REAL; (* AVR Excitation Field Voltage *)
    Inertial_Pwr_MW : REAL; (* Estimated Inertial Power Delivery *)
    H2_Leak_Alarm : BOOL;
    H2_Makeup_Valve : BOOL;
    Sys_Trip : BOOL;
END_VAR

VAR
    (* AVR Internal *)
    AVR_Kp : REAL := 12.5;
    AVR_Ki : REAL := 4.2;
    AVR_Kd : REAL := 0.1;
    AVR_Int : REAL := 0.0;
    AVR_Prev_Error : REAL := 0.0;

    (* Inertial Response Internal *)
    Prev_Freq : REAL := 60.0;
    Rotor_Mass_Tons : REAL := 200.0;
    Time_Delta_s : REAL := 0.01; (* Assume 10ms execution cycle time *)
    df_dt : REAL;

    (* H2 Leak Detection Internal *)
    Pressure_Drop_Rate : REAL;
    Prev_Pressure : REAL := 4.5;
    Leak_Time_Delay : TON;
END_VAR

(* --- Main Execution --- *)
IF Enable THEN
    (* --- 1. Massive 200-ton Spinning Rotor Inertial Frequency Response --- *)
    (* Calculate ROCOF (Rate of Change of Frequency) *)
    df_dt := (Grid_Freq_Hz - Prev_Freq) / Time_Delta_s;
    Prev_Freq := Grid_Freq_Hz;

    (* Inertial power response based on swing equation P = 2H * df/dt *)
    (* The massive 200-ton rotor equivalent inertia provides inherent grid stability *)
    Inertial_Pwr_MW := -1.0 * (Rotor_Mass_Tons * 0.0325) * df_dt; 

    (* --- 2. Automatic Voltage Regulator (AVR) Excitation Field Control --- *)
    (* PID Controller for Excitation Field to regulate reactive power *)
    VAR 
        Error : REAL;
        Derivative : REAL;
    END_VAR

    Error := AVR_Setpoint_kV - Grid_Volts_kV;
    AVR_Int := AVR_Int + (Error * Time_Delta_s);

    (* Anti-windup protection for the integrator *)
    IF AVR_Int > 500.0 THEN AVR_Int := 500.0; END_IF;
    IF AVR_Int < -500.0 THEN AVR_Int := -500.0; END_IF;

    Derivative := (Error - AVR_Prev_Error) / Time_Delta_s;
    AVR_Prev_Error := Error;

    Field_Excitation_V := (AVR_Kp * Error) + (AVR_Ki * AVR_Int) + (AVR_Kd * Derivative);

    (* Limit excitation field voltage to hardware constraints *)
    IF Field_Excitation_V > 250.0 THEN 
        Field_Excitation_V := 250.0; 
    ELSIF Field_Excitation_V < 0.0 THEN
        Field_Excitation_V := 0.0;
    END_IF;

    (* --- 3. Hydrogen Casing Cooling Loop Leak Detection --- *)
    (* Detect rapid pressure loss indicating casing seal failure or line rupture *)
    Pressure_Drop_Rate := (Prev_Pressure - H2_Press_Bar) / Time_Delta_s;
    Prev_Pressure := H2_Press_Bar;

    (* Leak condition: Pressure dropping fast or Purity below 95% *)
    IF (Pressure_Drop_Rate > 0.05) OR (H2_Purity_Pct < 95.0) THEN
        H2_Leak_Alarm := TRUE;
    ELSE
        H2_Leak_Alarm := FALSE;
    END_IF;

    (* Automatic Makeup Valve for minor pressure losses (normal operation) *)
    IF H2_Press_Bar < 4.3 AND NOT H2_Leak_Alarm THEN
        H2_Makeup_Valve := TRUE;
    ELSE
        H2_Makeup_Valve := FALSE;
    END_IF;

    (* Critical Trip Conditions: H2 is highly explosive if mixed with oxygen *)
    IF H2_Purity_Pct < 90.0 OR H2_Press_Bar < 3.0 THEN
        Sys_Trip := TRUE;
        Field_Excitation_V := 0.0; (* Dump field immediately *)
    ELSE
        Sys_Trip := FALSE;
    END_IF;

ELSE
    (* Safe shutdown state *)
    Field_Excitation_V := 0.0;
    Inertial_Pwr_MW := 0.0;
    H2_Makeup_Valve := FALSE;
    H2_Leak_Alarm := FALSE;
    Sys_Trip := FALSE;
END_IF;
END_FUNCTION_BLOCK
