FUNCTION_BLOCK "UPW_RO_Controller"
{ S7_Optimized_Access := 'TRUE' }
AUTHOR : 'Lumina Elite Architect'
FAMILY : 'SemiFabUPW'
VERSION : 1.0
//=============================================================================
// Ultra-Pure Water (UPW) Reverse Osmosis Advanced Controller
// Technical Specs:
// 1. 18.2 Megaohm-cm resistivity tracking and fail-to-drain interlocks.
// 2. Total Organic Carbon (TOC) continuous UV oxidation looping.
// 3. Final sub-micron ultrafiltration (UF) cross-flow matrix.
//=============================================================================
   VAR_INPUT 
      ib_SystemEnable : Bool;   // Master enable for the UPW RO system
      ir_FeedPressure_bar : Real;   // Feed pressure from main supply
      ir_RO_PermeateResistivity_MOhm : Real;   // RO Permeate Resistivity (Target: > 18.2 MOhm-cm)
      ir_TOC_Level_ppb : Real;   // Total Organic Carbon level in ppb (Target: < 1.0 ppb)
      ir_UF_TransMembranePressure_bar : Real; // TMP across Ultrafiltration matrix
      ib_DrainValve_ClosedFB : Bool; // Feedback from fail-to-drain valve
   END_VAR

   VAR_OUTPUT 
      ob_HighPressurePumpCmd : Bool; // Command for main RO HP pump
      or_HighPressurePumpSpeed_pct : Real; // VFD Speed for HP pump
      ob_FailToDrainValveCmd : Bool; // Command to open fail-to-drain valve
      ob_UV_OxidationLampCmd : Bool; // Command to power on UV 185nm/254nm oxidation lamps
      ob_UF_RecirculationPumpCmd : Bool; // Ultrafiltration cross-flow matrix pump
      ob_SystemFault : Bool; // Master fault indicator
      ob_WaterQualityOK : Bool; // True if UPW is 18.2 MOhm-cm and TOC < 1 ppb
   END_VAR

   VAR 
      stat_State_Machine : Int; // 0: OFF, 1: FLUSH, 2: PRODUCTION, 3: FAIL_TO_DRAIN
      inst_TimerFlush {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
      inst_TimerResistivityDelay {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
      stat_ResistivityFault : Bool;
      stat_TOCFault : Bool;
      stat_UFFault : Bool;
   END_VAR

   VAR CONSTANT 
      RESISTIVITY_LIMIT_MOHM : Real := 18.15; // Setpoint below 18.2 to allow hysteresis
      TOC_LIMIT_PPB : Real := 1.5; // Max allowable TOC in ppb
      UF_TMP_MAX_BAR : Real := 2.5; // Max trans-membrane pressure
      STATE_OFF : Int := 0;
      STATE_FLUSH : Int := 1;
      STATE_PRODUCTION : Int := 2;
      STATE_FAIL_TO_DRAIN : Int := 3;
   END_VAR

BEGIN
    // ------------------------------------------------------------------------
    // Fault Evaluation
    // ------------------------------------------------------------------------
    // 1. Resistivity tracking (18.2 Megaohm-cm)
    // Delay fault slightly to allow transient stabilization
    #inst_TimerResistivityDelay(IN := (#ir_RO_PermeateResistivity_MOhm < #RESISTIVITY_LIMIT_MOHM) AND (#stat_State_Machine = #STATE_PRODUCTION),
                                PT := T#5s);
    #stat_ResistivityFault := #inst_TimerResistivityDelay.Q;

    // 2. Total Organic Carbon (TOC) evaluation
    #stat_TOCFault := (#ir_TOC_Level_ppb > #TOC_LIMIT_PPB);

    // 3. Ultrafiltration (UF) cross-flow matrix TMP evaluation
    #stat_UFFault := (#ir_UF_TransMembranePressure_bar > #UF_TMP_MAX_BAR);

    #ob_SystemFault := #stat_ResistivityFault OR #stat_TOCFault OR #stat_UFFault;

    // ------------------------------------------------------------------------
    // State Machine
    // ------------------------------------------------------------------------
    IF NOT #ib_SystemEnable THEN
        #stat_State_Machine := #STATE_OFF;
    ELSIF #ob_SystemFault THEN
        #stat_State_Machine := #STATE_FAIL_TO_DRAIN;
    END_IF;

    CASE #stat_State_Machine OF
        #STATE_OFF:
            #ob_HighPressurePumpCmd := FALSE;
            #or_HighPressurePumpSpeed_pct := 0.0;
            #ob_FailToDrainValveCmd := FALSE;
            #ob_UV_OxidationLampCmd := FALSE;
            #ob_UF_RecirculationPumpCmd := FALSE;
            #ob_WaterQualityOK := FALSE;

            IF #ib_SystemEnable AND NOT #ob_SystemFault THEN
                #stat_State_Machine := #STATE_FLUSH;
            END_IF;

        #STATE_FLUSH:
            // Flush sequence to purge initial lines
            #ob_HighPressurePumpCmd := TRUE;
            #or_HighPressurePumpSpeed_pct := 40.0; // Low speed flush
            #ob_FailToDrainValveCmd := TRUE; // Flush goes to drain
            #ob_UV_OxidationLampCmd := TRUE; // Warm up UV
            #ob_UF_RecirculationPumpCmd := TRUE; // Run cross-flow matrix

            #inst_TimerFlush(IN := TRUE, PT := T#30s);
            IF #inst_TimerFlush.Q AND (#ir_RO_PermeateResistivity_MOhm >= #RESISTIVITY_LIMIT_MOHM) THEN
                #stat_State_Machine := #STATE_PRODUCTION;
            END_IF;

        #STATE_PRODUCTION:
            #inst_TimerFlush(IN := FALSE, PT := T#30s); // Reset flush timer
            #ob_HighPressurePumpCmd := TRUE;
            #or_HighPressurePumpSpeed_pct := 100.0; // Full production
            #ob_FailToDrainValveCmd := FALSE; // Send UPW to fab
            #ob_UV_OxidationLampCmd := TRUE; // Continuous TOC UV oxidation
            #ob_UF_RecirculationPumpCmd := TRUE; // Continuous sub-micron UF
            #ob_WaterQualityOK := TRUE;

        #STATE_FAIL_TO_DRAIN:
            // Fail-to-drain interlocks
            #ob_HighPressurePumpCmd := TRUE; // Keep running to maintain pressure, but dump
            #or_HighPressurePumpSpeed_pct := 50.0; 
            #ob_FailToDrainValveCmd := TRUE; // Divert to drain to protect fab
            #ob_UV_OxidationLampCmd := TRUE; // Keep UV on to attempt recovery
            #ob_UF_RecirculationPumpCmd := TRUE;
            #ob_WaterQualityOK := FALSE;

            IF NOT #ob_SystemFault AND #ib_SystemEnable THEN
                #stat_State_Machine := #STATE_FLUSH; // Re-attempt flush if faults clear
            END_IF;

    END_CASE;
END_FUNCTION_BLOCK

(*
  =============================================================================
  Block: FB_AutomatedCottonGinController
  Description: 
    Advanced enterprise-grade sequencer for an automated cotton gin facility.
    Integrates safety interlocks, saw-gin rib gap motorized clearing matrix,
    hot air drying tower moisture control, and 500-ton hydraulic bale press
    sequencing.
  Standard: IEC 61131-3 (Structured Text)
  Author: Lumina Elite Synthetic Data Architect
  =============================================================================
*)
FUNCTION_BLOCK FB_AutomatedCottonGinController
VAR_INPUT
    bEnable                 : BOOL; // System master start
    bEmergencyStop          : BOOL; // Emergency stop (Active Low)
    rCottonMoistureIn       : REAL; // Inlet cotton moisture % (0.0 to 100.0)
    rHydraulicPressurePress : REAL; // Current bale press hydraulic pressure (Bar) - corresponding to force
    bClearMatrixTrigger     : BOOL; // Trigger manual/auto clear matrix sequence
END_VAR

VAR_OUTPUT
    // Drying Tower Control
    rBurnerOutputCmd        : REAL; // 0-100% command to hot air drying tower burners
    bDryingBlowerStart      : BOOL; // Drying blower motor start command

    // Rib Gap Clearing Matrix Control
    bMatrixMotorFwd         : BOOL; // Clear matrix motor forward
    bMatrixMotorRev         : BOOL; // Clear matrix motor reverse
    bMatrixClearActive      : BOOL; // Matrix clearing sequence in progress

    // Bale Press Control
    bPressCylinderExtend    : BOOL; // Extend bale press cylinder
    bPressCylinderRetract   : BOOL; // Retract bale press cylinder
    bBaleEject              : BOOL; // Eject finished bale
    iBaleState              : INT;  // Current step of the baling sequence

    // General Status
    bSystemFault            : BOOL; // System in fault state
    sStatusMessage          : STRING(50);
END_VAR

VAR
    // Internal States
    eStateMode              : INT; // 0=INIT, 1=RUNNING, 2=FAULT, 3=CLEARING_MATRIX
    iBalingStep             : INT := 0; 

    // Timers
    tMatrixClearTimer       : TON;
    tPressHoldTimer         : TON;
    tEjectTimer             : TON;

    // PID for moisture (Simulated structure for standard library compatibility)
    fbMoisturePID           : PID_Basic; 

    // Constants
    cTargetMoisture         : REAL := 6.5; // Ideal ginning moisture %
    cPressTargetBar         : REAL := 320.0; // Assuming 320 Bar yields 500 tons of force on the ram
    cPressHoldTime          : TIME := T#5S; 
    cMatrixClearTime        : TIME := T#3S;
END_VAR

// 1. Safety Interlocks
IF NOT bEmergencyStop THEN
    bSystemFault := TRUE;
    sStatusMessage := 'E-STOP ACTIVE';
    eStateMode := 2; // FAULT

    // Safe state enforcement
    rBurnerOutputCmd := 0.0;
    bDryingBlowerStart := FALSE;
    bMatrixMotorFwd := FALSE;
    bMatrixMotorRev := FALSE;
    bPressCylinderExtend := FALSE;
    bPressCylinderRetract := TRUE; // Safely retract press on e-stop
    bBaleEject := FALSE;
    iBalingStep := 0;
    RETURN;
END_IF;

// 2. State Machine
CASE eStateMode OF
    0: // INIT
        IF bEnable THEN
            eStateMode := 1; // RUNNING
            sStatusMessage := 'SYSTEM RUNNING';
        ELSE
            sStatusMessage := 'READY TO START';
        END_IF;

    1: // RUNNING
        // Trigger clearing matrix
        IF bClearMatrixTrigger THEN
            eStateMode := 3; // CLEARING_MATRIX
            sStatusMessage := 'CLEARING RIB GAP MATRIX';
            bMatrixClearActive := TRUE;
        END_IF;

    3: // CLEARING_MATRIX
        // Saw-gin rib gap motorized clearing matrix sequencing
        tMatrixClearTimer(IN := TRUE, PT := T#6S); // cMatrixClearTime * 2

        IF tMatrixClearTimer.ET < cMatrixClearTime THEN
            // Forward pass to dislodge seeds/debris
            bMatrixMotorFwd := TRUE;
            bMatrixMotorRev := FALSE;
        ELSIF tMatrixClearTimer.ET < T#6S THEN
            // Reverse pass to reset matrix
            bMatrixMotorFwd := FALSE;
            bMatrixMotorRev := TRUE;
        ELSE
            // Complete
            bMatrixMotorFwd := FALSE;
            bMatrixMotorRev := FALSE;
            bMatrixClearActive := FALSE;
            tMatrixClearTimer(IN := FALSE);
            eStateMode := 1; // RUNNING
            sStatusMessage := 'SYSTEM RUNNING';
        END_IF;

    2: // FAULT
        IF bEmergencyStop AND bEnable = FALSE THEN
            // Reset fault if e-stop cleared and enable toggled off
            bSystemFault := FALSE;
            eStateMode := 0; // INIT
        END_IF;
END_CASE;

// 3. Moisture Sensor Feedback & Drying Tower Burners
IF eStateMode = 1 OR eStateMode = 3 THEN
    bDryingBlowerStart := TRUE;

    // Moisture Control Output
    fbMoisturePID(
        ACTUAL := rCottonMoistureIn,
        SET_POINT := cTargetMoisture,
        KP := 2.5,
        KI := 0.5,
        KD := 0.1,
        Y => rBurnerOutputCmd
    );

    // Limit burner command to 0-100%
    IF rBurnerOutputCmd > 100.0 THEN
        rBurnerOutputCmd := 100.0;
    ELSIF rBurnerOutputCmd < 0.0 THEN
        rBurnerOutputCmd := 0.0;
    END_IF;
ELSE
    bDryingBlowerStart := FALSE;
    rBurnerOutputCmd := 0.0;
END_IF;

// 4. Bale Press Hydraulic Sequencing (500 tons force)
IF eStateMode = 1 THEN
    CASE iBalingStep OF
        0: // Idle / Loading
            bPressCylinderExtend := FALSE;
            bPressCylinderRetract := TRUE;
            bBaleEject := FALSE;

            IF bEnable THEN 
                iBalingStep := 1;
            END_IF;

        1: // Compacting (Extending)
            bPressCylinderRetract := FALSE;
            bPressCylinderExtend := TRUE;

            // 500 tons force corresponds to cPressTargetBar
            IF rHydraulicPressurePress >= cPressTargetBar THEN
                iBalingStep := 2; // Transition to holding
            END_IF;

        2: // Holding pressure
            tPressHoldTimer(IN := TRUE, PT := cPressHoldTime);
            IF tPressHoldTimer.Q THEN
                tPressHoldTimer(IN := FALSE);
                iBalingStep := 3; // Transition to retracting
            END_IF;

        3: // Retracting
            bPressCylinderExtend := FALSE;
            bPressCylinderRetract := TRUE;

            IF rHydraulicPressurePress < 10.0 THEN
                iBalingStep := 4; // Transition to eject
            END_IF;

        4: // Eject Bale
            bBaleEject := TRUE;
            tEjectTimer(IN := TRUE, PT := T#2S); 
            IF tEjectTimer.Q THEN
                bBaleEject := FALSE;
                tEjectTimer(IN := FALSE);
                iBalingStep := 0; // Restart cycle
            END_IF;
    END_CASE;
ELSE
    // Reset baling sequence if not running
    iBalingStep := 0;
    tPressHoldTimer(IN := FALSE);
    tEjectTimer(IN := FALSE);
END_IF;

iBaleState := iBalingStep;
END_FUNCTION_BLOCK

