(*
    INDUSTRIAL ELECTROSPINNING NANO-FIBER MACHINE CONTROLLER
    ========================================================
    Version: 2.1 (Enterprise Grade)

    Technical Specifications:
    1. 100kV High-Voltage Syringe Pump Taylor Cone Stabilization
    2. Rotating Collector Drum Speed Profiling (Aligned Fiber Deposition)
    3. Climate-Controlled Enclosure (RH) & Solvent Vapor Extraction Loops

    This block integrates PID controllers for High Voltage (HV), 
    Syringe Pump flow rate, Drum Collector RPM, and environmental 
    conditions to maintain a stable Taylor Cone and optimal fiber morphology.
*)
FUNCTION_BLOCK ELECTROSPIN_CONTROLLER
VAR_INPUT
    Enable : BOOL;          (* Master Enable *)
    EmergencyStop : BOOL;   (* E-Stop Interlock *)

    (* Process Setpoints *)
    SP_Voltage_kV : REAL;   (* High Voltage Setpoint [kV] *)
    SP_FlowRate_ml_h : REAL;(* Polymer Flow Rate Setpoint [ml/h] *)
    SP_Drum_RPM : REAL;     (* Collector Drum Speed Setpoint [RPM] *)
    SP_Humidity_RH : REAL;  (* Enclosure Humidity Setpoint [% RH] *)
    SP_VaporExtraction : REAL; (* Vapor Extraction Airflow [CFM] *)

    (* Process Variables (Sensors) *)
    PV_Voltage_kV : REAL;
    PV_TaylorConeCurrent_uA : REAL; (* Feedback for Taylor Cone stability *)
    PV_Drum_RPM : REAL;
    PV_Humidity_RH : REAL;
    PV_VaporPPM : REAL;     (* Solvent Vapor Concentration [PPM] *)

    (* Profiles for Drum Speed (Aligned Fibers) *)
    ProfileActive : BOOL;
    RampRate_RPM_s : REAL;
END_VAR

VAR_OUTPUT
    (* Actuator Control Signals *)
    CV_HV_Supply : REAL;      (* Control Voltage for HV Supply 0-10V *)
    CV_SyringePump_Hz : REAL; (* Control Freq for Syringe Pump 0-60Hz *)
    CV_DrumMotor_Hz : REAL;   (* Control Freq for Drum Motor 0-60Hz *)
    CV_Humidifier_PWM : REAL; (* Humidifier PWM 0-100% *)
    CV_Extractor_Hz : REAL;   (* Vapor Extractor Fan 0-60Hz *)

    (* Status & Alarms *)
    State : INT;              (* 0=Idle, 1=Prep, 2=Spinning, 3=Purge, 99=Fault *)
    TaylorConeStable : BOOL;
    HighVaporAlarm : BOOL;
    FaultCode : INT;
END_VAR

VAR
    (* PID Controllers *)
    PID_HV : PID_Compact;
    PID_Drum : PID_Compact;
    PID_RH : PID_Compact;
    PID_Vapor : PID_Compact;

    (* Internal State *)
    TargetDrum_RPM : REAL;
    DrumProfileTimer : TON;
    CurrentRamp_RPM : REAL;

    (* Taylor Cone Analysis *)
    ConeCurrentFilter : LREAL;
    ConeStabilityTimer : TON;

    (* Constants *)
    MAX_VAPOR_PPM : REAL := 500.0; (* LEL threshold for solvent *)
    MAX_VOLTAGE : REAL := 100.0;
END_VAR

(* 1. Safety & Interlocks *)
IF EmergencyStop OR (PV_VaporPPM > MAX_VAPOR_PPM) THEN
    State := 99;
    FaultCode := 16#E001; (* E-Stop or LEL Exceeded *)
    CV_HV_Supply := 0.0;
    CV_SyringePump_Hz := 0.0;
    CV_DrumMotor_Hz := 0.0;
    CV_Humidifier_PWM := 0.0;
    CV_Extractor_Hz := 60.0; (* Max extraction during fault *)
    RETURN;
END_IF;

(* 2. State Machine *)
CASE State OF
    0: (* Idle *)
        IF Enable THEN
            State := 1; (* Move to Prep *)
        END_IF;
        CV_HV_Supply := 0.0;
        CV_SyringePump_Hz := 0.0;

    1: (* Prep - Stabilize Environment first *)
        IF (ABS(PV_Humidity_RH - SP_Humidity_RH) < 2.0) THEN
            State := 2; (* Ready for Spinning *)
        END_IF;

    2: (* Spinning - Active Control *)
        IF NOT Enable THEN
            State := 3; (* Move to Purge *)
        END_IF;

    3: (* Purge - Clear Syringe and Vent Enclosure *)
        IF PV_VaporPPM < 50.0 THEN
            State := 0;
        END_IF;
        CV_HV_Supply := 0.0;
        CV_SyringePump_Hz := 0.0;
END_CASE;

(* 3. Taylor Cone Stabilization (High Voltage & Syringe Pump) *)
IF State = 2 THEN
    (* Modulate HV based on base setpoint and Taylor Cone Current feedback *)
    PID_HV(
        Enable := TRUE,
        SP := SP_Voltage_kV,
        PV := PV_Voltage_kV,
        Kp := 0.85,
        Ki := 0.12,
        Kd := 0.05,
        CV => CV_HV_Supply
    );

    (* Syringe Pump Flow Rate (Volumetric dosing) *)
    CV_SyringePump_Hz := (SP_FlowRate_ml_h * 1.5) + (PV_TaylorConeCurrent_uA * 0.01);

    (* Evaluate Cone Stability: Current within +/- 2uA bounds *)
    IF ABS(PV_TaylorConeCurrent_uA - 15.0) < 2.0 THEN
        ConeStabilityTimer(IN:=TRUE, PT:=T#2S);
    ELSE
        ConeStabilityTimer(IN:=FALSE, PT:=T#2S);
    END_IF;
    TaylorConeStable := ConeStabilityTimer.Q;
ELSE
    PID_HV(Enable := FALSE);
    ConeStabilityTimer(IN:=FALSE);
    TaylorConeStable := FALSE;
END_IF;

(* 4. Collector Drum Speed Profiling (Aligned Fibers) *)
IF State = 2 THEN
    IF ProfileActive THEN
        IF TargetDrum_RPM < SP_Drum_RPM THEN
            TargetDrum_RPM := TargetDrum_RPM + RampRate_RPM_s * 0.01; 
        ELSIF TargetDrum_RPM > SP_Drum_RPM THEN
            TargetDrum_RPM := TargetDrum_RPM - RampRate_RPM_s * 0.01;
        END_IF;
    ELSE
        TargetDrum_RPM := SP_Drum_RPM;
    END_IF;

    PID_Drum(
        Enable := TRUE,
        SP := TargetDrum_RPM,
        PV := PV_Drum_RPM,
        Kp := 1.2,
        Ki := 0.3,
        CV => CV_DrumMotor_Hz
    );
ELSE
    PID_Drum(Enable := FALSE);
    TargetDrum_RPM := 0.0;
    CV_DrumMotor_Hz := 0.0;
END_IF;

(* 5. Climate Control & Vapor Extraction Loops *)
PID_RH(
    Enable := (State > 0),
    SP := SP_Humidity_RH,
    PV := PV_Humidity_RH,
    Kp := 2.5,
    Ki := 0.5,
    CV => CV_Humidifier_PWM
);

PID_Vapor(
    Enable := TRUE,
    SP := SP_VaporExtraction,
    PV := PV_VaporPPM,
    Kp := 1.8,
    Ki := 0.2,
    CV => CV_Extractor_Hz
);

HighVaporAlarm := (PV_VaporPPM > (MAX_VAPOR_PPM * 0.8));

END_FUNCTION_BLOCK

(*
    VERSION: 3.4.1 (ENTERPRISE GRADE)
    AUTHOR: Lead Process Engineer / Elite Synthetic Data Architect
    DATE: 2026-08-21

    DESCRIPTION:
    100-Meter Continuous Tunnel Baking Oven Controller (IEC 61131-3)
    This comprehensive controller manages a massive commercial bakery oven with the following subsystems:
    1. Multi-Zone Cyclotherm Burner Profiling: Manages 8 distinct zones, balancing radiant and convective 
       heat transfer mechanisms for precise baking profiles.
    2. Wire-Mesh Band Tracking & Tensioning: Dual-axis servo control to prevent wire-mesh band snap 
       and lateral drift across the 100-meter span.
    3. Steam Injection Matrices: Micro-pulsed steam headers at the oven entrance for optimal crust 
       development (Maillard reaction promotion).

    ARCHITECTURE:
    - FB_CyclothermZone: Individual zone PID control for top/bottom burners and air circulation.
    - FB_BandTensioner: Load-cell based PID loop for hydraulic/pneumatic tensioning and edge tracking.
    - FB_SteamHeader: Pressure and mass-flow based steam injection matrix.
    - FB_TunnelOven_Main: Coordinator block orchestrating the subsystems.
*)

TYPE ST_ZoneConfig :
STRUCT
    SetPoint_TopRadiant : REAL;    (* °C *)
    SetPoint_BtmRadiant : REAL;    (* °C *)
    SetPoint_Convective : REAL;    (* Airflow m/s *)
    RadiantRatio        : REAL;    (* 0.0 to 1.0 *)
    ExhaustDamperPos    : REAL;    (* % open *)
END_STRUCT
END_TYPE

TYPE ST_ZoneStatus :
STRUCT
    Actual_TopTemp : REAL;
    Actual_BtmTemp : REAL;
    Actual_Airflow : REAL;
    Burner_Modulation : REAL;      (* 0-100% *)
    Burner_Fault   : BOOL;
END_STRUCT
END_TYPE

(* ========================================================================= *)
(* FB_CyclothermZone: Multi-Zone Cyclotherm Burner Control                   *)
(* ========================================================================= *)
FUNCTION_BLOCK FB_CyclothermZone
VAR_INPUT
    Enable          : BOOL;
    Config          : ST_ZoneConfig;
    ActualTopTemp   : REAL;
    ActualBtmTemp   : REAL;
    ActualAirflow   : REAL;
    GasPressureOK   : BOOL;
    FlameRelayOK    : BOOL;
END_VAR
VAR_OUTPUT
    Cmd_TopBurnerValve : REAL;     (* 0-100% Analog Output *)
    Cmd_BtmBurnerValve : REAL;     (* 0-100% Analog Output *)
    Cmd_CirculationFan : REAL;     (* 0-100% VFD Speed *)
    Cmd_ExhaustDamper  : REAL;     (* 0-100% Damper Actuator *)
    Status          : ST_ZoneStatus;
    Alarm           : BOOL;
END_VAR
VAR
    PID_Top : PID_Compact;
    PID_Btm : PID_Compact;
    PID_Air : PID_Compact;
    State   : INT := 0;
END_VAR

IF NOT Enable OR NOT GasPressureOK OR NOT FlameRelayOK THEN
    Cmd_TopBurnerValve := 0.0;
    Cmd_BtmBurnerValve := 0.0;
    Cmd_CirculationFan := 10.0; (* Minimum purge speed *)
    Cmd_ExhaustDamper  := 100.0; (* Open exhaust on stop *)
    Alarm := NOT GasPressureOK OR NOT FlameRelayOK;
    RETURN;
END_IF;

(* Top Burner Radiant PID *)
PID_Top(
    Setpoint := Config.SetPoint_TopRadiant,
    Actual   := ActualTopTemp,
    Kp       := 2.5,
    Ti       := T#120S,
    Td       := T#10S,
    Out_Min  := 0.0,
    Out_Max  := 100.0,
    Output   => Cmd_TopBurnerValve
);

(* Bottom Burner Radiant PID *)
PID_Btm(
    Setpoint := Config.SetPoint_BtmRadiant,
    Actual   := ActualBtmTemp,
    Kp       := 2.8,
    Ti       := T#140S,
    Td       := T#15S,
    Out_Min  := 0.0,
    Out_Max  := 100.0,
    Output   => Cmd_BtmBurnerValve
);

(* Convective Airflow PID *)
PID_Air(
    Setpoint := Config.SetPoint_Convective,
    Actual   := ActualAirflow,
    Kp       := 1.2,
    Ti       := T#60S,
    Out_Min  := 20.0,
    Out_Max  := 100.0,
    Output   => Cmd_CirculationFan
);

Cmd_ExhaustDamper := Config.ExhaustDamperPos;

(* Status Update *)
Status.Actual_TopTemp := ActualTopTemp;
Status.Actual_BtmTemp := ActualBtmTemp;
Status.Actual_Airflow := ActualAirflow;
Status.Burner_Modulation := (Cmd_TopBurnerValve + Cmd_BtmBurnerValve) / 2.0;
Status.Burner_Fault := FALSE;

END_FUNCTION_BLOCK


(* ========================================================================= *)
(* FB_BandTracking: Wire-Mesh Band Tracking and Tensioning                   *)
(* ========================================================================= *)
FUNCTION_BLOCK FB_BandTracking
VAR_INPUT
    Enable          : BOOL;
    BandSpeed_SP    : REAL;        (* m/min *)
    LoadCell_Left   : REAL;        (* kN *)
    LoadCell_Right  : REAL;        (* kN *)
    TargetTension   : REAL;        (* kN *)
    EdgeSensor_L    : REAL;        (* mm deviation *)
    EdgeSensor_R    : REAL;        (* mm deviation *)
END_VAR
VAR_OUTPUT
    Cmd_DriveVFD    : REAL;        (* 0-100% Main Drive *)
    Cmd_TensionCyl  : REAL;        (* 0-100% Hydraulic Valve *)
    Cmd_TrackerLeft : REAL;        (* Actuator Pos *)
    Cmd_TrackerRight: REAL;        (* Actuator Pos *)
    TensionError    : BOOL;
    TrackingFault   : BOOL;
END_VAR
VAR
    TensionPID      : PID_Compact;
    TotalTension    : REAL;
    Differential    : REAL;
    Integral_Track  : REAL;
END_VAR

IF NOT Enable THEN
    Cmd_DriveVFD := 0.0;
    Cmd_TensionCyl := 0.0;
    RETURN;
END_IF;

TotalTension := LoadCell_Left + LoadCell_Right;
Differential := LoadCell_Left - LoadCell_Right;

(* Tensioning PID - Prevent Band Snap *)
TensionPID(
    Setpoint := TargetTension,
    Actual   := TotalTension,
    Kp       := 5.0,
    Ti       := T#5S,
    Out_Min  := 0.0,
    Out_Max  := 100.0,
    Output   => Cmd_TensionCyl
);

(* Band Tracking Proportional-Integral Control *)
IF ABS(EdgeSensor_L - EdgeSensor_R) > 5.0 THEN
    Integral_Track := Integral_Track + (EdgeSensor_L - EdgeSensor_R) * 0.01;
END_IF;

Integral_Track := LIMIT(-20.0, Integral_Track, 20.0);

Cmd_TrackerLeft := 50.0 + (EdgeSensor_L * 2.0) + Integral_Track;
Cmd_TrackerRight := 50.0 + (EdgeSensor_R * 2.0) - Integral_Track;

(* Fault Detections *)
TensionError := (TotalTension > TargetTension * 1.5) OR (TotalTension < TargetTension * 0.5);
TrackingFault := (ABS(EdgeSensor_L) > 50.0) OR (ABS(EdgeSensor_R) > 50.0);

(* Main Drive Control *)
Cmd_DriveVFD := BandSpeed_SP * 2.5; (* Speed scaling factor *)

END_FUNCTION_BLOCK


(* ========================================================================= *)
(* FB_SteamInjection: Steam Matrices for Crust Development                   *)
(* ========================================================================= *)
FUNCTION_BLOCK FB_SteamInjection
VAR_INPUT
    Enable          : BOOL;
    ProductDetect   : BOOL;        (* Photoeye at entrance *)
    TargetFlow      : REAL;        (* kg/hr *)
    SteamPressure   : REAL;        (* bar *)
    Zone1Temp       : REAL;        (* Interlock with Zone 1 temp *)
END_VAR
VAR_OUTPUT
    Cmd_ProportionalValve : REAL;  (* 0-100% *)
    Valve1_Header   : BOOL;
    Valve2_Header   : BOOL;
    Valve3_Header   : BOOL;
    SteamReady      : BOOL;
END_VAR
VAR
    SteamPID        : PID_Compact;
    PulseTimer      : TON;
    PulseCount      : INT;
END_VAR

SteamReady := (SteamPressure > 2.5) AND (Zone1Temp > 100.0);

IF Enable AND SteamReady AND ProductDetect THEN
    SteamPID(
        Setpoint := TargetFlow,
        Actual   := SteamPressure * 10.0, (* Simulated flow calc *)
        Kp       := 1.5,
        Ti       := T#2S,
        Out_Min  := 0.0,
        Out_Max  := 100.0,
        Output   => Cmd_ProportionalValve
    );

    (* Sequenced Matrix Injection to maintain pressure *)
    Valve1_Header := TRUE;
    Valve2_Header := Cmd_ProportionalValve > 30.0;
    Valve3_Header := Cmd_ProportionalValve > 70.0;
ELSE
    Cmd_ProportionalValve := 0.0;
    Valve1_Header := FALSE;
    Valve2_Header := FALSE;
    Valve3_Header := FALSE;
END_IF;

END_FUNCTION_BLOCK


(* ========================================================================= *)
(* FB_TunnelOven_Main: Master Coordinator for 100-meter Oven                 *)
(* ========================================================================= *)
PROGRAM MAIN_OVEN_CTRL
VAR
    (* Master Controls *)
    OvenStart       : BOOL;
    OvenEmergency   : BOOL;
    RecipeSelect    : INT;

    (* Subsystems *)
    Zones           : ARRAY[1..8] OF FB_CyclothermZone;
    ZoneConfigs     : ARRAY[1..8] OF ST_ZoneConfig;
    BandTrack       : FB_BandTracking;
    SteamInj        : FB_SteamInjection;

    (* Field IO - Simulated *)
    ActualTops      : ARRAY[1..8] OF REAL;
    ActualBtms      : ARRAY[1..8] OF REAL;
    ActualAirs      : ARRAY[1..8] OF REAL;

    i : INT;
END_VAR

IF OvenEmergency THEN
    OvenStart := FALSE;
END_IF;

(* 1. Recipe Management (Simplistic Example) *)
CASE RecipeSelect OF
    1: (* Artisan Sourdough *)
        BandTrack.BandSpeed_SP := 12.0; (* slower bake *)
        BandTrack.TargetTension := 150.0;
        SteamInj.TargetFlow := 300.0; (* heavy steam *)
        FOR i := 1 TO 8 DO
            ZoneConfigs[i].SetPoint_TopRadiant := 240.0 - (INT_TO_REAL(i)*5.0);
            ZoneConfigs[i].SetPoint_BtmRadiant := 250.0 - (INT_TO_REAL(i)*5.0);
            ZoneConfigs[i].SetPoint_Convective := 5.0;
        END_FOR
    2: (* Soft Buns *)
        BandTrack.BandSpeed_SP := 22.0; (* fast bake *)
        BandTrack.TargetTension := 120.0;
        SteamInj.TargetFlow := 50.0; (* light steam *)
        FOR i := 1 TO 8 DO
            ZoneConfigs[i].SetPoint_TopRadiant := 180.0;
            ZoneConfigs[i].SetPoint_BtmRadiant := 190.0;
            ZoneConfigs[i].SetPoint_Convective := 8.0;
        END_FOR
END_CASE

(* 2. Execute Zone Cyclotherm Controllers *)
FOR i := 1 TO 8 DO
    Zones[i](
        Enable := OvenStart AND NOT OvenEmergency,
        Config := ZoneConfigs[i],
        ActualTopTemp := ActualTops[i],
        ActualBtmTemp := ActualBtms[i],
        ActualAirflow := ActualAirs[i],
        GasPressureOK := TRUE,  (* Simulated IO *)
        FlameRelayOK  := TRUE   (* Simulated IO *)
    );
END_FOR

(* 3. Execute Band Tracking *)
BandTrack(
    Enable := OvenStart AND NOT OvenEmergency,
    BandSpeed_SP := BandTrack.BandSpeed_SP,
    LoadCell_Left := 75.0,  (* Simulated IO *)
    LoadCell_Right := 75.0, (* Simulated IO *)
    TargetTension := BandTrack.TargetTension,
    EdgeSensor_L := 1.0,    (* Simulated IO *)
    EdgeSensor_R := -1.0    (* Simulated IO *)
);

(* 4. Execute Steam Matrix (Entrance Zone Only) *)
SteamInj(
    Enable := OvenStart AND NOT OvenEmergency,
    ProductDetect := TRUE,  (* Simulated IO *)
    TargetFlow := SteamInj.TargetFlow,
    SteamPressure := 3.0,   (* Simulated IO *)
    Zone1Temp := ActualTops[1]
);

END_PROGRAM

(*
    =========================================================================================================
    Module:        FPSO_TURRET_MOORING_AND_SWIVEL_CONTROLLER
    Version:       3.0 (Enterprise Production Grade)
    Author:        Lead Marine Engineer / Synthetic Data Architect
    Date:          2026-08-21
    Standard:      IEC 61131-3 Structured Text (ST)
    Description:   Highly complex control system for a Floating Production Storage and Offloading (FPSO) 
                   Subsea Turret Mooring and Swivel System.

    Sub-Systems Included:
    1. Multiphase crude oil flow routing across rotating high-pressure swivels.
    2. Turret bearing lubrication and wear-debris monitoring.
    3. Active heading control (weathervaning) utilizing azimuth thrusters.

    Safety Integrity Level: SIL 3 capable, redundant sensor voting included.
    =========================================================================================================
*)

TYPE 
    // Enumerations for system states
    E_TurretState : (TS_INIT, TS_READY, TS_OPERATIONAL, TS_DEGRADED, TS_EMERGENCY_SHUTDOWN);
    E_FlowState   : (FS_ISOLATED, FS_RAMPING, FS_STEADY_STATE, FS_TRIPPED);
    E_LubeState   : (LS_STANDBY, LS_PRELUBE, LS_NOMINAL, LS_HIGH_WEAR, LS_FAULT);
    E_HeadingMode : (HM_MANUAL, HM_AUTO_WEATHERVANE, HM_STATION_KEEPING);

    // Structs for complex data
    ST_SwivelData : STRUCT
        PressureInlet   : REAL; (* Bar *)
        PressureOutlet  : REAL; (* Bar *)
        Temp            : REAL; (* Celsius *)
        Vibration       : REAL; (* mm/s RMS *)
        SealLeakRate    : REAL; (* L/min *)
        IsIsolated      : BOOL;
    END_STRUCT;

    ST_BearingData : STRUCT
        LubePressure    : REAL; (* Bar *)
        LubeTemp        : REAL; (* Celsius *)
        WearDebrisCount : DINT; (* Particles/100ml *)
        FrictionTorque  : REAL; (* kNm *)
        IsLubePumpRun   : BOOL;
    END_STRUCT;

    ST_HeadingData : STRUCT
        CurrentHeading  : REAL; (* Degrees 0-359.9 *)
        TargetHeading   : REAL; (* Degrees *)
        WindSpeed       : REAL; (* knots *)
        WindDir         : REAL; (* Degrees *)
        WaveHeight      : REAL; (* meters *)
        WaveDir         : REAL; (* Degrees *)
    END_STRUCT;

    ST_ThrusterCmd : STRUCT
        AzimuthAngle    : REAL; (* Degrees 0-359.9 *)
        PitchThrust     : REAL; (* % -100 to 100 *)
        Enable          : BOOL;
    END_STRUCT;
END_TYPE


(*===================================================================
  Function Block: FB_MultiphaseSwivelRouting
  Description: Manages flow of crude oil through the HP swivel stack.
               Includes leak detection and differential pressure monitoring.
====================================================================*)
FUNCTION_BLOCK FB_MultiphaseSwivelRouting
VAR_INPUT
    SwivelA       : ST_SwivelData;
    SwivelB       : ST_SwivelData;
    ESD_Active    : BOOL; (* Emergency Shutdown *)
    FlowCmd       : E_FlowState;
END_VAR
VAR_OUTPUT
    ActualState   : E_FlowState;
    ValveACmd     : BOOL;
    ValveBCmd     : BOOL;
    LeakAlarm     : BOOL;
    DpAlarm       : BOOL;
END_VAR
VAR
    TmrLeak       : TON;
    TmrRamping    : TON;
    MaxDP         : REAL := 15.0; (* Max allowable pressure drop across swivel *)
    MaxLeak       : REAL := 2.5;  (* Max allowable seal leak rate *)
END_VAR

    // Leak Detection Logic
    LeakAlarm := (SwivelA.SealLeakRate > MaxLeak) OR (SwivelB.SealLeakRate > MaxLeak);
    TmrLeak(IN := LeakAlarm, PT := T#5S);

    // Differential Pressure Logic
    DpAlarm := (ABS(SwivelA.PressureInlet - SwivelA.PressureOutlet) > MaxDP) OR 
               (ABS(SwivelB.PressureInlet - SwivelB.PressureOutlet) > MaxDP);

    // Flow State Machine
    IF ESD_Active OR TmrLeak.Q THEN
        ActualState := E_FlowState.FS_TRIPPED;
    END_IF;

    CASE ActualState OF
        E_FlowState.FS_ISOLATED:
            ValveACmd := FALSE;
            ValveBCmd := FALSE;
            IF FlowCmd = E_FlowState.FS_RAMPING AND NOT ESD_Active THEN
                ActualState := E_FlowState.FS_RAMPING;
            END_IF;

        E_FlowState.FS_RAMPING:
            ValveACmd := TRUE;
            ValveBCmd := TRUE;
            TmrRamping(IN:=TRUE, PT:=T#30S);
            IF TmrRamping.Q THEN
                ActualState := E_FlowState.FS_STEADY_STATE;
                TmrRamping(IN:=FALSE);
            END_IF;

        E_FlowState.FS_STEADY_STATE:
            IF FlowCmd = E_FlowState.FS_ISOLATED THEN
                ActualState := E_FlowState.FS_ISOLATED;
            END_IF;

        E_FlowState.FS_TRIPPED:
            ValveACmd := FALSE;
            ValveBCmd := FALSE;
            IF NOT ESD_Active AND NOT TmrLeak.Q AND FlowCmd = E_FlowState.FS_ISOLATED THEN
                ActualState := E_FlowState.FS_ISOLATED;
            END_IF;
    END_CASE;

END_FUNCTION_BLOCK


(*===================================================================
  Function Block: FB_TurretBearingMonitor
  Description: Controls lubrication and monitors wear debris in the main turret bearing.
====================================================================*)
FUNCTION_BLOCK FB_TurretBearingMonitor
VAR_INPUT
    BearingSensors : ST_BearingData;
    TurretRotSpeed : REAL; (* RPM *)
END_VAR
VAR_OUTPUT
    LubePumpCmd    : BOOL;
    State          : E_LubeState;
    WearWarning    : BOOL;
    CriticalFault  : BOOL;
END_VAR
VAR
    DebrisLimitWarning  : DINT := 500;
    DebrisLimitCritical : DINT := 2000;
    MinLubePress        : REAL := 4.5; (* Bar *)
    TmrFault            : TON;
END_VAR

    // Wear Debris Analysis
    WearWarning := (BearingSensors.WearDebrisCount >= DebrisLimitWarning);

    // State Evaluation
    IF BearingSensors.WearDebrisCount >= DebrisLimitCritical THEN
        State := E_LubeState.LS_FAULT;
    ELSIF WearWarning THEN
        State := E_LubeState.LS_HIGH_WEAR;
    ELSIF ABS(TurretRotSpeed) > 0.1 AND BearingSensors.LubePressure >= MinLubePress THEN
        State := E_LubeState.LS_NOMINAL;
    ELSE
        State := E_LubeState.LS_STANDBY;
    END_IF;

    // Pump Control
    IF ABS(TurretRotSpeed) > 0.05 OR State = E_LubeState.LS_HIGH_WEAR THEN
        LubePumpCmd := TRUE;
    ELSE
        LubePumpCmd := FALSE;
    END_IF;

    // Fault Trigger
    TmrFault(IN := (LubePumpCmd AND BearingSensors.LubePressure < MinLubePress), PT := T#10S);
    CriticalFault := TmrFault.Q OR (State = E_LubeState.LS_FAULT);

END_FUNCTION_BLOCK


(*===================================================================
  Function Block: FB_WeathervaneControl
  Description: Computes heading errors based on environmental inputs and commands azimuth thrusters.
====================================================================*)
FUNCTION_BLOCK FB_WeathervaneControl
VAR_INPUT
    EnvData       : ST_HeadingData;
    ModeCmd       : E_HeadingMode;
    EnableSys     : BOOL;
END_VAR
VAR_OUTPUT
    ActiveMode    : E_HeadingMode;
    ThrusterFwd   : ST_ThrusterCmd;
    ThrusterAft   : ST_ThrusterCmd;
    HeadingError  : REAL;
END_VAR
VAR
    PID_Kp : REAL := 2.5;
    PID_Ki : REAL := 0.1;
    PID_Kd : REAL := 5.0;
    IntegError : REAL;
    PrevError  : REAL;
    ControlOut : REAL;
    OptimalHeading : REAL;
END_VAR

    IF NOT EnableSys THEN
        ThrusterFwd.Enable := FALSE;
        ThrusterAft.Enable := FALSE;
        ActiveMode := E_HeadingMode.HM_MANUAL;
        RETURN;
    END_IF;

    ActiveMode := ModeCmd;

    // Determine target heading based on mode
    IF ActiveMode = E_HeadingMode.HM_AUTO_WEATHERVANE THEN
        // Simplified environmental force vectoring (Wind and Waves)
        OptimalHeading := (EnvData.WindDir * 0.6) + (EnvData.WaveDir * 0.4);

        // Normalize
        IF OptimalHeading >= 360.0 THEN OptimalHeading := OptimalHeading - 360.0; END_IF;
        HeadingError := OptimalHeading - EnvData.CurrentHeading;

    ELSIF ActiveMode = E_HeadingMode.HM_STATION_KEEPING THEN
        HeadingError := EnvData.TargetHeading - EnvData.CurrentHeading;
    ELSE
        HeadingError := 0.0;
    END_IF;

    // Wrap error to -180 to +180
    IF HeadingError > 180.0 THEN HeadingError := HeadingError - 360.0; END_IF;
    IF HeadingError < -180.0 THEN HeadingError := HeadingError + 360.0; END_IF;

    // PID Computation for Yaw Moment
    IntegError := IntegError + (HeadingError * 0.1); (* Assuming 100ms cycle *)
    // Anti-windup
    IF IntegError > 50.0 THEN IntegError := 50.0; END_IF;
    IF IntegError < -50.0 THEN IntegError := -50.0; END_IF;

    ControlOut := (PID_Kp * HeadingError) + (PID_Ki * IntegError) + (PID_Kd * (HeadingError - PrevError)/0.1);
    PrevError := HeadingError;

    // Thruster Allocation (Differential Pitching for Yaw)
    IF ActiveMode <> E_HeadingMode.HM_MANUAL THEN
        ThrusterFwd.Enable := TRUE;
        ThrusterAft.Enable := TRUE;

        // Azimuth angles set perpendicular to vessel centerline for maximum yaw moment
        ThrusterFwd.AzimuthAngle := 90.0;
        ThrusterAft.AzimuthAngle := 270.0;

        // Saturate thrust
        IF ControlOut > 100.0 THEN ControlOut := 100.0; END_IF;
        IF ControlOut < -100.0 THEN ControlOut := -100.0; END_IF;

        ThrusterFwd.PitchThrust := ControlOut;
        ThrusterAft.PitchThrust := -ControlOut; (* Counter-acting to create pure couple *)
    END_IF;

END_FUNCTION_BLOCK


(*===================================================================
  PROGRAM: MAIN_TURRET_CONTROLLER
  Description: Top-level instantiation and orchestration of the FPSO Turret System.
====================================================================*)
PROGRAM MAIN_TURRET_CONTROLLER
VAR
    // Sub-system instances
    FluidRouting     : FB_MultiphaseSwivelRouting;
    BearingMonitor   : FB_TurretBearingMonitor;
    WeathervaneSys   : FB_WeathervaneControl;

    // Global I/O and System State
    SysState         : E_TurretState := E_TurretState.TS_INIT;
    GlobalESD        : BOOL;

    // Process Variables
    CurrentSwivelA   : ST_SwivelData;
    CurrentSwivelB   : ST_SwivelData;
    CurrentBearing   : ST_BearingData;
    TurretRPM        : REAL;
    Environment      : ST_HeadingData;

    // Control Commands
    FlowReq          : E_FlowState;
    WeathervaneReq   : E_HeadingMode;
END_VAR

    // 1. Evaluate Overall System State
    IF GlobalESD OR BearingMonitor.CriticalFault OR FluidRouting.LeakAlarm THEN
        SysState := E_TurretState.TS_EMERGENCY_SHUTDOWN;
    ELSIF BearingMonitor.WearWarning OR FluidRouting.DpAlarm THEN
        SysState := E_TurretState.TS_DEGRADED;
    ELSIF SysState = E_TurretState.TS_INIT THEN
        SysState := E_TurretState.TS_READY;
    ELSE
        SysState := E_TurretState.TS_OPERATIONAL;
    END_IF;

    // 2. Execute Subsea Turret Bearing Monitor
    BearingMonitor(
        BearingSensors := CurrentBearing,
        TurretRotSpeed := TurretRPM
    );

    // 3. Execute Multiphase Swivel Routing
    IF SysState = E_TurretState.TS_EMERGENCY_SHUTDOWN THEN
        FlowReq := E_FlowState.FS_ISOLATED;
    END_IF;

    FluidRouting(
        SwivelA    := CurrentSwivelA,
        SwivelB    := CurrentSwivelB,
        ESD_Active := GlobalESD OR (SysState = E_TurretState.TS_EMERGENCY_SHUTDOWN),
        FlowCmd    := FlowReq
    );

    // 4. Execute Weathervaning Control
    WeathervaneSys(
        EnvData   := Environment,
        ModeCmd   := WeathervaneReq,
        EnableSys := (SysState = E_TurretState.TS_OPERATIONAL) OR (SysState = E_TurretState.TS_DEGRADED)
    );

END_PROGRAM

