        RETURN;
    END_IF;

    // ------------------------------------------------------------------------------
    // 1. LEAN/RICH MEA CROSS-HEAT EXCHANGER THERMAL BALANCING
    // ------------------------------------------------------------------------------
    // Calculate heat transferred on both sides [Q = m * Cp * dT] / 3600 for kW
    #rHeatTransfer_HotSide := (#rLeanMEA_MassFlow * #rCp_MEA_30wt * (#rLeanMEA_Temp_ExchangerIn - #rLeanMEA_Temp_ExchangerOut)) / 3600.0;
    #rHeatTransfer_ColdSide := (#rRichMEA_MassFlow * #rCp_MEA_30wt * (#rRichMEA_Temp_ExchangerOut - #rRichMEA_Temp_ExchangerIn)) / 3600.0;

    // Efficiency Calculation (Cold Side Heat Gained / Hot Side Heat Lost)
    IF #rHeatTransfer_HotSide > 0.0 THEN
        #rThermalEfficiency := (#rHeatTransfer_ColdSide / #rHeatTransfer_HotSide) * 100.0;
    ELSE
        #rThermalEfficiency := 0.0;
    END_IF;

    // Thermal Imbalance Alarm (Triggers if heat transfer deviates by more than 15%)
    #instTON_ThermalImbalance(IN := ABS(#rHeatTransfer_HotSide - #rHeatTransfer_ColdSide) > (#rHeatTransfer_HotSide * 0.15),
                              PT := T#1M);
    #bAlarm_ThermalImbalance := #instTON_ThermalImbalance.Q;

    // PID Control for Bypass Valve to maintain target Rich MEA feed temp to stripper
    #instPID_ThermalBypass(
        Setpoint := #rTarget_RichMEA_StripperInTemp,
        Input := #rRichMEA_Temp_ExchangerOut,
        Reset := #bResetAlarms,
        Mode := 3, // Auto mode
        Output => #tempBypassPID_Out
    );

    // Reverse acting loop formulation wrapper
    #rLeanMEA_BypassValveSetPt := LIMIT(MN := 0.0, IN := #tempBypassPID_Out, MX := 100.0);

    // ------------------------------------------------------------------------------
    // 2. STRIPPER COLUMN STEAM REBOILER DUTY CALCULATION
    // ------------------------------------------------------------------------------
    // Dynamic calculation of Steam Latent Heat based on Header Pressure (simplified formulation)
    #rEnthalpySteam := #c_SteamBaseEnthalpy + (5.0 * (#rSteam_HeaderPressure - 3.0));
    #rEnthalpyCondensate := #rReboiler_CondensateTemp * #c_CondensateCp;
    #tempLatentHeat := #rEnthalpySteam - #rEnthalpyCondensate;

    // Reboiler PID Temperature Control (Maintains Stripper Bottom Temp)
    #instPID_ReboilerTemp(
        Setpoint := #rStripper_BottomTemp_SP,
        Input := #rStripper_BottomTemp,
        Reset := #bResetAlarms,
        Mode := 3,
        Output => #tempReboilerPID_Out
    );
    #rSteam_ControlValveSetPt := LIMIT(MN := 0.0, IN := #tempReboilerPID_Out, MX := 100.0);

    // Real-time Duty Calculation (Estimating steam mass flow based on max valve Cv capacity)
    #rCalc_SteamDemand_KgH := (#rSteam_ControlValveSetPt / 100.0) * 15000.0; // Assuming 15T/hr max

    // Reboiler Duty [MW] = (MassFlow [kg/h] * LatentHeat [kJ/kg]) / 3600000
    #rCalc_ReboilerDuty_MW := (#rCalc_SteamDemand_KgH * #tempLatentHeat) / 3600000.0;

    // ------------------------------------------------------------------------------
    // 3. FLUE GAS ABSORBER COLUMN FOAMING DETECTION & ANTI-FOAM DOSING
    // ------------------------------------------------------------------------------
    // Foaming is detected by analyzing abnormal differential pressure across the absorber bed 
    // relative to the current flue gas flow rate (Ergun equation principle).

    // Moving Average for DP to filter noise
    #arrDP_Buffer[#iDP_BufferIndex] := #rAbsorber_DiffPressure;
    #iDP_BufferIndex := (#iDP_BufferIndex + 1) MOD 20;

    #tempSumDP := 0.0;
    FOR #i := 0 TO 19 DO
        #tempSumDP := #tempSumDP + #arrDP_Buffer[#i];
    END_FOR;
    #rDP_MovingAverage := #tempSumDP / 20.0;

    // Base expected DP = k * Q^2 (k = 0.000015 heuristically mapped)
    #rExpectedDP := 0.000015 * (#rAbsorber_FlueGasFlow * #rAbsorber_FlueGasFlow);

    // Detect Foaming (DP deviates significantly from theoretical flow-based DP)
    IF (#rAbsorber_FlueGasFlow > #c_MinFlueGasFlow) THEN
        #instTON_FoamDetect(IN := (#rDP_MovingAverage - #rExpectedDP) > #c_MaxDP_Deviation,
                            PT := T#30S);
    ELSE
        #instTON_FoamDetect(IN := FALSE, PT := T#30S);
    END_IF;

    #bAlarm_FoamingDetected := #instTON_FoamDetect.Q;

    // Anti-Foam Dosing Logic (Auto-dose for 5 minutes once detected)
    #instTOF_DosingDuration(IN := #bAlarm_FoamingDetected,
                            PT := T#5M);

    #bAntiFoam_DosingPumpCmd := #instTOF_DosingDuration.Q;

    IF #bAntiFoam_DosingPumpCmd THEN
        // Modulate dosing rate based on severity of DP deviation
        #rAntiFoam_DosingRateSetPt := LIMIT(MN := 20.0, 
                                            IN := ((#rDP_MovingAverage - #rExpectedDP) / #c_MaxDP_Deviation) * 50.0, 
                                            MX := 100.0);
    ELSE
        #rAntiFoam_DosingRateSetPt := 0.0;
    END_IF;

    // ==============================================================================
    // FAULT RESET HANDLING
    // ==============================================================================
    IF #bResetAlarms THEN
        #bAlarm_FoamingDetected := FALSE;
        #bAlarm_ThermalImbalance := FALSE;
        #bAlarm_ReboilerDutyDev := FALSE;
    END_IF;

END_FUNCTION_BLOCK
