FUNCTION_BLOCK FB_Pyrolysis_Depolymerization_Controller
VAR_INPUT
    bStart_Sequence           : BOOL;  // Initiates the full automated pyrolysis cycle
    bEmergency_Stop           : BOOL;  // Triggers immediate inert dump and microwave isolation
    rReactor_Temp_PV          : REAL;  // Process Value: Internal reactor temperature [°C]
    rReactor_Pressure_PV      : REAL;  // Process Value: Internal reactor pressure [bar]
    rNitrogen_Purity_PV       : REAL;  // Process Value: Oxygen content inside reactor [%]
    rMicrowave_Reflect_PV     : REAL;  // Process Value: Reflected microwave power [kW]
    bColumn_Level_High        : BOOL;  // Fractional distillation column syncrude level status
END_VAR

VAR_OUTPUT
    bNitrogen_Valve_Open      : BOOL;  // N2 purging valve
    rMicrowave_Power_SP       : REAL;  // Setpoint: Command power to magnetrons [kW]
    bSyncrude_Pump_Run        : BOOL;  // Initiates syncrude recovery sequence
    bOff_Gas_Vent_Open        : BOOL;  // Opens off-gas flaring or recovery vent
    iSystem_State             : INT;   // 0=Idle, 10=Purging, 20=Heating, 30=Reaction, 40=Recovery, 99=Fault
END_VAR

VAR
    fbTemp_PID                : PID;   // Core temperature loop evolved into matrix controller
    fbPurge_Timer             : TON;   // N2 blanket timer
    fbReaction_Timer          : TON;   // Main depolymerization phase timer

    // Internal States
    bPurge_Complete           : BOOL;
    bTemp_Reached             : BOOL;

    // Constraints
    rMax_Temp_Limit           : REAL := 550.0; // Max optimal depolymerization temp [°C]
    rO2_Threshold             : REAL := 1.5;   // Max allowable oxygen before combustion risk [%]
    rMicrowave_Max_Power      : REAL := 150.0; // kW
END_VAR

// ----------------------------------------------------------------------------------------------------
// 1. SAFETY & EMERGENCY INTERLOCKS
// ----------------------------------------------------------------------------------------------------
IF bEmergency_Stop OR rReactor_Pressure_PV > 5.0 THEN
    iSystem_State := 99;
END_IF;

IF iSystem_State = 99 THEN
    bNitrogen_Valve_Open := TRUE;   // Flood with inert gas
    rMicrowave_Power_SP := 0.0;     // Kill heating matrices immediately
    bSyncrude_Pump_Run := FALSE;
    bOff_Gas_Vent_Open := TRUE;     // Relieve pressure
    RETURN; // Halt further processing
END_IF;

// ----------------------------------------------------------------------------------------------------
// 2. STATE MACHINE LOGIC
// ----------------------------------------------------------------------------------------------------
CASE iSystem_State OF

    0: // IDLE
        bNitrogen_Valve_Open := FALSE;
        rMicrowave_Power_SP := 0.0;
        bSyncrude_Pump_Run := FALSE;
        bOff_Gas_Vent_Open := FALSE;

        IF bStart_Sequence THEN
            iSystem_State := 10;
        END_IF;

    10: // N2 PURGING (Inert Blanketing)
        bNitrogen_Valve_Open := TRUE;
        fbPurge_Timer(IN:=TRUE, PT:=T#5M); // 5 minute volumetric purge

        IF fbPurge_Timer.Q AND (rNitrogen_Purity_PV < rO2_Threshold) THEN
            fbPurge_Timer(IN:=FALSE); // Reset
            iSystem_State := 20;
        END_IF;

    20: // MICROWAVE-ASSISTED HEATING (Rapid C-C Cleavage)
        // Advanced PID mapping to Microwave Arrays
        fbTemp_PID(
            ACTUAL := rReactor_Temp_PV,
            SET_POINT := 480.0, // Target depolymerization temperature
            KP := 2.5, KI := 0.1, KD := 0.5,
            Y_MIN := 0.0, Y_MAX := rMicrowave_Max_Power
        );
        rMicrowave_Power_SP := fbTemp_PID.Y;

        // Microwave protection logic (Reflected power cutoff)
        IF rMicrowave_Reflect_PV > (rMicrowave_Power_SP * 0.15) THEN
            // If > 15% power reflected back, reduce power to save magnetrons
            rMicrowave_Power_SP := rMicrowave_Power_SP * 0.5;
        END_IF;

        IF rReactor_Temp_PV >= 475.0 THEN
            bTemp_Reached := TRUE;
            iSystem_State := 30;
        END_IF;

    30: // DEPOLYMERIZATION & OFF-GAS SEQUENCING
        // Maintain Temperature
        fbTemp_PID(ACTUAL := rReactor_Temp_PV, SET_POINT := 480.0);
        rMicrowave_Power_SP := fbTemp_PID.Y;

        fbReaction_Timer(IN:=TRUE, PT:=T#45M);

        // Fractional Distillation Off-Gas sequencing
        // Pressure regulation to push vapors into column
        IF rReactor_Pressure_PV > 1.2 THEN
            bOff_Gas_Vent_Open := TRUE;
        ELSIF rReactor_Pressure_PV < 0.9 THEN
            bOff_Gas_Vent_Open := FALSE;
        END_IF;

        IF fbReaction_Timer.Q THEN
            fbReaction_Timer(IN:=FALSE);
            iSystem_State := 40;
        END_IF;

    40: // SYNCRUDE RECOVERY (Fractional Distillation Extract)
        rMicrowave_Power_SP := 0.0; // Cool down phase
        bOff_Gas_Vent_Open := TRUE; // Flush remaining vapors

        // Pump syncrude when level in fractional distillation column is adequate
        IF bColumn_Level_High THEN
            bSyncrude_Pump_Run := TRUE;
        ELSE
            bSyncrude_Pump_Run := FALSE;
        END_IF;

        IF rReactor_Temp_PV < 100.0 THEN
            iSystem_State := 0; // Return to idle once cooled
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
