```iec61131-3
(* 
   =============================================================================
   CRYOGENIC NGL RECOVERY CONTROLLER
   =============================================================================
   Version:      4.2
   Module:       FB_CryogenicNGLRecovery
   Description:  Comprehensive Process Control for Natural Gas Liquid Recovery
                 incorporating:
                  - Turbo-Expander bypass / Joule-Thomson valve sequencing
                  - De-ethanizer & De-propanizer thermal profiling
                  - Molecular sieve dehydration bed regeneration arrays
   =============================================================================
*)

FUNCTION_BLOCK FB_CryogenicNGLRecovery

VAR_INPUT
    // Process Inputs: Dehydration Bed Temperatures & Pressures
    rBed1_Temp         : REAL; (* Deg C *)
    rBed2_Temp         : REAL; (* Deg C *)
    rBed1_Moisture     : REAL; (* ppm *)
    rBed2_Moisture     : REAL; (* ppm *)

    // Process Inputs: Turbo-Expander / JT Valve
    rInletGas_Press    : REAL; (* barg *)
    rInletGas_Temp     : REAL; (* Deg C *)
    rExpander_Speed    : REAL; (* RPM *)
    rExpander_Vib      : REAL; (* mm/s *)

    // Process Inputs: Fractionation Train (De-Ethanizer & De-Propanizer)
    rDeEthanizer_BtmTemp : REAL;
    rDeEthanizer_TopTemp : REAL;
    rDeEthanizer_Press   : REAL;

    rDePropanizer_BtmTemp: REAL;
    rDePropanizer_TopTemp: REAL;
    rDePropanizer_Press  : REAL;

    // System Commands
    bSystemStart       : BOOL;
    bSystemStop        : BOOL;
    bEmergencyShutdown : BOOL;
END_VAR

VAR_OUTPUT
    // Dehydration Bed Controls
    bBed1_RegenHeater  : BOOL;
    bBed2_RegenHeater  : BOOL;
    rBed1_RegenGasValve: REAL; (* 0-100% *)
    rBed2_RegenGasValve: REAL; (* 0-100% *)

    // Expander / JT Valve Controls
    rJT_Valve_Command  : REAL; (* 0-100% *)
    rExpander_IGV      : REAL; (* Inlet Guide Vanes 0-100% *)
    bExpander_Trip     : BOOL;

    // Fractionation Tower Controls
    rDeEth_ReboilerSteamValve : REAL; (* 0-100% *)
    rDeEth_RefluxValve        : REAL; (* 0-100% *)

    rDeProp_ReboilerSteamValve: REAL; (* 0-100% *)
    rDeProp_RefluxValve       : REAL; (* 0-100% *)

    // Alarms and Status
    wSystemStatus      : WORD;
    bAlarmHighMoisture : BOOL;
    bAlarmExpanderVib  : BOOL;
END_VAR

VAR
    // PID Controllers for Towers
    pidDeEthReflux     : FB_PID;
    pidDeEthReboiler   : FB_PID;
    pidDePropReflux    : FB_PID;
    pidDePropReboiler  : FB_PID;

    // PID Controllers for Expander / JT
    pidJT_Pressure     : FB_PID;
    pidExpander_Speed  : FB_PID;

    // Dehydration Bed State Machine
    eRegenStateBed1    : INT; (* 0: STANDBY, 1: HEATING, 2: COOLING, 3: ADSORPTION *)
    eRegenStateBed2    : INT; (* 0: STANDBY, 1: HEATING, 2: COOLING, 3: ADSORPTION *)
    tRegenTimerBed1    : TON;
    tRegenTimerBed2    : TON;

    // Internal Variables
    bExpanderActive    : BOOL;
END_VAR

(* -----------------------------------------------------------------------------
   1. Emergency Shutdown (ESD) Handling
   ----------------------------------------------------------------------------- *)
IF bEmergencyShutdown THEN
    // Close all critical valves and trip rotating equipment
    rJT_Valve_Command := 0.0;
    rExpander_IGV := 0.0;
    bExpander_Trip := TRUE;

    bBed1_RegenHeater := FALSE;
    bBed2_RegenHeater := FALSE;
    rBed1_RegenGasValve := 0.0;
    rBed2_RegenGasValve := 0.0;

    rDeEth_ReboilerSteamValve := 0.0;
    rDeEth_RefluxValve := 0.0;
    rDeProp_ReboilerSteamValve := 0.0;
    rDeProp_RefluxValve := 0.0;

    wSystemStatus := 16#FFFF; // ESD State
    RETURN; // Halt further processing
END_IF;

(* -----------------------------------------------------------------------------
   2. Molecular Sieve Dehydration Bed Regeneration Arrays
   ----------------------------------------------------------------------------- *)
// Monitor Moisture Alarms
bAlarmHighMoisture := (rBed1_Moisture > 5.0 AND eRegenStateBed1 = 3) OR 
                      (rBed2_Moisture > 5.0 AND eRegenStateBed2 = 3);

// Simplified Lead/Lag Bed Swap Logic
IF eRegenStateBed1 = 3 AND rBed1_Moisture > 1.0 AND eRegenStateBed2 = 0 THEN
    eRegenStateBed1 := 1; // HEATING
    eRegenStateBed2 := 3; // ADSORPTION
ELSIF eRegenStateBed2 = 3 AND rBed2_Moisture > 1.0 AND eRegenStateBed1 = 0 THEN
    eRegenStateBed2 := 1; // HEATING
    eRegenStateBed1 := 3; // ADSORPTION
END_IF;

// Bed 1 State Machine
CASE eRegenStateBed1 OF
    0: // STANDBY
        bBed1_RegenHeater := FALSE;
        rBed1_RegenGasValve := 0.0;

    1: // HEATING
        bBed1_RegenHeater := TRUE;
        rBed1_RegenGasValve := 100.0;
        IF rBed1_Temp > 280.0 THEN // Regeneration temp reached
            tRegenTimerBed1(IN:=TRUE, PT:=T#4H);
            IF tRegenTimerBed1.Q THEN
                eRegenStateBed1 := 2; // COOLING
                tRegenTimerBed1(IN:=FALSE);
            END_IF;
        END_IF;

    2: // COOLING
        bBed1_RegenHeater := FALSE;
        rBed1_RegenGasValve := 50.0; // Cooling gas flow
        IF rBed1_Temp < 40.0 THEN // Cooled down
            eRegenStateBed1 := 0; // STANDBY
        END_IF;

    3: // ADSORPTION
        bBed1_RegenHeater := FALSE;
        rBed1_RegenGasValve := 0.0;
END_CASE;

// Bed 2 State Machine (Symmetric to Bed 1)
CASE eRegenStateBed2 OF
    0: // STANDBY
        bBed2_RegenHeater := FALSE;
        rBed2_RegenGasValve := 0.0;

    1: // HEATING
        bBed2_RegenHeater := TRUE;
        rBed2_RegenGasValve := 100.0;
        IF rBed2_Temp > 280.0 THEN
            tRegenTimerBed2(IN:=TRUE, PT:=T#4H);
            IF tRegenTimerBed2.Q THEN
                eRegenStateBed2 := 2; // COOLING
                tRegenTimerBed2(IN:=FALSE);
            END_IF;
        END_IF;

    2: // COOLING
        bBed2_RegenHeater := FALSE;
        rBed2_RegenGasValve := 50.0;
        IF rBed2_Temp < 40.0 THEN
            eRegenStateBed2 := 0; // STANDBY
        END_IF;

    3: // ADSORPTION
        bBed2_RegenHeater := FALSE;
        rBed2_RegenGasValve := 0.0;
END_CASE;


(* -----------------------------------------------------------------------------
   3. Turbo-Expander Bypass & Joule-Thomson (JT) Valve Sequencing
   ----------------------------------------------------------------------------- *)
// Expander vibration monitoring
bAlarmExpanderVib := (rExpander_Vib > 15.0);

IF bAlarmExpanderVib THEN
    bExpander_Trip := TRUE;
END_IF;

IF bExpander_Trip THEN
    // If Expander trips, seamlessly switch to JT Valve for pressure drop
    bExpanderActive := FALSE;
    rExpander_IGV := 0.0;

    // JT Valve takes over pressure control to maintain plant throughput
    pidJT_Pressure(
        ACT := rInletGas_Press,
        SET := 60.0, (* barg target for cold separator *)
        KP := 1.5,
        TN := 5.0,
        TV := 0.0
    );
    rJT_Valve_Command := pidJT_Pressure.Y;
ELSE
    bExpanderActive := TRUE;
    // Expander controls pressure drop/temperature drop
    pidExpander_Speed(
        ACT := rExpander_Speed,
        SET := 35000.0, (* Target RPM for optimal isoentropic expansion *)
        KP := 0.8,
        TN := 10.0,
        TV := 2.0
    );
    rExpander_IGV := pidExpander_Speed.Y;

    // JT Valve stays in standby (closed or minimal bypass)
    rJT_Valve_Command := 0.0; 
END_IF;


(* -----------------------------------------------------------------------------
   4. Fractional Distillation Thermal Profiling (De-Eth / De-Prop)
   ----------------------------------------------------------------------------- *)
// De-Ethanizer Control:
// Top temperature dictates ethane purity (Reflux Control)
pidDeEthReflux(
    ACT := rDeEthanizer_TopTemp,
    SET := -10.0, 
    KP := 2.0,
    TN := 120.0
);
rDeEth_RefluxValve := pidDeEthReflux.Y;

// Bottom temperature dictates remaining NGL liquids (Reboiler Steam Control)
pidDeEthReboiler(
    ACT := rDeEthanizer_BtmTemp,
    SET := 105.0,
    KP := 1.5,
    TN := 180.0
);
rDeEth_ReboilerSteamValve := pidDeEthReboiler.Y;

// De-Propanizer Control:
// Top temperature dictates propane purity
pidDePropReflux(
    ACT := rDePropanizer_TopTemp,
    SET := 45.0, 
    KP := 2.5,
    TN := 90.0
);
rDeProp_RefluxValve := pidDePropReflux.Y;

// Bottom temperature dictates butane+ (C4+) composition
pidDePropReboiler(
    ACT := rDePropanizer_BtmTemp,
    SET := 120.0,
    KP := 1.8,
    TN := 180.0
);
rDeProp_ReboilerSteamValve := pidDePropReboiler.Y;

END_FUNCTION_BLOCK
