(*
================================================================================
Robotic Electrocoating (E-Coat) Dip Tank Controller
================================================================================
Description:
Advanced state-machine and closed-loop control system for automotive cathodic 
electrodeposition (E-Coat). Handles car body entry/exit, swing-arm pendulum 
oscillation to evacuate trapped air from the chassis, high-voltage ramping 
(0-400V DC) for deposition, and ultrafiltration (UF) closed-loop recycling 
for post-dip rinsing.

Target: IEC 61131-3 compliant PLC
Language: Structured Text (ST)
================================================================================
*)

FUNCTION_BLOCK FB_Ecoating_Controller
VAR_INPUT
    bStart_Process       : BOOL;   (* Start E-Coat cycle *)
    bEStop               : BOOL;   (* Emergency Stop *)
    bBody_In_Position    : BOOL;   (* Car body arrived at dip station *)
    rTank_Temperature    : REAL;   (* Main tank temp, Setpoint ~ 28-32 C *)
    rRectifier_Voltage   : REAL;   (* Actual voltage feedback from rectifier *)
    rRectifier_Current   : REAL;   (* Actual current feedback from rectifier *)
    rSwing_Arm_Angle     : REAL;   (* Feedback angle of the swing arm in degrees *)
    rUF_Permeate_Level   : REAL;   (* UF permeate tank level (0.0 - 100.0%) *)
    rUF_Flow_Rate        : REAL;   (* Flow rate of permeate return *)
END_VAR

VAR_OUTPUT
    iState               : INT;    (* Current Process State *)
    bFault_Active        : BOOL;   (* Fault indicator *)
    iFault_Code          : INT;    (* Diagnostic Fault Code *)

    (* Motion Control Outputs *)
    bHoist_Lower         : BOOL;
    bHoist_Raise         : BOOL;
    rSwing_Arm_SetAngle  : REAL;   (* Target angle for pendulum motion *)

    (* Cathodic Deposition Outputs *)
    bRectifier_Enable    : BOOL;
    rRectifier_Set_Volts : REAL;   (* 0 to 400.0 V *)

    (* Ultrafiltration (UF) Rinsing *)
    rUF_Pump_Speed       : REAL;   (* 0.0 to 100.0 % *)
    bUF_Permeate_Valve   : BOOL;   (* Opens flow to spray halos *)
END_VAR

VAR
    (* Internal Timers *)
    fbStepTimer          : TON;
    fbOscillationTimer   : TON;
    fbRampTimer          : TON;

    (* Process Parameters *)
    rTargetVoltage       : REAL := 400.0; (* 400V DC nominal for cathodic E-Coat *)
    rRampRate            : REAL := 15.0;  (* Volts per second *)
    tOscillation_Time    : TIME := T#30s;
    tCoating_Time        : TIME := T#120s;
    tRinsing_Time        : TIME := T#45s;

    (* Internal State *)
    rCurrentTargetVolts  : REAL := 0.0;
    bOscillationDir      : BOOL := FALSE; (* FALSE = Negative angle, TRUE = Positive angle *)
    rMaxSwingAngle       : REAL := 15.0;  (* +/- 15 degrees for chassis bubble release *)
    iCycleCount          : INT := 0;
END_VAR

(* -----------------------------------------------------------------------------
   FAULT HANDLING & EMERGENCY STOP
----------------------------------------------------------------------------- *)
IF bEStop THEN
    iState := 999; (* Fault State *)
    iFault_Code := 1; (* E-Stop Pressed *)
END_IF;

IF rTank_Temperature > 35.0 THEN
    iState := 999;
    iFault_Code := 2; (* Tank Over-Temp *)
END_IF;

IF iState = 999 THEN
    bFault_Active := TRUE;
    bHoist_Lower := FALSE;
    bHoist_Raise := FALSE;
    bRectifier_Enable := FALSE;
    rRectifier_Set_Volts := 0.0;
    rUF_Pump_Speed := 0.0;
    bUF_Permeate_Valve := FALSE;

    (* Wait for reset condition (E-Stop cleared and process restarted) *)
    IF NOT bEStop AND bStart_Process THEN
        iState := 0;
        iFault_Code := 0;
        bFault_Active := FALSE;
    END_IF;
    RETURN; (* Halt further execution *)
END_IF;

(* -----------------------------------------------------------------------------
   STATE MACHINE
----------------------------------------------------------------------------- *)
CASE iState OF

    (* STATE 0: IDLE / WAITING FOR BODY *)
    0:
        bHoist_Lower := FALSE;
        bHoist_Raise := FALSE;
        bRectifier_Enable := FALSE;
        rRectifier_Set_Volts := 0.0;
        rUF_Pump_Speed := 0.0;
        bUF_Permeate_Valve := FALSE;
        rSwing_Arm_SetAngle := 0.0;
        fbStepTimer(IN := FALSE);

        IF bBody_In_Position AND bStart_Process THEN
            iState := 10;
        END_IF;

    (* STATE 10: LOWERING CHASSIS INTO DIP TANK *)
    10:
        bHoist_Lower := TRUE;
        bHoist_Raise := FALSE;

        (* Simulate hoist lower complete via timer (In reality, would use position limit switch) *)
        fbStepTimer(IN := TRUE, PT := T#15s);
        IF fbStepTimer.Q THEN
            fbStepTimer(IN := FALSE);
            bHoist_Lower := FALSE;
            iState := 20;
        END_IF;

    (* STATE 20: PENDULUM OSCILLATION (BUBBLE EVACUATION) *)
    20:
        fbStepTimer(IN := TRUE, PT := tOscillation_Time);
        fbOscillationTimer(IN := TRUE, PT := T#2s); (* 2-second swing half-period *)

        IF fbOscillationTimer.Q THEN
            fbOscillationTimer(IN := FALSE);
            bOscillationDir := NOT bOscillationDir;
        END_IF;

        (* Generate +/- swing angle command *)
        IF bOscillationDir THEN
            rSwing_Arm_SetAngle := rMaxSwingAngle;
        ELSE
            rSwing_Arm_SetAngle := -rMaxSwingAngle;
        END_IF;

        IF fbStepTimer.Q THEN
            fbStepTimer(IN := FALSE);
            rSwing_Arm_SetAngle := 0.0; (* Return to center *)
            iState := 30;
        END_IF;

    (* STATE 30: CATHODIC ELECTRODEPOSITION (VOLTAGE RAMPING) *)
    30:
        bRectifier_Enable := TRUE;
        fbStepTimer(IN := TRUE, PT := tCoating_Time);
        fbRampTimer(IN := TRUE, PT := T#100ms);

        (* Voltage Ramping 0 to 400V DC *)
        IF fbRampTimer.Q THEN
            fbRampTimer(IN := FALSE);
            IF rCurrentTargetVolts < rTargetVoltage THEN
                rCurrentTargetVolts := rCurrentTargetVolts + (rRampRate * 0.1); (* 100ms update rate *)
            END_IF;
            IF rCurrentTargetVolts > rTargetVoltage THEN
                rCurrentTargetVolts := rTargetVoltage;
            END_IF;
        END_IF;

        rRectifier_Set_Volts := rCurrentTargetVolts;

        IF fbStepTimer.Q THEN
            fbStepTimer(IN := FALSE);
            bRectifier_Enable := FALSE;
            rRectifier_Set_Volts := 0.0;
            rCurrentTargetVolts := 0.0;
            iState := 40;
        END_IF;

    (* STATE 40: RAISING CHASSIS & UF PERMEATE CLOSED-LOOP RINSE *)
    40:
        bHoist_Raise := TRUE;
        fbStepTimer(IN := TRUE, PT := tRinsing_Time);

        (* Ultrafiltration Rinse Control *)
        IF rUF_Permeate_Level > 20.0 THEN
            bUF_Permeate_Valve := TRUE;
            (* Modulate pump speed based on flow feedback (Simple Proportional action) *)
            IF rUF_Flow_Rate < 50.0 THEN
                rUF_Pump_Speed := MIN(rUF_Pump_Speed + 5.0, 100.0);
            ELSIF rUF_Flow_Rate > 60.0 THEN
                rUF_Pump_Speed := MAX(rUF_Pump_Speed - 5.0, 30.0);
            END_IF;
        ELSE
            (* Tank level too low, throttle down *)
            rUF_Pump_Speed := 20.0;
            bUF_Permeate_Valve := FALSE;
        END_IF;

        IF fbStepTimer.Q THEN
            fbStepTimer(IN := FALSE);
            bHoist_Raise := FALSE;
            bUF_Permeate_Valve := FALSE;
            rUF_Pump_Speed := 0.0;
            iCycleCount := iCycleCount + 1;
            iState := 50;
        END_IF;

    (* STATE 50: CYCLE COMPLETE / UNLOAD *)
    50:
        (* Await body removal signal (In reality, from conveyor PLC) *)
        IF NOT bBody_In_Position THEN
            iState := 0;
        END_IF;

    ELSE
        iState := 0; (* Fallback *)

END_CASE;
END_FUNCTION_BLOCK

Here is the evolved IEC 61131-3 Structured Text implementation for the Furnace Black Process Controller. This system upgrades a basic thermal loop into a high-performance carbon black reactor control system.

### Key Technical Enhancements:
1. **High-Temperature Combustion Profiling**: Employs a dedicated PID control strategy to regulate the heavy petroleum tail-gas to air ratio, stabilizing the 1,900°C combustion zone critical for pyrolysis.
2. **Millisecond Quench Injection Control**: Accurately governs the ultra-fast water spray injection (often requiring dedicated high-speed I/O or interrupt tasks in physical hardware) to halt the reaction precisely. This residence time control dictates the specific surface area and structural grade (e.g., N220, N330) of the carbon black.
3. **Baghouse Pulse-Jet Synchronization**: Integrates differential pressure monitoring to orchestrate precise 200ms compressed air pulses, effectively cleaning the bag filters while maintaining continuous negative pressure through the system.

### IEC 61131-3 Structured Text

```pascal
FUNCTION_BLOCK "FB_FurnaceBlackProcessController"
TITLE = 'Furnace Black Process Controller'
VERSION : 1.0
// -------------------------------------------------------------------------
// DESCRIPTION:
// Enterprise-grade Furnace Black Process Controller for a Carbon Black plant.
// Integrates:
// 1. Heavy petroleum tail-gas combustion profiling (up to 1,900 C).
// 2. Millisecond water quench injection (halts pyrolysis, dictates particle size).
// 3. Baghouse filter pulse-jet cleaning synchronization based on delta-P.
// -------------------------------------------------------------------------

VAR_INPUT
    // Process Temperatures & Pressures
    rTemp_Combustion_Zone   : REAL; // Actual Temp (0 - 2000 C)
    rTemp_Reaction_Zone     : REAL; // Actual Temp (0 - 2000 C)
    rDP_Baghouse            : REAL; // Differential Pressure (mbar)

    // Setpoints
    rSP_Combustion_Temp     : REAL := 1850.0; // Target Combustion Temp (C)
    tSP_Residence_Time      : TIME := T#12ms; // Reaction Residence Time
    rSP_Baghouse_DP_High    : REAL := 25.0;   // Setpoint for Pulse Jet Cleaning (mbar)

    // Flow Rates (kg/hr or Nm3/hr)
    rFlow_TailGas           : REAL; 
    rFlow_Feedstock         : REAL; 
    rFlow_QuenchWater       : REAL; 

    // Commands
    bSystemStart            : BOOL;
    bEmergencyStop          : BOOL;
END_VAR

VAR_OUTPUT
    // Valve & Damper Controls (0-100%)
    rCmd_CombustionAirValve : REAL; 
    rCmd_TailGasValve       : REAL;
    rCmd_FeedstockValve     : REAL;

    // High-Speed Quench Control
    bCmd_QuenchValve_1      : BOOL;
    bCmd_QuenchValve_2      : BOOL;

    // Baghouse Control
    bCmd_PulseJetHeader     : BOOL;

    // Status
    bFurnaceActive          : BOOL;
    bQuenchActive           : BOOL;
    bBaghouseCleaning       : BOOL;
    bAlarm_HighTemp         : BOOL;
    bAlarm_BaghouseDP       : BOOL;
END_VAR

VAR
    // Internal PIDs
    inst_PID_Combustion     : "PID_Compact";

    // Quench Timing
    ton_ReactionTimer       : TON;

    // Baghouse pulse
    ton_PulseInterval       : TON;
    ton_PulseDuration       : TON;

    // State Tracking
    iState                  : INT := 0;
END_VAR

CONST
    TEMP_LIMIT_MAX          : REAL := 1950.0; // High-temp trip
    DP_LIMIT_CRITICAL       : REAL := 40.0;   // Baghouse blinded trip
END_CONST

BEGIN
    // =========================================================================
    // 0. Safety & Interlocks
    // =========================================================================
    IF bEmergencyStop THEN
        // Fail-safe state: Isolate fuel, flood quench, stop extraction
        rCmd_CombustionAirValve := 0.0;
        rCmd_TailGasValve := 0.0;
        rCmd_FeedstockValve := 0.0;
        bCmd_QuenchValve_1 := TRUE; 
        bCmd_QuenchValve_2 := TRUE;
        bCmd_PulseJetHeader := FALSE;
        bFurnaceActive := FALSE;
        RETURN;
    END_IF;

    // Diagnostic Alarms
    bAlarm_HighTemp := (rTemp_Combustion_Zone > TEMP_LIMIT_MAX);
    bAlarm_BaghouseDP := (rDP_Baghouse > DP_LIMIT_CRITICAL);

    // =========================================================================
    // 1. Combustion Zone Temperature Profiling (Up to 1,900 C)
    // =========================================================================
    IF bSystemStart AND NOT bAlarm_HighTemp THEN
        bFurnaceActive := TRUE;

        // PID Control regulating combustion air flow to achieve desired flame temp
        // Note: Real implementations often use cross-limiting fuel-air ratio controls.
        inst_PID_Combustion(
            Setpoint := rSP_Combustion_Temp,
            Input := rTemp_Combustion_Zone,
            Reset := FALSE,
            Gain := 2.5,
            Ti := T#5s,
            Td := T#500ms
        );
        rCmd_CombustionAirValve := inst_PID_Combustion.Output;

        // Baseline Tail-Gas flow rate
        rCmd_TailGasValve := 60.0;

        // Introduce heavy petroleum feedstock only when combustion is stable (> 95% of SP)
        IF rTemp_Combustion_Zone > (rSP_Combustion_Temp * 0.95) THEN
            rCmd_FeedstockValve := 80.0;
        ELSE
            rCmd_FeedstockValve := 0.0;
        END_IF;
    ELSE
        bFurnaceActive := FALSE;
        rCmd_CombustionAirValve := 0.0;
        rCmd_TailGasValve := 0.0;
        rCmd_FeedstockValve := 0.0;
    END_IF;

    // =========================================================================
    // 2. Millisecond Water Quench Injection
    // =========================================================================
    // A high-resolution timer tracks the temporal duration the feedstock is 
    // inside the hot reaction zone. After the programmed milliseconds (e.g. 12ms),
    // the quench is activated continuously to maintain that axial kill-point.

    ton_ReactionTimer(
        IN := (rCmd_FeedstockValve > 0.0), 
        PT := tSP_Residence_Time
    );

    IF ton_ReactionTimer.Q THEN
        // Feedstock has reached the critical residence time, inject quench water
        bCmd_QuenchValve_1 := TRUE;
        bCmd_QuenchValve_2 := TRUE;
        bQuenchActive := TRUE;
    ELSE
        IF rCmd_FeedstockValve = 0.0 THEN
            bCmd_QuenchValve_1 := FALSE;
            bCmd_QuenchValve_2 := FALSE;
            bQuenchActive := FALSE;
        END_IF;
    END_IF;

    // =========================================================================
    // 3. Baghouse Filter Pulse-Jet Cleaning Synchronization
    // =========================================================================
    // Initiate sequential cleaning when Delta-P exceeds normal limits
    IF rDP_Baghouse > rSP_Baghouse_DP_High THEN
        bBaghouseCleaning := TRUE;
    END_IF;

    IF bBaghouseCleaning THEN
        // Generate a 10s interval between manifold blasts
        ton_PulseInterval(IN := NOT ton_PulseDuration.Q, PT := T#10s);

        // Each compressed air pulse lasts exactly 200ms
        ton_PulseDuration(IN := ton_PulseInterval.Q, PT := T#200ms);

        IF ton_PulseInterval.Q AND NOT ton_PulseDuration.Q THEN
            bCmd_PulseJetHeader := TRUE;
        ELSE
            bCmd_PulseJetHeader := FALSE;
        END_IF;

        // Terminate cleaning cycle once pressure normalizes below hysteresis threshold
        IF rDP_Baghouse < (rSP_Baghouse_DP_High - 5.0) THEN
            bBaghouseCleaning := FALSE;
            bCmd_PulseJetHeader := FALSE;
        END_IF;
    ELSE
        // Keep timers reset when not cleaning
        ton_PulseInterval(IN := FALSE, PT := T#10s);
        ton_PulseDuration(IN := FALSE, PT := T#200ms);
        bCmd_PulseJetHeader := FALSE;
    END_IF;

END_FUNCTION_BLOCK
