```pascal
FUNCTION_BLOCK "FB_Francis_Turbine_Governor"
{ S7_Optimized_Access := 'TRUE' }
AUTHOR : 'Lumina Elite'
FAMILY : 'HydroPower'
VERSION : 3.0
// Lead Infrastructure Engineer - Hydroelectric Dam Turbine Controller
// Evolved from a simple flow control block to a highly complex, mission-critical Francis Turbine Governor and Penstock Controller.
// Features: 
// 1. Wicket Gate Hydraulic Servo Positioning for Megawatt Load Following
// 2. Penstock Surge Tank Monitoring for Water Hammer Prevention
// 3. Generator Rotor Magnetic Field Excitation Loop

VAR_INPUT
    // 1. Grid & Load Following (Megawatt Control)
    ir_Grid_Frequency_Hz : REAL;       // Grid frequency [Hz], nominal 50.0 or 60.0
    ir_Target_MW : REAL;               // Target active power [MW]
    ir_Actual_MW : REAL;               // Actual active power [MW]
    ir_Frequency_Setpoint : REAL := 50.0; // Nominal frequency
    ir_Speed_Droop_Pct : REAL := 4.0;  // Droop characteristic [%]

    // 2. Penstock & Surge Tank Monitoring
    ir_Surge_Tank_Level_m : REAL;      // Surge tank water level [m]
    ir_Penstock_Pressure_bar : REAL;   // Pressure at turbine inlet [bar]
    ir_Max_Pressure_Limit_bar : REAL := 45.0; // Water hammer threshold
    ir_Min_Surge_Level_m : REAL := 120.0;     // Minimum level before tripping

    // 3. Generator Rotor Excitation
    ir_Stator_Voltage_kV : REAL;       // Stator terminal voltage [kV]
    ir_Target_Voltage_kV : REAL := 18.0; // Target terminal voltage
    ir_Rotor_Current_A : REAL;         // Actual excitation current [A]
    ir_Power_Factor : REAL;            // Cos(Phi)

    // 4. Turbine Physical Parameters
    ir_Turbine_RPM : REAL;             // Actual runner speed [RPM]
    ir_Target_RPM : REAL := 150.0;     // Rated synchronous speed
    ir_Wicket_Gate_Pos_Pct : REAL;     // Current guide vane position [%]

    // Control Commands
    ib_System_Start : BOOL;            // Sequence start command
    ib_Emergency_Stop : BOOL;          // Emergency shutdown (fast closure)
    ib_Reset_Faults : BOOL;

    // PID Parameters
    ir_Gov_Kp : REAL := 2.5;
    ir_Gov_Ti : REAL := 5.0;
    ir_Gov_Td : REAL := 1.2;
    ir_AVR_Kp : REAL := 10.0;
    ir_AVR_Ti : REAL := 2.0;
END_VAR

VAR_OUTPUT
    or_Wicket_Gate_Cmd_Pct : REAL;     // Servo valve command for wicket gates [0.0 - 100.0 %]
    or_Excitation_Voltage_Cmd : REAL;  // Command to excitation thyristor bridge [V]
    ob_Main_Inlet_Valve_Open : BOOL;   // MIV control
    ob_Grid_Breaker_Close : BOOL;      // Synchronization breaker
    ob_Water_Hammer_Relief : BOOL;     // Relief valve trigger
    ob_System_Tripped : BOOL;          // General trip flag
    odw_Trip_Code : DWORD;             // Diagnostics code
    or_Governor_State : INT;           // 0=Stop, 1=Startup, 2=Sync, 3=Load, 4=Shutdown
END_VAR

VAR
    // Governor PID State (Speed/Load)
    stat_Gov_Integral : REAL;
    stat_Gov_Prev_Error : REAL;

    // AVR PID State (Voltage/Excitation)
    stat_AVR_Integral : REAL;
    stat_AVR_Prev_Error : REAL;

    // Surge & Pressure filters
    stat_Pressure_Filtered : REAL;
    stat_Level_Filtered : REAL;
    stat_Prev_Gate_Pos : REAL;

    // Timing & Cycle calculation
    stat_LastCycleTime : LREAL;
    stat_DeltaTime_s : REAL;

    // Internal Setpoints
    stat_Calculated_MW_Setpoint : REAL;

    // States & Timers
    stat_Sync_Timer {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
    stat_Brake_Timer {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;

    // Water Hammer protection
    stat_Gate_Closing_Rate : REAL;

    // Temporary Variables (Since VAR_TEMP isn't used here, mapped to STAT)
    temp_Speed_Error : REAL;
    temp_Power_Error : REAL;
    temp_Volt_Error : REAL;
END_VAR

BEGIN
    // Calculate Cycle Time (delta T)
    stat_DeltaTime_s := LREAL_TO_REAL(RUNTIME(stat_LastCycleTime));
    IF stat_DeltaTime_s <= 0.0 OR stat_DeltaTime_s > 1.0 THEN
        stat_DeltaTime_s := 0.05; // 50ms default control loop
    END_IF;

    // Reset Logic
    IF ib_Reset_Faults THEN
        ob_System_Tripped := FALSE;
        odw_Trip_Code := 16#0000_0000;
        ob_Water_Hammer_Relief := FALSE;
    END_IF;

    // Filtering for Hydraulic Transients
    stat_Pressure_Filtered := stat_Pressure_Filtered * 0.9 + ir_Penstock_Pressure_bar * 0.1;
    stat_Level_Filtered := stat_Level_Filtered * 0.95 + ir_Surge_Tank_Level_m * 0.05;

    // Calculate gate rate of change (%/s)
    stat_Gate_Closing_Rate := (stat_Prev_Gate_Pos - ir_Wicket_Gate_Pos_Pct) / stat_DeltaTime_s;
    stat_Prev_Gate_Pos := ir_Wicket_Gate_Pos_Pct;

    // --- CRITICAL PROTECTIONS (Overrides Everything) ---
    // 1. Water Hammer & Surge Prevention
    IF stat_Pressure_Filtered > ir_Max_Pressure_Limit_bar THEN
        // Open bypass relief valve immediately to dissipate pressure wave
        ob_Water_Hammer_Relief := TRUE;
        ob_System_Tripped := TRUE;
        odw_Trip_Code := odw_Trip_Code OR 16#0000_0001; 
    END_IF;

    // 2. Surge Tank Mass Oscillation / Emptying
    IF stat_Level_Filtered < ir_Min_Surge_Level_m THEN
        ob_System_Tripped := TRUE;
        odw_Trip_Code := odw_Trip_Code OR 16#0000_0002;
    END_IF;

    // 3. Overspeed Protection
    IF ir_Turbine_RPM > (ir_Target_RPM * 1.3) THEN
        ob_System_Tripped := TRUE;
        odw_Trip_Code := odw_Trip_Code OR 16#0000_0004;
    END_IF;

    // Emergency Stop
    IF ib_Emergency_Stop THEN
        ob_System_Tripped := TRUE;
        odw_Trip_Code := odw_Trip_Code OR 16#0000_0008;
    END_IF;

    // Trip Handling
    IF ob_System_Tripped THEN
        or_Governor_State := 0; // Stop
        ob_Main_Inlet_Valve_Open := FALSE;
        ob_Grid_Breaker_Close := FALSE;
        or_Excitation_Voltage_Cmd := 0.0;

        // Fast but controlled closure to prevent water hammer
        // If closing rate is too high, limit it.
        IF stat_Gate_Closing_Rate > 15.0 THEN // Max 15% per second closing
            or_Wicket_Gate_Cmd_Pct := ir_Wicket_Gate_Pos_Pct - (15.0 * stat_DeltaTime_s);
        ELSE
            or_Wicket_Gate_Cmd_Pct := 0.0; // Command fully closed
        END_IF;

        or_Wicket_Gate_Cmd_Pct := MAX(IN1:=0.0, IN2:=or_Wicket_Gate_Cmd_Pct);
        stat_Gov_Integral := 0.0;
        stat_AVR_Integral := 0.0;
        RETURN;
    END_IF;

    // --- STATE MACHINE ---
    CASE or_Governor_State OF
        0: // STOPPED
            or_Wicket_Gate_Cmd_Pct := 0.0;
            or_Excitation_Voltage_Cmd := 0.0;
            ob_Grid_Breaker_Close := FALSE;
            IF ib_System_Start THEN
                ob_Main_Inlet_Valve_Open := TRUE;
                or_Governor_State := 1;
            END_IF;

        1: // STARTUP & SPEED NO-LOAD
            // Open wicket gates slightly to overcome breakaway friction
            // Speed PID control targeting ir_Target_RPM
            temp_Speed_Error := ir_Target_RPM - ir_Turbine_RPM;

            stat_Gov_Integral := stat_Gov_Integral + (ir_Gov_Kp / ir_Gov_Ti) * temp_Speed_Error * stat_DeltaTime_s;
            stat_Gov_Integral := LIMIT(MN:=0.0, IN:=stat_Gov_Integral, MX:=40.0); // Limit during startup

            or_Wicket_Gate_Cmd_Pct := (ir_Gov_Kp * temp_Speed_Error) + stat_Gov_Integral - (ir_Gov_Td * (stat_Gov_Prev_Error - temp_Speed_Error) / stat_DeltaTime_s);
            or_Wicket_Gate_Cmd_Pct := LIMIT(MN:=0.0, IN:=or_Wicket_Gate_Cmd_Pct, MX:=40.0);
            stat_Gov_Prev_Error := temp_Speed_Error;

            // Start Excitation (Field Flashing) when RPM > 80%
            IF ir_Turbine_RPM > (ir_Target_RPM * 0.8) THEN
                or_Excitation_Voltage_Cmd := 20.0; // Base flashing voltage
            END_IF;

            // Check for synchronous speed and voltage
            IF ABS(temp_Speed_Error) < 0.5 AND ir_Stator_Voltage_kV >= (ir_Target_Voltage_kV * 0.95) THEN
                or_Governor_State := 2;
            END_IF;

        2: // SYNCHRONIZATION
            // Maintain speed, wait for sync phase match
            stat_Sync_Timer(IN:=TRUE, PT:=T#3s);
            IF stat_Sync_Timer.Q THEN
                ob_Grid_Breaker_Close := TRUE;
                or_Governor_State := 3;
                stat_Gov_Integral := or_Wicket_Gate_Cmd_Pct; // Bumpless transfer
                stat_Sync_Timer(IN:=FALSE, PT:=T#0s);
            END_IF;

        3: // LOAD FOLLOWING (MW Control + Frequency Droop)
            // Primary Frequency Response (Speed Droop)
            // If Grid Freq drops, MW setpoint increases
            stat_Calculated_MW_Setpoint := ir_Target_MW + ((ir_Frequency_Setpoint - ir_Grid_Frequency_Hz) / ir_Frequency_Setpoint) * (100.0 / ir_Speed_Droop_Pct) * ir_Target_MW;

            // Governor PID (Power Control)
            temp_Power_Error := stat_Calculated_MW_Setpoint - ir_Actual_MW;

            stat_Gov_Integral := stat_Gov_Integral + (ir_Gov_Kp / ir_Gov_Ti) * temp_Power_Error * stat_DeltaTime_s;
            // Anti-windup
            stat_Gov_Integral := LIMIT(MN:=0.0, IN:=stat_Gov_Integral, MX:=100.0);

            or_Wicket_Gate_Cmd_Pct := (ir_Gov_Kp * temp_Power_Error) + stat_Gov_Integral;
            or_Wicket_Gate_Cmd_Pct := LIMIT(MN:=0.0, IN:=or_Wicket_Gate_Cmd_Pct, MX:=100.0);

            // AVR PID (Voltage / Reactive Power Control)
            temp_Volt_Error := ir_Target_Voltage_kV - ir_Stator_Voltage_kV;

            stat_AVR_Integral := stat_AVR_Integral + (ir_AVR_Kp / ir_AVR_Ti) * temp_Volt_Error * stat_DeltaTime_s;
            stat_AVR_Integral := LIMIT(MN:=0.0, IN:=stat_AVR_Integral, MX:=250.0); // Exciter ceiling voltage

            or_Excitation_Voltage_Cmd := (ir_AVR_Kp * temp_Volt_Error) + stat_AVR_Integral;
            or_Excitation_Voltage_Cmd := LIMIT(MN:=0.0, IN:=or_Excitation_Voltage_Cmd, MX:=250.0);

            IF NOT ib_System_Start THEN
                or_Governor_State := 4; // Shutdown requested
            END_IF;

        4: // SHUTDOWN
            // Unload turbine smoothly
            or_Wicket_Gate_Cmd_Pct := or_Wicket_Gate_Cmd_Pct - (2.0 * stat_DeltaTime_s); // 2% per second close
            IF ir_Actual_MW < 1.0 THEN
                ob_Grid_Breaker_Close := FALSE; // Open breaker
                or_Excitation_Voltage_Cmd := 0.0; // De-excite
            END_IF;

            IF or_Wicket_Gate_Cmd_Pct <= 0.0 THEN
                or_Wicket_Gate_Cmd_Pct := 0.0;
                ob_Main_Inlet_Valve_Open := FALSE; // Close MIV
                stat_Brake_Timer(IN:=(ir_Turbine_RPM < (ir_Target_RPM*0.2)), PT:=T#5s);
                // Mechanical brakes would apply here in a real system
                IF ir_Turbine_RPM < 1.0 THEN
                    or_Governor_State := 0;
                END_IF;
            END_IF;

    END_CASE;

END_FUNCTION_BLOCK
