    // ---------------- Antisolvent Dynamics ----------------------
    rAntisolvent_Flow_PV     : REAL;          // Actual flow of antisolvent [L/min]
    rFeed_Flow_PV            : REAL;          // API mother liquor feed rate [L/min]

    // ---------------- Target Optimization Parameters ------------
    rTarget_CSD_Mean         : REAL;          // Desired D50 / Mean CSD [um]
    rTarget_Supersaturation  : REAL;          // Setpoint for relative supersaturation [S]
    rMax_Cooling_Rate        : REAL := 1.5;   // DegC/min
END_VAR

VAR_OUTPUT
    // ---------------- Control Elements --------------------------
    rAntisolvent_Flow_SP     : REAL;          // Setpoint to Antisolvent Dosing Coriolis Mass Flow Meter
    rJacket_Temp_SP          : REAL;          // Setpoint to TCU (Temperature Control Unit) Cascade
    rAgitator_Speed_SP       : REAL;          // Setpoint for VFD Agitator [RPM]

    // ---------------- Sequencing & Status -----------------------
    eStatus                  : E_Cryst_Status; // (IDLE, SEEDING, GROWTH, MATURATION, DISCHARGE, FAULT)
    xAntisolvent_Valve_Open  : BOOL;          // Discrete trigger for dosing valve sequence

    // ---------------- Diagnostics & Alarms ----------------------
    rCurrent_Supersat_Ratio  : REAL;          // S = C/C*
    rNucleation_Penalty      : REAL;          // Calculated risk of secondary nucleation
    xAlarm_MSZW_Violation    : BOOL;          // True if trajectory crosses labile zone
    xAlarm_Fines_Spike       : BOOL;          // True if massive fine generation detected
END_VAR

VAR
    // ---------------- Internal State Machines & Timers ----------
    nState                   : INT;
    fbMaturationTimer        : TON;
    fbDosingPulseTimer       : TON;

    // ---------------- PID & Optimization Controllers ------------
    fbPID_Supersaturation    : FB_PID_Advanced; // Evolved from basic PID
    fbPID_Temperature        : FB_PID_Advanced; 

    // ---------------- CSD Optimization Matrices -----------------
    // Let M = Population Balance Model (PBM) transformation matrix (simplified 10x10 representation)
    arrGrowthMatrix          : ARRAY[1..10, 1..10] OF REAL; 
    arrNucleationVector      : ARRAY[1..10] OF REAL;
    arrCurrentCSD_State      : ARRAY[1..10] OF REAL;
    arrPredictedCSD_State    : ARRAY[1..10] OF REAL;

    // ---------------- Internal Registers ------------------------
    rError_CSD               : REAL;
    i                        : INT;
    j                        : INT;
    rMatrixSum               : REAL;
    rDosing_Rate_Base        : REAL;
    rDosing_Rate_Opt         : REAL;
    rSupersat_Integral       : REAL;
    xSeed_Detected           : BOOL;

    // Constants
    c_MSZW_UpperLimit        : REAL := 1.25;  // Supersaturation limit before spontaneous nucleation
    c_MSZW_LowerLimit        : REAL := 1.05;  // Minimum to drive crystal growth
END_VAR

// ===================================================================================================
// SYSTEM INTERLOCKS & SAFETY
// ===================================================================================================
IF xEmergencyStop THEN
    rAntisolvent_Flow_SP := 0.0;
    rJacket_Temp_SP := rTemperature_PT100; // Hold temperature
    rAgitator_Speed_SP := 50.0;            // Minimum safe suspension speed
    xAntisolvent_Valve_Open := FALSE;
    eStatus := E_Cryst_Status.FAULT;
    RETURN;
END_IF

IF xReset THEN
    xAlarm_MSZW_Violation := FALSE;
    xAlarm_Fines_Spike := FALSE;
    eStatus := E_Cryst_Status.IDLE;
END_IF

IF NOT xEnable THEN
    rAntisolvent_Flow_SP := 0.0;
    eStatus := E_Cryst_Status.IDLE;
    RETURN;
END_IF

// ===================================================================================================
// 1. SUPERSATURATION CALCULATION & CLOSED-LOOP CONTROL
// ===================================================================================================
// S = Actual Concentration / Solubility Limit at Current T and Antisolvent Ratio
IF rSolubility_Curve_Val > 0.0 THEN
    rCurrent_Supersat_Ratio := rConcentration_ATR_FTIR / rSolubility_Curve_Val;
ELSE
    rCurrent_Supersat_Ratio := 0.0;
END_IF

// Detect MSZW (Metastable Zone Width) Boundary Violations
IF rCurrent_Supersat_Ratio > c_MSZW_UpperLimit THEN
    xAlarm_MSZW_Violation := TRUE;
    // Fast corrective action: Increase temperature to dissolve fines and lower supersaturation
    rJacket_Temp_SP := rJacket_Temp_SP + 2.0; 
END_IF

// PID Controller for Supersaturation (Manipulated Variable = Cooling Rate & Antisolvent Flow)
fbPID_Supersaturation(
    xEnable     := (eStatus = E_Cryst_Status.GROWTH),
    rSetpoint   := rTarget_Supersaturation,
    rProcessVal := rCurrent_Supersat_Ratio,
    rKp         := 2.5,
    rKi         := 0.1,
    rKd         := 0.05,
    rTs         := 1.0,  // 1 second execution cycle
    rOutput     => rDosing_Rate_Base
);

// ===================================================================================================
// 2. FBRM / PAT INTEGRATION & FINES DETECTION
// ===================================================================================================
// Detect Secondary Nucleation (Massive spike in fines < 10um)
IF rFines_Fraction > 0.15 AND rMean_Chord_Length < (rTarget_CSD_Mean * 0.5) THEN
    xAlarm_Fines_Spike := TRUE;
    rNucleation_Penalty := 100.0; // High penalty for optimization
ELSE
    xAlarm_Fines_Spike := FALSE;
    rNucleation_Penalty := 0.0;
END_IF

// ===================================================================================================
// 3. CRYSTAL SIZE DISTRIBUTION (CSD) OPTIMIZATION MATRICES
// ===================================================================================================
// Simplified Population Balance Model (PBM) execution using real-time FBRM data mapping
// Map raw FBRM array (1..100) to 10-bin model state
FOR i := 1 TO 10 DO
    arrCurrentCSD_State[i] := 0.0;
    FOR j := 1 TO 10 DO
        arrCurrentCSD_State[i] := arrCurrentCSD_State[i] + arrFBRM_Counts_Per_Sec[(i-1)*10 + j];
    END_FOR
END_FOR

// Matrix Multiplication: Predicted_State = GrowthMatrix * Current_State + NucleationVector
FOR i := 1 TO 10 DO
    rMatrixSum := 0.0;
    FOR j := 1 TO 10 DO
        rMatrixSum := rMatrixSum + (arrGrowthMatrix[i, j] * arrCurrentCSD_State[j]);
    END_FOR
    arrPredictedCSD_State[i] := rMatrixSum + arrNucleationVector[i] * rCurrent_Supersat_Ratio;
END_FOR

// Calculate CSD Error based on target mean bin (assume bin 7 is target)
rError_CSD := arrPredictedCSD_State[7] - (arrCurrentCSD_State[7] * 1.1); // Aiming for 10% growth in target bin

// Adjust Dosing based on CSD Prediction
IF rError_CSD < 0.0 THEN
    // Growth is too slow, increase supersaturation slightly via antisolvent optimization factor
    rDosing_Rate_Opt := rDosing_Rate_Base * 1.05;
ELSIF xAlarm_Fines_Spike THEN
    // Stop antisolvent addition to suppress nucleation
    rDosing_Rate_Opt := 0.0;
ELSE
    rDosing_Rate_Opt := rDosing_Rate_Base;
END_IF

// ===================================================================================================
// 4. ANTISOLVENT ADDITION SEQUENCING & STATE MACHINE
// ===================================================================================================
CASE eStatus OF

    E_Cryst_Status.IDLE:
        rAntisolvent_Flow_SP := 0.0;
        xAntisolvent_Valve_Open := FALSE;
        rAgitator_Speed_SP := 60.0; // Suspend solids
        IF xEnable AND rConcentration_ATR_FTIR > 0.0 THEN
            eStatus := E_Cryst_Status.SEEDING;
        END_IF

    E_Cryst_Status.SEEDING:
        // Wait for external seeding event (detected by FBRM counts jumping)
        IF arrCurrentCSD_State[3] > 100.0 THEN // Arbitrary seed threshold in bin 3
            xSeed_Detected := TRUE;
            eStatus := E_Cryst_Status.GROWTH;
        END_IF

    E_Cryst_Status.GROWTH:
        // Continuous API crystallization main loop
        rAntisolvent_Flow_SP := LIMIT(0.0, rDosing_Rate_Opt, 50.0); // Limit max flow to 50 L/min

        // Pulse valve sequence if flow is too low to maintain continuous flow (prevent line clogging)
        IF rAntisolvent_Flow_SP > 0.0 AND rAntisolvent_Flow_SP < 5.0 THEN
            fbDosingPulseTimer(IN := NOT fbDosingPulseTimer.Q, PT := T#5S);
            IF fbDosingPulseTimer.ET < T#2S THEN
                xAntisolvent_Valve_Open := TRUE;
                rAntisolvent_Flow_SP := 12.5; // Pulse at higher rate
            ELSE
                xAntisolvent_Valve_Open := FALSE;
                rAntisolvent_Flow_SP := 0.0;
            END_IF
        ELSE
            xAntisolvent_Valve_Open := (rAntisolvent_Flow_SP > 0.0);
        END_IF

        // Transition to maturation if batch/semi-continuous conditions are met
        IF rFines_Fraction < 0.05 AND rMean_Chord_Length >= rTarget_CSD_Mean THEN
            eStatus := E_Cryst_Status.MATURATION;
        END_IF

    E_Cryst_Status.MATURATION:
        // Hold state to allow ostwald ripening (dissolving remaining fines)
        rAntisolvent_Flow_SP := 0.0;
        xAntisolvent_Valve_Open := FALSE;
        // Thermal cycling for ripening
        fbMaturationTimer(IN := TRUE, PT := T#60M);

        IF (fbMaturationTimer.ET MOD T#20M) < T#10M THEN
            rJacket_Temp_SP := rJacket_Temp_SP + 5.0; // Heat cycle
        ELSE
            rJacket_Temp_SP := rJacket_Temp_SP - 5.0; // Cool cycle
        END_IF

        IF fbMaturationTimer.Q THEN
            eStatus := E_Cryst_Status.DISCHARGE;
        END_IF

    E_Cryst_Status.DISCHARGE:
        // Transfer to filter dryer / centrifuge
        rAntisolvent_Flow_SP := 0.0;
        xAntisolvent_Valve_Open := FALSE;
        rAgitator_Speed_SP := 120.0; // High speed to prevent settling during transfer
        IF NOT xEnable THEN
            eStatus := E_Cryst_Status.IDLE;
        END_IF

    E_Cryst_Status.FAULT:
        // Handled by interlocks block at top

END_CASE

END_FUNCTION_BLOCK

(*
================================================================================================
Wafer Stepper Reticle Stage Controller - 6-DOF Magnetic Levitation & EUV Synchronization
================================================================================================
Version: 3.4.1 (Enterprise Fab Edition)
Engineer: Lead Mechatronics Engineer
Compliance: IEC 61131-3
Description: 
Advanced control system for a reticle stage in a photolithography wafer stepper. 
Implements 6-DOF magnetic levitation control with picometer (pm) resolution utilizing
multi-axis laser interferometry. Incorporates feed-forward jerk minimization to stabilize
projection optics during 100g max acceleration profiles. Synchronizes with Extreme 
Ultraviolet (EUV) light source pulsing for optimal dose delivery.
================================================================================================
*)

TYPE ST_6DOF_POSITION :
STRUCT
    X  : LREAL; (* X-axis translation [pm] *)
    Y  : LREAL; (* Y-axis translation [pm] *)
    Z  : LREAL; (* Z-axis translation [pm] *)
    Rx : LREAL; (* Pitch (rotation around X) [urad] *)
    Ry : LREAL; (* Roll (rotation around Y) [urad] *)
    Rz : LREAL; (* Yaw (rotation around Z) [urad] *)
END_STRUCT
END_TYPE

TYPE ST_EUV_SYNC :
STRUCT
    DoseTarget     : LREAL; (* Target energy dose [mJ/cm2] *)
    PulseRate      : LREAL; (* EUV pulse repetition rate [Hz] *)
    SyncJitter     : LREAL; (* Acceptable jitter [ns] *)
    TriggerEnabled : BOOL;  (* Pulse trigger active flag *)
    SourceReady    : BOOL;  (* EUV plasma source status *)
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_ReticleStageController
VAR_INPUT
    Enable              : BOOL;
    EmergencyStop       : BOOL;
    TargetPosition      : ST_6DOF_POSITION;
    InterferometerRawX  : ARRAY[0..3] OF LINT; (* Multi-beam X reading [pm] *)
    InterferometerRawY  : ARRAY[0..3] OF LINT; (* Multi-beam Y reading [pm] *)
    InterferometerRawZ  : ARRAY[0..3] OF LINT; (* Multi-beam Z reading [pm] *)
    EUVSyncParams       : ST_EUV_SYNC;
    TrajectoryClock     : LREAL; (* System high-res trajectory time [s] *)
END_VAR

VAR_OUTPUT
    CurrentPosition     : ST_6DOF_POSITION;
    PositionError       : ST_6DOF_POSITION;
    LevitationForces    : ARRAY[0..7] OF LREAL; (* 8 Maglev Actuators Forces [N] *)
    EUVTrigger          : BOOL;
    LensVibrationAlarm  : BOOL;
    StageReady          : BOOL;
    CurrentJerk         : LREAL; (* [m/s^3] *)
END_VAR

VAR_INPUT CONSTANT
    MAX_ACCEL     : LREAL := 981.0; (* 100g in m/s^2 *)
    MAX_JERK      : LREAL := 50000.0; (* m/s^3 *)
    MASS_STAGE    : LREAL := 15.5; (* kg *)
    CG_OFFSET     : ARRAY[0..2] OF LREAL := [0.0, 0.0, -0.015];
END_VAR

VAR
    (* State Variables *)
    LastPosition      : ST_6DOF_POSITION;
    LastVelocity      : ST_6DOF_POSITION;
    LastAccel         : ST_6DOF_POSITION;
    LastTime          : LREAL;

    (* Kinematic calculations *)
    Vel_X, Accel_X, Jerk_X : LREAL;
    Vel_Y, Accel_Y, Jerk_Y : LREAL;

    (* Filter & PID *)
    Kp, Ki, Kd : ARRAY[0..5] OF LREAL := [6(25000.0)]; 
    FeedForwardJerkX : LREAL;
    FeedForwardJerkY : LREAL;

    (* Maglev matrix *)
    TransformMatrix : ARRAY[0..7, 0..5] OF LREAL;

    (* Internal Timing *)
    dt : LREAL;
    PulseTimer : LREAL;
END_VAR

(* --- 1. Emergency Stop & Safety Validation --- *)
IF EmergencyStop THEN
    StageReady := FALSE;
    EUVTrigger := FALSE;
    FOR i := 0 TO 7 DO
        LevitationForces[i] := 0.0; (* Safe drop to catch-blocks *)
    END_FOR
    RETURN;
END_IF;

IF NOT Enable THEN
    StageReady := FALSE;
    EUVTrigger := FALSE;
    RETURN;
END_IF;

(* --- 2. 6-DOF High-Resolution Position Tracking (Picometer Resolution) --- *)
(* In a real implementation, a geometric transformation maps multiple interferometer
   beams to the center of gravity. Simplified averaging here for demonstration. *)
CurrentPosition.X := LINT_TO_LREAL(InterferometerRawX[0] + InterferometerRawX[1] + InterferometerRawX[2] + InterferometerRawX[3]) / 4.0;
CurrentPosition.Y := LINT_TO_LREAL(InterferometerRawY[0] + InterferometerRawY[1] + InterferometerRawY[2] + InterferometerRawY[3]) / 4.0;
CurrentPosition.Z := LINT_TO_LREAL(InterferometerRawZ[0] + InterferometerRawZ[1] + InterferometerRawZ[2] + InterferometerRawZ[3]) / 4.0;

(* Calculate errors in pm *)
PositionError.X := TargetPosition.X - CurrentPosition.X;
PositionError.Y := TargetPosition.Y - CurrentPosition.Y;
PositionError.Z := TargetPosition.Z - CurrentPosition.Z;

(* --- 3. Kinematics & Feed-Forward Jerk Minimization --- *)
dt := TrajectoryClock - LastTime;
IF dt > 0.0 THEN
    (* Derivatives for X-axis (convert pm to m for dynamic calculation) *)
    Vel_X := ((CurrentPosition.X - LastPosition.X) * 1.0E-12) / dt;
    Accel_X := (Vel_X - LastVelocity.X) / dt;
    Jerk_X := (Accel_X - LastAccel.X) / dt;

    (* Derivatives for Y-axis *)
    Vel_Y := ((CurrentPosition.Y - LastPosition.Y) * 1.0E-12) / dt;
    Accel_Y := (Vel_Y - LastVelocity.Y) / dt;
    Jerk_Y := (Accel_Y - LastAccel.Y) / dt;

    CurrentJerk := SQRT(Jerk_X * Jerk_X + Jerk_Y * Jerk_Y);

    (* Jerk Minimization: Pre-shaping force commands to counteract high-frequency excitation 
       Prevent lens vibration during 100g maneuvers. We employ derivative feed-forward control. *)
    IF CurrentJerk > MAX_JERK THEN
        LensVibrationAlarm := TRUE;
    ELSE
        LensVibrationAlarm := FALSE;
    END_IF;

    FeedForwardJerkX := (Jerk_X / MAX_JERK) * (MASS_STAGE * 0.1); 
    FeedForwardJerkY := (Jerk_Y / MAX_JERK) * (MASS_STAGE * 0.1);
END_IF;

(* --- 4. Magnetic Levitation Actuator Allocation --- *)
(* Simple diagonal PID with Feed-Forward *)
VAR
    ForceCmd : ARRAY[0..5] OF LREAL;
    i : INT;
END_VAR

ForceCmd[0] := (Kp[0] * PositionError.X * 1.0E-12) + (MASS_STAGE * Accel_X) - FeedForwardJerkX;
ForceCmd[1] := (Kp[1] * PositionError.Y * 1.0E-12) + (MASS_STAGE * Accel_Y) - FeedForwardJerkY;
ForceCmd[2] := (Kp[2] * PositionError.Z * 1.0E-12) + (MASS_STAGE * 9.81); (* Gravity comp *)
ForceCmd[3] := Kp[3] * PositionError.Rx * 1.0E-6;
ForceCmd[4] := Kp[4] * PositionError.Ry * 1.0E-6;
ForceCmd[5] := Kp[5] * PositionError.Rz * 1.0E-6;

(* Distribute logical forces to 8 physical maglev coils via pseudo-inverse transform matrix 
   (Matrix values assumed pre-calculated during initialization) *)
FOR i := 0 TO 7 DO
    LevitationForces[i] := TransformMatrix[i,0]*ForceCmd[0] + 
                           TransformMatrix[i,1]*ForceCmd[1] + 
                           TransformMatrix[i,2]*ForceCmd[2] + 
                           TransformMatrix[i,3]*ForceCmd[3] + 
                           TransformMatrix[i,4]*ForceCmd[4] + 
                           TransformMatrix[i,5]*ForceCmd[5];
END_FOR;

(* --- 5. EUV Light Source Synchronization --- *)
IF EUVSyncParams.SourceReady AND EUVSyncParams.TriggerEnabled THEN
    (* Check if position is within scanning slit tolerance (+/- 500 pm) *)
    IF ABS(PositionError.X) < 500.0 AND ABS(PositionError.Y) < 500.0 THEN
        StageReady := TRUE;

        (* EUV pulse generation based on precise velocity integration (spatial triggering) *)
        PulseTimer := PulseTimer + dt;
        IF PulseTimer >= (1.0 / EUVSyncParams.PulseRate) THEN
            EUVTrigger := TRUE;
            PulseTimer := 0.0;
        ELSE
            EUVTrigger := FALSE;
        END_IF;
    ELSE
        StageReady := FALSE;
        EUVTrigger := FALSE;
    END_IF;
ELSE
    StageReady := FALSE;
    EUVTrigger := FALSE;
END_IF;

(* Update historical states *)
LastPosition := CurrentPosition;
LastVelocity.X := Vel_X; LastVelocity.Y := Vel_Y;
LastAccel.X := Accel_X; LastAccel.Y := Accel_Y;
LastTime := TrajectoryClock;

END_FUNCTION_BLOCK

(*
    =============================================================================
    BLOCK: FB_AmineScrubberController
    DESCRIPTION: 
    Enterprise-grade CO2 Stripping Controller for Monoethanolamine (MEA) 
    capture plants. Integrates cross-heat exchanger balancing, reboiler duty 
    calculation based on fundamental thermodynamics, and advanced foaming 
    detection using differential pressure pattern recognition.
    =============================================================================
*)

TYPE ST_MeaProperties :
STRUCT
    Density           : REAL; (* kg/m3 *)
    SpecificHeat      : REAL; (* kJ/kg.K *)
    Concentration     : REAL; (* wt % *)
    CO2Loading        : REAL; (* mol CO2 / mol MEA *)
END_STRUCT
END_TYPE

TYPE ST_SteamProperties :
STRUCT
    Pressure          : REAL; (* bar *)
    Temperature       : REAL; (* C *)
    Enthalpy          : REAL; (* kJ/kg *)
    LatentHeat        : REAL; (* kJ/kg *)
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_PID_Adv
VAR_INPUT
    Setpoint          : REAL;
    ProcessValue      : REAL;
    Kp, Ki, Kd        : REAL;
    Ts                : REAL; (* Sample time in sec *)
    OutMin, OutMax    : REAL;
    Reset             : BOOL;
END_VAR
VAR_OUTPUT
    ControlOut        : REAL;
END_VAR
VAR
    Error             : REAL;
    LastError         : REAL;
    Integral          : REAL;
    Derivative        : REAL;
END_VAR
Error := Setpoint - ProcessValue;
IF Reset THEN
    Integral := 0.0;
    LastError := Error;
END_IF;
Integral := Integral + (Error * Ts);
(* Anti-windup *)
IF Integral > (OutMax / Ki) AND Ki <> 0.0 THEN
    Integral := OutMax / Ki;
ELSIF Integral < (OutMin / Ki) AND Ki <> 0.0 THEN
    Integral := OutMin / Ki;
END_IF;
Derivative := (Error - LastError) / Ts;
ControlOut := (Kp * Error) + (Ki * Integral) + (Kd * Derivative);
IF ControlOut > OutMax THEN ControlOut := OutMax; END_IF;
IF ControlOut < OutMin THEN ControlOut := OutMin; END_IF;
LastError := Error;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_MovingAverage
VAR_INPUT
    InValue           : REAL;
    Enable            : BOOL;
END_VAR
VAR_OUTPUT
    OutAvg            : REAL;
    OutRateOfChange   : REAL;
END_VAR
VAR
    Buffer            : ARRAY[1..10] OF REAL;
    Idx               : INT := 1;
    Sum               : REAL;
    i                 : INT;
    LastAvg           : REAL;
    Initialized       : BOOL;
END_VAR
IF Enable THEN
    IF NOT Initialized THEN
        FOR i := 1 TO 10 DO
            Buffer[i] := InValue;
        END_FOR;
        Initialized := TRUE;
    END_IF;
    Buffer[Idx] := InValue;
    Idx := Idx + 1;
    IF Idx > 10 THEN Idx := 1; END_IF;
    Sum := 0.0;
    FOR i := 1 TO 10 DO
        Sum := Sum + Buffer[i];
    END_FOR;
    LastAvg := OutAvg;
    OutAvg := Sum / 10.0;
    OutRateOfChange := OutAvg - LastAvg;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_AmineScrubberController
VAR_INPUT
    (* 1. Heat Exchanger Inputs *)
    rTempRichMEA_In   : REAL; (* C *)
    rTempLeanMEA_In   : REAL; (* C *)
    rFlowRichMEA      : REAL; (* kg/h *)
    rFlowLeanMEA      : REAL; (* kg/h *)

    (* 2. Reboiler Inputs *)
    stRichMEA         : ST_MeaProperties;
    stLeanMEA         : ST_MeaProperties;
    stSteam           : ST_SteamProperties;
    rTempStripperBot  : REAL; (* C *)
    rTempStripperTop  : REAL; (* C *)

    (* 3. Foaming Detection Inputs *)
    rAbsorberDP       : REAL; (* mbar *)
    rFlueGasFlow      : REAL; (* Nm3/h *)
    rAbsorberLevel    : REAL; (* mm *)

    bSystemEnable     : BOOL;
    rCycleTime        : REAL; (* Seconds *)
END_VAR
VAR_OUTPUT
    rBypassValvePos   : REAL; (* 0-100% *)
    rSteamValvePos    : REAL; (* 0-100% *)
    bAntiFoamPumpRun  : BOOL;
    rAntiFoamSpeed    : REAL; (* 0-100% *)

    rCalcDuty         : REAL; (* kW *)
    bFoamingAlarm     : BOOL;
    bHeatImbalance    : BOOL;
END_VAR
VAR
    (* Exchanger Balancing *)
    pidHxBypass       : FB_PID_Adv;
    rTargetLeanTempOut: REAL := 40.0; (* C *)
    rEstLeanTempOut   : REAL;
    rHeatCapacityRatio: REAL;

    (* Reboiler Duty Variables *)
    rSensibleHeat     : REAL;
    rDesorptionHeat   : REAL;
    rVaporizationHeat : REAL;
    rTotalDutyReq     : REAL; (* kJ/h *)
    pidReboiler       : FB_PID_Adv;
    rSteamFlowReq     : REAL; (* kg/h *)

    (* Foaming Detection *)
    maAbsorberDP      : FB_MovingAverage;
    timerFoam         : TON;
    rDPRateThreshold  : REAL := 5.0; (* mbar/s *)
    rDPAbsoluteLimit  : REAL := 150.0; (* mbar *)
END_VAR

IF NOT bSystemEnable THEN
    rBypassValvePos := 0.0;
    rSteamValvePos := 0.0;
    bAntiFoamPumpRun := FALSE;
    RETURN;
END_IF;

(*********************************************************
  1. Lean/Rich MEA Heat Exchanger Thermal Balancing
*********************************************************)
(* Q_rich_gain = Q_lean_loss *)
rHeatCapacityRatio := (rFlowRichMEA * stRichMEA.SpecificHeat) / 
                      MAX(1.0, (rFlowLeanMEA * stLeanMEA.SpecificHeat));

pidHxBypass(
    Setpoint := rTargetLeanTempOut,
    ProcessValue := rTempLeanMEA_In - (rTempRichMEA_In * rHeatCapacityRatio),
    Kp := 2.5, Ki := 0.1, Kd := 0.5,
    Ts := rCycleTime,
    OutMin := 0.0, OutMax := 100.0,
    Reset := NOT bSystemEnable,
    ControlOut => rBypassValvePos
);

bHeatImbalance := ABS(rFlowRichMEA - rFlowLeanMEA) > (0.2 * rFlowRichMEA);

(*********************************************************
  2. Stripper Column Steam Reboiler Duty Calculation
*********************************************************)
rSensibleHeat := rFlowRichMEA * stRichMEA.SpecificHeat * (rTempStripperBot - rTempRichMEA_In);

(* Heat of Desorption for CO2 release *)
rDesorptionHeat := (stRichMEA.CO2Loading - stLeanMEA.CO2Loading) * 
                   rFlowRichMEA * stRichMEA.Concentration * 1900.0;

rVaporizationHeat := rFlowRichMEA * 0.05 * 2260.0;

rTotalDutyReq := rSensibleHeat + rDesorptionHeat + rVaporizationHeat;
rCalcDuty := rTotalDutyReq / 3600.0;

IF stSteam.LatentHeat > 0.0 THEN
    rSteamFlowReq := rTotalDutyReq / stSteam.LatentHeat;
ELSE
    rSteamFlowReq := 0.0;
END_IF;

pidReboiler(
    Setpoint := rSteamFlowReq,
    ProcessValue := (rSteamValvePos / 100.0) * 5000.0,
    Kp := 1.2, Ki := 0.05, Kd := 0.1,
    Ts := rCycleTime,
    OutMin := 0.0, OutMax := 100.0,
    Reset := NOT bSystemEnable,
    ControlOut => rSteamValvePos
);

(*********************************************************
  3. Absorber Foaming Detection & Anti-Foam Dosing
*********************************************************)
maAbsorberDP(InValue := rAbsorberDP, Enable := bSystemEnable);

IF (maAbsorberDP.OutRateOfChange > rDPRateThreshold AND rFlueGasFlow > 0.0) 
   OR (rAbsorberDP > rDPAbsoluteLimit) THEN
    bFoamingAlarm := TRUE;
ELSE
    bFoamingAlarm := FALSE;
END_IF;

timerFoam(IN := bFoamingAlarm, PT := T#5S);

IF timerFoam.Q THEN
    bAntiFoamPumpRun := TRUE;
    rAntiFoamSpeed := 75.0;
    IF rAbsorberDP > (rDPAbsoluteLimit * 1.2) THEN
        rAntiFoamSpeed := 100.0;
    END_IF;
ELSE
    bAntiFoamPumpRun := FALSE;
    rAntiFoamSpeed := 0.0;
END_IF;

END_FUNCTION_BLOCK

# CERN Large Hadron Collider / High-Luminosity Superconducting RF Cavity & 1.8K Cryogenic Control Architecture

## 1. Thermodynamic & Aerodynamic Engineering Rationale

### 1.1 Superfluid Helium-II Thermodynamics & London Two-Fluid Formulation
At sub-atmospheric pressures below the lambda point ($T_\lambda = 2.1768\text{ K}$ at $P_\lambda = 50.4\text{ mbar}$), liquid Helium-4 undergoes a second-order quantum phase transition into superfluid Helium-II. In this regime, the bulk fluid behaves according to Tisza and London's two-fluid hydrodynamics:
$$\rho = \rho_n + \rho_s$$
where $\rho_n$ is the normal fluid component possessing finite dynamic viscosity $\eta_n$ and carrying all entropy $S$, while $\rho_s$ is the superfluid component with zero viscosity ($\curl \mathbf{v}_s = 0$) and zero entropy.

The superfluid density ratio as a function of temperature is approximated empirically for real-time PLC evaluation as:
$$\frac{\rho_s}{\rho}(T) = 1.0 - \left( \frac{T}{T_\lambda} \right)^{5.6} \quad (T < T_\lambda)$$

At the target baseline operating temperature $T_0 = 1.800\text{ K}$, the superfluid fraction exceeds $65.5\%$. The saturated vapor pressure at $1.800\text{ K}$ is governed by the empirical He-4 vapor pressure formulation (ITS-90):
$$P_{sat}(1.800\text{ K}) \approx 16.38\text{ mbar} \quad (1638\text{ Pa})$$

#### Gorter-Mellink Heat Transport Regime
Unlike classical fluids where Fourier conduction $\mathbf{q} = -k \nabla T$ applies, heat transport in He-II is dominated by internal thermal counterflow. The heat flux is limited by mutual friction between quantized vortex lines and the normal fluid component:
$$q = \left( \frac{1}{f(T)} \frac{dT}{dx} \right)^{1/3} \quad \left[ \text{W/m}^2 \right]$$
where $f(T)$ is the Gorter-Mellink thermal resistance function. This non-linear mechanism delivers an effective thermal conductivity several thousand times greater than high-purity copper ($RRR > 300$), completely preventing nucleate bubble formation at the cavity niobium-helium interface. Boiling occurs exclusively at the free bath surface.

#### Thermomechanical Fountain Effect
Across porous plug sub-cooling barriers or capillary restrictors, temperature gradients generate a thermomechanical London fountain pressure:
$$\Delta P_f = \int_{T_1}^{T_2} \rho S(T) \, dT$$
For differential temperature excursions $\Delta T = 10\text{ mK}$ around $1.8\text{ K}$, the resulting fountain pressure $\Delta P_f \approx 2.2\text{ kPa}$ provides passive thermal siphon pumping across the superconducting cavity cooling jackets.

---

### 1.2 Sub-Atmospheric Pressure Regulation & 4-Stage Cold Centrifugal Compressor Cascade
To pump the saturated helium bath down to $16.38\text{ mbar}$, four stages of cryogenic centrifugal cold compressors are operated in series inside the cryo-plant vacuum vessel ($T_{in} \approx 4.0 - 15.0\text{ K}$).
1. **Cascade Compression Ratio**: The total pressure ratio $\Pi_{tot} = \frac{P_{out}}{P_{in}} = \frac{1300\text{ mbar}}{16.38\text{ mbar}} \approx 79.36$ is partitioned equally across the 4 stages:
   $$\pi_i = \sqrt[4]{\Pi_{tot}} \approx 2.985 \quad (i = 1, 2, 3, 4)$$
2. **Surge & Stall Prevention**: Each compressor stage operates with active variable speed modulation ($200 - 800\text{ Hz}$, active magnetic bearings) and a dedicated high-speed anti-surge bypass control valve ($CV_{surge, i}$). The surge proximity parameter is calculated in real time:
   $$SS_i = \frac{\dot{m}_i - \dot{m}_{surge, i}(N_i, \pi_i)}{\dot{m}_{surge, i}(N_i, \pi_i)}$$
   When $SS_i < 0.15$ ($15\%$ surge margin), the anti-surge bypass valve modulates open via feed-forward gain override to guarantee compressor aerodynamic stability.

---

## 2. Superconducting RF Cavity Dynamics & Vector Control

### 2.1 Lorentz Force Detuning & Microphonics Compensation
The 400.000 MHz Superconducting RF (SRF) bulk niobium cavity exhibits a loaded quality factor $Q_L \approx 1.5 \times 10^6$, giving a cavity half-bandwidth:
$$\Delta f_{BW} = \frac{f_0}{2 Q_L} = \frac{400 \times 10^6}{3.0 \times 10^6} \approx 133.3\text{ Hz}$$

Radiation pressure on the cavity inner walls induces mechanical deformation, resulting in Lorentz force detuning:
$$\Delta f_L = -K_L \cdot E_{acc}^2$$
where $K_L \approx 1.8\text{ Hz/(MV/m)}^2$. At nominal operating gradient $E_{acc} = 20.0\text{ MV/m}$, $\Delta f_L = -720\text{ Hz}$, which is more than $5\times$ the cavity operational bandwidth.

Additionally, external cryogenic pressure fluctuations and ground vibrations induce acoustic microphonics (mechanical eigenmodes between $10\text{ Hz}$ and $500\text{ Hz}$) causing stochastic detuning $\Delta f_\mu \approx \pm 40\text{ Hz}$.

### 2.2 Dual-Actuator Hybrid Tuning Scheme
- **Coarse Mechanical Stepper Motor**: Range $\pm 500\text{ kHz}$, step resolution $0.5\text{ Hz/step}$. Operates in a slow control loop ($100\text{ ms}$ update rate) with a deadband window to absorb slow thermal drift and minimize mechanical screw backlash wear.
- **Piezoelectric Stack Fast Actuator**: Range $\pm 2.5\text{ kHz}$, sub-millisecond response, drive voltage $0 - 150\text{ V}$. Drives an inverse hysteresis compensation algorithm combining dynamic feed-forward compensation based on accelerating gradient $E_{acc}(t)$ and real-time feedback on the phase detuning angle:
  $$\tan \psi = -2 Q_L \frac{\Delta f}{f_0} = \frac{\text{Im}(V_c \cdot V_{fwd}^*)}{\text{Re}(V_c \cdot V_{fwd}^*)}$$

### 2.3 Low-Level RF (LLRF) Cartesian I/Q Demodulation & Control
The cavity electric field is decomposed into In-Phase ($I$) and Quadrature ($Q$) orthogonal components:
$$V_c(t) = I(t) \cos(\omega_{RF} t) - Q(t) \sin(\omega_{RF} t)$$
Amplitude and Phase are derived:
$$A(t) = \sqrt{I(t)^2 + Q(t)^2}, \quad \phi(t) = \text{atan2}(Q(t), I(t))$$
Dual decoupled PI controllers with cross-polar rotation matrices regulate $I$ and $Q$ to drive phase error below $0.05^\circ$ and amplitude jitter below $0.01\%$.

---

## 3. SIL-3 Quench Detection & Fast Extraction Interlocks

### 3.1 Inductive Voltage Rejection & Resistive Zone Emergence
During cavity beam loading or superconducting magnet ramping, large $dI/dt$ induces substantial inductive voltages ($V_{ind} = L \frac{dI}{dt}$) that mask small resistive quench signals. 

A high-precision differential bridge tap circuit measures voltages $V_1(t)$ and $V_2(t)$ across symmetrical halves of the superconducting structure:
$$V_{diff}(t) = \left| V_1(t) - V_2(t) - M_{comp} \frac{dI}{dt} \right|$$
where $M_{comp}$ is the inductive compensation coefficient. 

### 3.2 Dual-Threshold Quench Validation & Fast Extraction Commutation
1. **Validation Integral**: If $V_{diff}(t) > V_{threshold}$ ($100\text{ mV}$), an accumulator calculates the quench energy action integral:
   $$\Psi_{quench} = \int_{t_0}^{t} \left( V_{diff}(\tau) - V_{threshold} \right) d\tau$$
   If $\Psi_{quench} > \Psi_{critical}$ ($1.0\text{ mV}\cdot\text{s}$) or if $V_{diff}(t) > V_{critical}$ ($500\text{ mV}$), a Quench Trip is initiated within $< 10\,\mu\text{s}$.
2. **Sub-Millisecond Energy Extraction Sequencing**:
   - Redundant optical trigger pulses ignite the dual-channel SCR Thyristor Crowbar ($bSCR\_Fire\_ChA$, $bSCR\_Fire\_ChB$).
   - The primary DC Superconducting Extraction Circuit Breakers are opened, commutating stored magnetic energy into external water-cooled dump resistors ($R_{dump} = 0.5\,\Omega$).
   - RF power amplifiers are hardware-inhibited within $< 2\,\mu\text{s}$.
   - The Cryogenic Superfluid Boil-Off Emergency Fast Relief Valve (`HV_Quench_Relief_FastOpen`) is energized to prevent cryostat vessel overpressurization beyond $2.0\text{ bar}$.

