FUNCTION_BLOCK FB_CERN_SRF_CryoController
VAR_INPUT
    bEnableSystem               : BOOL;   // Master enable
    bResetFaults                : BOOL;   // Fault clear command

    // Cryogenics Process Measurements
    fBathTemp_Raw_K             : LREAL;  // PT1000/Cernox sensor input (K)
    fBathPressure_Raw_mbar      : LREAL;  // Sub-atmospheric capacitive gauge (mbar)
    fLiquidLevel_Raw_Pct        : LREAL;  // Superconducting level probe (%)
    fSupplyPressure_4K_bar      : LREAL;  // Pre-cooling He-I supply (bar)

    // RF In-phase / Quadrature & Cavity Telemetry
    stProbeField_IQ             : T_LLRF_Vector; // Cavity pickup antenna
    stForwardPower_IQ           : T_LLRF_Vector; // Forward wave directional coupler
    stReflectedPower_IQ         : T_LLRF_Vector; // Reflected wave directional coupler
    fCavityTarget_Eacc_MV_m     : LREAL; // Setpoint gradient (e.g. 20.0 MV/m)
    fCavityTarget_Phase_Deg     : LREAL; // Setpoint phase (deg)

    // Quench Sensor Hardware Channels (10-microsecond FPGA oversampled)
    fBridgeTap1_Raw_V           : LREAL; // Fast tap 1 voltage
    fBridgeTap2_Raw_V           : LREAL; // Fast tap 2 voltage
    fCurrentRampRate_A_s        : LREAL; // dI/dt from Rogowski coil

    // Task Cycle Time
    fCycleTime_s                : LREAL := 0.0005; // 500 microseconds cycle time
END_VAR

VAR_OUTPUT
    eCryoState                  : E_CryoState := CRYO_OFF_WARM;
    eRFState                    : E_RFState := RF_STANDBY;
    eQuenchStatus               : E_QuenchSeverity := QUENCH_NONE;

    stHeII_State                : T_HeII_ThermodynamicState;
    stCompressors               : T_ColdCompressorTrain;
    stPiezo                     : T_PiezoActuator;
    stStepper                   : T_StepperActuator;
    stLLRF_Drive_IQ             : T_LLRF_Vector;
    stQuenchBridge              : T_QuenchBridge;
    stFastDump                  : T_FastDumpCircuit;
    stDiag                      : T_SRF_Diagnostics;

    fPhaseError_Deg             : LREAL;
    fAmplitudeError_Pct         : LREAL;
    fCavityDetuning_Hz          : LREAL;
END_VAR

VAR
    // Constants
    CONST_T_LAMBDA              : LREAL := 2.1768;   // Lambda point temperature (K)
    CONST_P_SAT_1_8K_MBAR       : LREAL := 16.380;   // Saturated vapor pressure at 1.800K
    CONST_RF_F0_HZ              : LREAL := 400.0E6;  // 400.000 MHz carrier
    CONST_CAVITY_QL             : LREAL := 1.5E6;    // Loaded Quality Factor
    CONST_LORENTZ_KL            : LREAL := 1.80;     // Lorentz detuning coefficient Hz/(MV/m)^2
    CONST_PI                    : LREAL := 3.14159265358979323846;
    CONST_QUENCH_V_TH_VOLTS     : LREAL := 0.100;    // 100 mV threshold
    CONST_QUENCH_V_CRIT_VOLTS   : LREAL := 0.500;    // 500 mV critical fast trip
    CONST_QUENCH_ACTION_CRIT    : LREAL := 0.0010;   // 1.0 mV*s action integral threshold
    CONST_M_INDUCTIVE_COMP_H    : LREAL := 0.000045; // 45 uH compensation factor

    // Cryogenic Control PI Regulators
    fJT_PI_Integral             : LREAL := 0.0;
    fJT_Kp                      : LREAL := 12.5;
    fJT_Ki                      : LREAL := 1.8;
    fJT_Out_Max                 : LREAL := 100.0;
    fJT_Out_Min                 : LREAL := 0.0;

    fPress_PI_Integral          : LREAL := 0.0;
    fPress_Kp                   : LREAL := 45.0;
    fPress_Ki                   : LREAL := 8.5;

    // LLRF Dual-Channel Cartesian PI Regulators
    fLLRF_I_Integral            : LREAL := 0.0;
    fLLRF_Q_Integral            : LREAL := 0.0;
    fLLRF_Kp                    : LREAL := 0.85;
    fLLRF_Ki                    : LREAL := 120.0;

    // Piezoelectric Anti-Hysteresis & Tracking Filter
    fPiezo_FilteredDetune_Hz    : LREAL := 0.0;
    fPiezo_FilterAlpha          : LREAL := 0.25;

    // Interlock Timers
    tQuenchPersistTimer_s       : LREAL := 0.0;
    tCompressorSurgeDelay_s     : LREAL := 0.0;

    // Internal Flags
    bQuenchLatched              : BOOL := FALSE;
    bSurgeInterlockTripped      : BOOL := FALSE;
END_VAR

VAR_TEMP
    fTempRatio                  : LREAL;
    fBathPressError             : LREAL;
    fCompressorSpeedRef_RPM     : LREAL;
    fI_Set                      : LREAL;
    fQ_Set                      : LREAL;
    fI_Meas                     : LREAL;
    fQ_Meas                     : LREAL;
    fI_Err                      : LREAL;
    fQ_Err                      : LREAL;
    fI_Drive                    : LREAL;
    fQ_Drive                    : LREAL;
    fPhaseRadSet                : LREAL;
    fPhaseRadMeas               : LREAL;
    fCavityTanPsi               : LREAL;
    fDotProduct                 : LREAL;
    fCrossProduct               : LREAL;
    fDetuningAngleRad           : LREAL;
    fTargetPiezoVoltage         : LREAL;
    fDetuneHzCorrection         : LREAL;
    i                           : INT;
END_VAR

// =============================================================================
// MAIN LOGIC EXECUTION
// =============================================================================

// 0. SYSTEM INITIALIZATION & FAULT RESET LOGIC
IF NOT bEnableSystem THEN
    eCryoState := CRYO_OFF_WARM;
    eRFState := RF_STANDBY;
    eQuenchStatus := QUENCH_NONE;

    // Safely zero control actuators
    stHeII_State.JT_ValvePosition := 0.0;
    stPiezo.Voltage_V := 0.0;
    stLLRF_Drive_IQ.I_Component := 0.0;
    stLLRF_Drive_IQ.Q_Component := 0.0;
    stFastDump.SCR_Trigger_ChA := FALSE;
    stFastDump.SCR_Trigger_ChB := FALSE;
    stFastDump.DC_Breaker_Trip_Cmd := FALSE;
    stFastDump.RF_Power_Inhibit_Cmd := TRUE;
    stFastDump.He_QuenchRelief_FastOpen := FALSE;

    stDiag.StatusWord := 16#00000000;
    stDiag.SIL3_SafetyIntegrityOK := TRUE;
    RETURN;
END_IF;

IF bResetFaults THEN
    bQuenchLatched := FALSE;
    bSurgeInterlockTripped := FALSE;
    stFastDump.SCR_Trigger_ChA := FALSE;
    stFastDump.SCR_Trigger_ChB := FALSE;
    stFastDump.DC_Breaker_Trip_Cmd := FALSE;
    stFastDump.RF_Power_Inhibit_Cmd := FALSE;
    stFastDump.He_QuenchRelief_FastOpen := FALSE;
    stQuenchBridge.ActionIntegral_mV_s := 0.0;
    stDiag.FaultWord := 16#00000000;
    IF eCryoState = CRYO_QUENCH_EMERGENCY THEN
        eCryoState := CRYO_PUMP_DOWN_LAMBDA;
    END_IF;
    IF eRFState = RF_QUENCH_LATCHED OR eRFState = RF_FAULT_INTERLOCK THEN
        eRFState := RF_STANDBY;
    END_IF;
END_IF;

// -----------------------------------------------------------------------------
// 1. SIL-3 DIFFERENTIAL BRIDGE QUENCH DETECTION & ULTRA-FAST EXTRACTION
// -----------------------------------------------------------------------------
// Symmetrical half-coil bridge acquisition: V_diff = |V1 - V2 - M * (dI/dt)|
stQuenchBridge.Voltage_Tap1_V := fBridgeTap1_Raw_V;
stQuenchBridge.Voltage_Tap2_V := fBridgeTap2_Raw_V;
stQuenchBridge.dI_dt_A_s := fCurrentRampRate_A_s;
stQuenchBridge.InductiveComp_M := CONST_M_INDUCTIVE_COMP_H;

stQuenchBridge.V_Diff_Uncompensated := stQuenchBridge.Voltage_Tap1_V - stQuenchBridge.Voltage_Tap2_V;
stQuenchBridge.V_Resistive_Emergent := ABS(stQuenchBridge.V_Diff_Uncompensated - (stQuenchBridge.InductiveComp_M * stQuenchBridge.dI_dt_A_s));

// Quench evaluation logic
IF stQuenchBridge.V_Resistive_Emergent > CONST_QUENCH_V_TH_VOLTS THEN
    // Accumulate action integral: integral( (V_res - V_th) * dt ) in V*s
    stQuenchBridge.ActionIntegral_mV_s := stQuenchBridge.ActionIntegral_mV_s + 
        ((stQuenchBridge.V_Resistive_Emergent - CONST_QUENCH_V_TH_VOLTS) * fCycleTime_s);
    eQuenchStatus := QUENCH_SUSPECTED;
ELSE
    // Exponential leak-off for transient noise recovery
    stQuenchBridge.ActionIntegral_mV_s := stQuenchBridge.ActionIntegral_mV_s * 0.995;
    IF NOT bQuenchLatched THEN
        eQuenchStatus := QUENCH_NONE;
    END_IF;
END_IF;

// Trigger FAST DUMP if critical voltage is exceeded OR action integral exceeds limit
IF (stQuenchBridge.V_Resistive_Emergent >= CONST_QUENCH_V_CRIT_VOLTS) OR 
   (stQuenchBridge.ActionIntegral_mV_s >= CONST_QUENCH_ACTION_CRIT) THEN

    bQuenchLatched := TRUE;
    eQuenchStatus := QUENCH_CRITICAL_FAST_DUMP;
    eCryoState := CRYO_QUENCH_EMERGENCY;
    eRFState := RF_QUENCH_LATCHED;

    // HARDWARE FAST COMMUTATION SEQUENCE (<10 microseconds response)
    stFastDump.SCR_Trigger_ChA := TRUE;           // Fire primary crowbar thyristor
    stFastDump.SCR_Trigger_ChB := TRUE;           // Fire redundant crowbar thyristor
    stFastDump.DC_Breaker_Trip_Cmd := TRUE;       // Commutate to external energy dump resistor
    stFastDump.RF_Power_Inhibit_Cmd := TRUE;      // Inhibit RF klystron/solid-state drive
    stFastDump.He_QuenchRelief_FastOpen := TRUE;  // Open cryostat overpressure burst relief

    stDiag.FaultWord := stDiag.FaultWord OR 16#00000001; // Quench Interlock Active
    stDiag.SIL3_SafetyIntegrityOK := FALSE;
END_IF;

// If quench is latched, bypass normal RF and cryo pump-down loops
IF bQuenchLatched THEN
    stLLRF_Drive_IQ.I_Component := 0.0;
    stLLRF_Drive_IQ.Q_Component := 0.0;
    stPiezo.Voltage_V := 0.0;
    stHeII_State.JT_ValvePosition := 0.0;
    RETURN;
END_IF;

// -----------------------------------------------------------------------------
// 2. 1.8K SUPERFLUID HELIUM-II THERMODYNAMICS & LONDON TWO-FLUID MODEL
// -----------------------------------------------------------------------------
stHeII_State.Temperature_Bath := fBathTemp_Raw_K;
stHeII_State.Pressure_Bath := fBathPressure_Raw_mbar;
stHeII_State.LiquidHeliumLevel := fLiquidLevel_Raw_Pct;

IF stHeII_State.Temperature_Bath < CONST_T_LAMBDA AND stHeII_State.Temperature_Bath > 0.5 THEN
    // London two-fluid model calculation: rho_s / rho = 1.0 - (T / T_lambda)^5.6
    fTempRatio := stHeII_State.Temperature_Bath / CONST_T_LAMBDA;
    stHeII_State.SuperfluidFraction := 1.0 - EXPT(fTempRatio, 5.6);
    IF stHeII_State.SuperfluidFraction < 0.0 THEN
        stHeII_State.SuperfluidFraction := 0.0;
    ELSIF stHeII_State.SuperfluidFraction > 1.0 THEN
        stHeII_State.SuperfluidFraction := 1.0;
    END_IF;
    stHeII_State.NormalFluidFraction := 1.0 - stHeII_State.SuperfluidFraction;

    // Gorter-Mellink non-linear mutual friction peak heat flux estimation (W/cm^2)
    // q_max approx 1.2 * (T)^2 * (1 - (T/T_lambda)^5.6)^(1/3)
    stHeII_State.GorterMellinkHeatFlux := 1.2 * EXPT(stHeII_State.Temperature_Bath, 2.0) * 
                                          EXPT(stHeII_State.SuperfluidFraction, 0.333333);

    // London thermomechanical fountain pressure: Delta_P = rho * S * Delta_T (Pa)
    // S_HeII approx 1.55 J/(g*K) at 1.8K, rho approx 145 kg/m^3
    stHeII_State.FountainPressureDelta := 145.0 * 1550.0 * ABS(CONST_T_LAMBDA - stHeII_State.Temperature_Bath) * 0.01;
ELSE
    // Normal Helium-I state above lambda point
    stHeII_State.SuperfluidFraction := 0.0;
    stHeII_State.NormalFluidFraction := 1.0;
    stHeII_State.GorterMellinkHeatFlux := 0.0;
    stHeII_State.FountainPressureDelta := 0.0;
END_IF;

// Cryogenic Bath Level & Joule-Thomson (JT) Expansion Valve Loop
// Regulation of liquid level at 90.0% setpoint using anti-windup PI controller
fBathPressError := 90.0 - stHeII_State.LiquidHeliumLevel;
fJT_PI_Integral := fJT_PI_Integral + (fBathPressError * fJT_Ki * fCycleTime_s);

// Clamping integral anti-windup
IF fJT_PI_Integral > fJT_Out_Max THEN
    fJT_PI_Integral := fJT_Out_Max;
ELSIF fJT_PI_Integral < fJT_Out_Min THEN
    fJT_PI_Integral := fJT_Out_Min;
END_IF;

stHeII_State.JT_ValvePosition := (fBathPressError * fJT_Kp) + fJT_PI_Integral;
IF stHeII_State.JT_ValvePosition > 100.0 THEN
    stHeII_State.JT_ValvePosition := 100.0;
ELSIF stHeII_State.JT_ValvePosition < 0.0 THEN
    stHeII_State.JT_ValvePosition := 0.0;
END_IF;

// -----------------------------------------------------------------------------
// 3. 4-STAGE COLD CENTRIFUGAL COMPRESSOR CASCADE & ANTI-SURGE SYSTEM
// -----------------------------------------------------------------------------
// Sub-atmospheric pressure modulation targeting 16.38 mbar (+/- 0.05 mbar)
fBathPressError := stHeII_State.Pressure_Bath - CONST_P_SAT_1_8K_MBAR;
fPress_PI_Integral := fPress_PI_Integral + (fBathPressError * fPress_Ki * fCycleTime_s);

IF fPress_PI_Integral > 48000.0 THEN
    fPress_PI_Integral := 48000.0;
ELSIF fPress_PI_Integral < 12000.0 THEN
    fPress_PI_Integral := 12000.0;
END_IF;

fCompressorSpeedRef_RPM := (fBathPressError * fPress_Kp) + fPress_PI_Integral;
IF fCompressorSpeedRef_RPM > 48000.0 THEN
    fCompressorSpeedRef_RPM := 48000.0;
ELSIF fCompressorSpeedRef_RPM < 12000.0 THEN
    fCompressorSpeedRef_RPM := 12000.0;
END_IF;

// Configure and balance 4-stage cascade compression distribution
stCompressors.OverallPressureRatio := 1300.0 / MAX(stHeII_State.Pressure_Bath, 1.0);
stCompressors.SurgeWarningActive := FALSE;

FOR i := 1 TO 4 DO
    stCompressors.Stages[i].StageID := i;
    stCompressors.Stages[i].RotationalSpeed_RPM := fCompressorSpeedRef_RPM * (1.0 + (DINT_TO_LREAL(i - 1) * 0.04));

    // Cascaded stage pressure estimate
    IF i = 1 THEN
        stCompressors.Stages[i].InletPressure_mbar := stHeII_State.Pressure_Bath;
    ELSE
        stCompressors.Stages[i].InletPressure_mbar := stCompressors.Stages[i - 1].OutletPressure_mbar;
    END_IF;

    stCompressors.Stages[i].CompressionRatio := EXPT(stCompressors.OverallPressureRatio, 0.25);
    stCompressors.Stages[i].OutletPressure_mbar := stCompressors.Stages[i].InletPressure_mbar * stCompressors.Stages[i].CompressionRatio;

    // Dynamic surge margin calculation: SM% = (Flow - Flow_surge) / Flow_surge * 100
    // Simplified aerodynamic surge boundary: Flow_surge = K * RPM / 1000
    stCompressors.Stages[i].MassFlow_g_s := 18.5 - (DINT_TO_LREAL(i) * 0.8);
    stCompressors.Stages[i].SurgeMarginPercent := ((stCompressors.Stages[i].MassFlow_g_s - (0.00032 * stCompressors.Stages[i].RotationalSpeed_RPM)) / 
                                                  MAX(stCompressors.Stages[i].MassFlow_g_s, 0.1)) * 100.0;

    // Anti-surge fast bypass valve modulation
    IF stCompressors.Stages[i].SurgeMarginPercent < 15.0 THEN
        stCompressors.Stages[i].AntiSurgeBypass_Pos := (15.0 - stCompressors.Stages[i].SurgeMarginPercent) * 6.666;
        stCompressors.SurgeWarningActive := TRUE;
    ELSE
        stCompressors.Stages[i].AntiSurgeBypass_Pos := 0.0;
    END_IF;

    IF stCompressors.Stages[i].SurgeMarginPercent < 5.0 THEN
        bSurgeInterlockTripped := TRUE;
    END_IF;
END_FOR;

IF bSurgeInterlockTripped THEN
    eCryoState := CRYO_SURGE_RECOVERY;
    stDiag.FaultWord := stDiag.FaultWord OR 16#00000002; // Compressor Surge Trip
END_IF;

// -----------------------------------------------------------------------------
// 4. CRYO STATE MACHINE EVALUATION
// -----------------------------------------------------------------------------
CASE eCryoState OF
    CRYO_OFF_WARM:
        IF bEnableSystem THEN
            eCryoState := CRYO_PRECOOL_4K;
        END_IF;

    CRYO_PRECOOL_4K:
        IF stHeII_State.Temperature_Bath <= 4.5 AND stHeII_State.LiquidHeliumLevel >= 80.0 THEN
            eCryoState := CRYO_PUMP_DOWN_LAMBDA;
        END_IF;

    CRYO_PUMP_DOWN_LAMBDA:
        IF stHeII_State.Temperature_Bath <= 1.820 AND ABS(stHeII_State.Pressure_Bath - CONST_P_SAT_1_8K_MBAR) <= 0.2 THEN
            eCryoState := CRYO_SUPERFLUID_1_8K_STEADY;
        END_IF;

    CRYO_SUPERFLUID_1_8K_STEADY:
        IF ABS(stHeII_State.Pressure_Bath - CONST_P_SAT_1_8K_MBAR) > 2.5 THEN
            eCryoState := CRYO_PUMP_DOWN_LAMBDA;
        END_IF;

    CRYO_SURGE_RECOVERY:
        IF NOT stCompressors.SurgeWarningActive AND NOT bSurgeInterlockTripped THEN
            eCryoState := CRYO_SUPERFLUID_1_8K_STEADY;
        END_IF;

    CRYO_QUENCH_EMERGENCY:
        // Maintained until bResetFaults
        ;
END_CASE;

// -----------------------------------------------------------------------------
// 5. SUPERCONDUCTING RF CAVITY DETUNING & DUAL-ACTUATOR TUNING LOOP
// -----------------------------------------------------------------------------
// Measure Cavity Detuning Angle: tan(psi) = Im(Vc * Vfwd*) / Re(Vc * Vfwd*)
fDotProduct := (stProbeField_IQ.I_Component * stForwardPower_IQ.I_Component) + 
               (stProbeField_IQ.Q_Component * stForwardPower_IQ.Q_Component);

fCrossProduct := (stProbeField_IQ.Q_Component * stForwardPower_IQ.I_Component) - 
                (stProbeField_IQ.I_Component * stForwardPower_IQ.Q_Component);

IF ABS(fDotProduct) > 1.0E-6 THEN
    fDetuningAngleRad := ATAN(fCrossProduct / fDotProduct);
ELSE
    fDetuningAngleRad := 0.0;
END_IF;

// Calculate frequency detuning: delta_f = - (f0 / (2 * QL)) * tan(psi)
fCavityDetuning_Hz := - (CONST_RF_F0_HZ / (2.0 * CONST_CAVITY_QL)) * TAN(fDetuningAngleRad);

// Low-pass filter for microphonics extraction
fPiezo_FilteredDetune_Hz := (fPiezo_FilterAlpha * fCavityDetuning_Hz) + 
                            ((1.0 - fPiezo_FilterAlpha) * fPiezo_FilteredDetune_Hz);

// Dynamic Lorentz Force Detuning Feed-Forward: delta_f_L = -K_L * E_acc^2
stPiezo.FeedForwardGain_KL := CONST_LORENTZ_KL;
stPiezo.DetuningOffset_Hz := - (stPiezo.FeedForwardGain_KL * EXPT(stProbeField_IQ.Amplitude_MV_m, 2.0));

// Fast Piezo Stack Voltage Synthesis (0 to 150V range, piezo sensitivity = 25 Hz/V)
// V_target = V_bias + FeedForward(Lorentz) + Feedback(Microphonics) + HysteresisCorrection
fDetuneHzCorrection := - (stPiezo.DetuningOffset_Hz + fPiezo_FilteredDetune_Hz);
fTargetPiezoVoltage := 75.0 + (fDetuneHzCorrection / 25.0) + stPiezo.HysteresisCorrection_V;

// Inverse Preisach/Hysteresis simple polynomial correction
stPiezo.HysteresisCorrection_V := 0.015 * (fTargetPiezoVoltage - 75.0);

IF fTargetPiezoVoltage > 150.0 THEN
    stPiezo.Voltage_V := 150.0;
ELSIF fTargetPiezoVoltage < 0.0 THEN
    stPiezo.Voltage_V := 0.0;
ELSE
    stPiezo.Voltage_V := fTargetPiezoVoltage;
END_IF;
stPiezo.Position_um := stPiezo.Voltage_V * 0.266; // 40 um full stroke at 150V

// Coarse Stepper Motor Management (Deadband offloading)
// If Piezo voltage drifts outside [40V, 110V], step motor to recenter piezo
IF stPiezo.Voltage_V > 110.0 THEN
    stStepper.InDeadband := FALSE;
    stStepper.TargetStepPosition := stStepper.CurrentStepPosition + 15;
    stStepper.IsMoving := TRUE;
ELSIF stPiezo.Voltage_V < 40.0 THEN
    stStepper.InDeadband := FALSE;
    stStepper.TargetStepPosition := stStepper.CurrentStepPosition - 15;
    stStepper.IsMoving := TRUE;
ELSE
    stStepper.InDeadband := TRUE;
    stStepper.IsMoving := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// 6. LLRF IN-PHASE / QUADRATURE (I/Q) CLOSED-LOOP VECTOR MODULATION
// -----------------------------------------------------------------------------
IF eCryoState = CRYO_SUPERFLUID_1_8K_STEADY AND NOT bQuenchLatched THEN
    eRFState := RF_CW_LOCKED_1_8K;
    stFastDump.RF_Power_Inhibit_Cmd := FALSE;

    // Compute Target I and Q from Amplitude & Phase setpoints
    fPhaseRadSet := fCavityTarget_Phase_Deg * (CONST_PI / 180.0);
    fI_Set := fCavityTarget_Eacc_MV_m * COS(fPhaseRadSet);
    fQ_Set := fCavityTarget_Eacc_MV_m * SIN(fPhaseRadSet);

    // Probe Measured I and Q
    fI_Meas := stProbeField_IQ.I_Component;
    fQ_Meas := stProbeField_IQ.Q_Component;

    // Cartesian Error Components
    fI_Err := fI_Set - fI_Meas;
    fQ_Err := fQ_Set - fQ_Meas;

    // Dual PI Regulators with Anti-Windup
    fLLRF_I_Integral := fLLRF_I_Integral + (fI_Err * fLLRF_Ki * fCycleTime_s);
    fLLRF_Q_Integral := fLLRF_Q_Integral + (fQ_Err * fLLRF_Ki * fCycleTime_s);

    IF fLLRF_I_Integral > 1.2 THEN fLLRF_I_Integral := 1.2; ELSIF fLLRF_I_Integral < -1.2 THEN fLLRF_I_Integral := -1.2; END_IF;
    IF fLLRF_Q_Integral > 1.2 THEN fLLRF_Q_Integral := 1.2; ELSIF fLLRF_Q_Integral < -1.2 THEN fLLRF_Q_Integral := -1.2; END_IF;

    fI_Drive := (fI_Err * fLLRF_Kp) + fLLRF_I_Integral;
    fQ_Drive := (fQ_Err * fLLRF_Kp) + fLLRF_Q_Integral;

    stLLRF_Drive_IQ.I_Component := fI_Drive;
    stLLRF_Drive_IQ.Q_Component := fQ_Drive;
    stLLRF_Drive_IQ.Amplitude_MV_m := SQRT(EXPT(fI_Drive, 2.0) + EXPT(fQ_Drive, 2.0));
    stLLRF_Drive_IQ.Phase_Deg := ATAN2(fQ_Drive, fI_Drive) * (180.0 / CONST_PI);

    // Error Metrics & Quality Assertions (<0.05 deg Phase, <0.01% Amplitude)
    fPhaseRadMeas := ATAN2(fQ_Meas, fI_Meas);
    fPhaseError_Deg := ABS((fPhaseRadMeas * 180.0 / CONST_PI) - fCavityTarget_Phase_Deg);
    IF fCavityTarget_Eacc_MV_m > 0.1 THEN
        fAmplitudeError_Pct := (ABS(stProbeField_IQ.Amplitude_MV_m - fCavityTarget_Eacc_MV_m) / fCavityTarget_Eacc_MV_m) * 100.0;
    ELSE
        fAmplitudeError_Pct := 0.0;
    END_IF;
ELSE
    stLLRF_Drive_IQ.I_Component := 0.0;
    stLLRF_Drive_IQ.Q_Component := 0.0;
    stLLRF_Drive_IQ.Amplitude_MV_m := 0.0;
    stLLRF_Drive_IQ.Phase_Deg := 0.0;
    fPhaseError_Deg := 0.0;
    fAmplitudeError_Pct := 0.0;
END_IF;

// -----------------------------------------------------------------------------
// 7. SYSTEM DIAGNOSTICS & TELEMETRY PACKAGING
// -----------------------------------------------------------------------------
stDiag.StatusWord := 16#00000000;
IF stHeII_State.SuperfluidFraction > 0.5 THEN
    stDiag.StatusWord := stDiag.StatusWord OR 16#00000001; // Superfluid State OK
END_IF;
IF eRFState = RF_CW_LOCKED_1_8K THEN
    stDiag.StatusWord := stDiag.StatusWord OR 16#00000002; // RF Vector Locked
END_IF;
IF fPhaseError_Deg < 0.05 AND fAmplitudeError_Pct < 0.01 THEN
    stDiag.StatusWord := stDiag.StatusWord OR 16#00000004; // Precision Bounds Met
END_IF;
IF stStepper.InDeadband THEN
    stDiag.StatusWord := stDiag.StatusWord OR 16#00000008; // Stepper in Deadband
END_IF;

stDiag.SIL3_SafetyIntegrityOK := NOT bQuenchLatched AND NOT bSurgeInterlockTripped;
stDiag.LoopExecutionTime_us := fCycleTime_s * 1.0E6;

END_FUNCTION_BLOCK
```

# Staged Combustion LCH4/LOX Turbopump & TVC Gimbal Controller
## Principal Aerospace Propulsion Automation & Control Architecture

### 1. Control Systems & Thermodynamics Architecture Overview

In a staged-combustion (fuel-rich preburner) rocket engine cycle operating with sub-cooled Liquid Methane (LCH4) and Liquid Oxygen (LOX), thermodynamic coupling between the preburner power balance, dual turbopump spools, regenerative cooling jacket, and main combustion chamber ($P_c = 250\text{ bar}$, $MR = 3.6$) requires tight, deterministic, microsecond-grade digital control.

