    // Compressor Aerodynamics
    rInlet_Air_Temp_C       : REAL;  // [°C] Ambient/Inlet plenum temperature
    rInlet_Air_Press_bar    : REAL;  // [bar] Ambient/Inlet plenum pressure
    rComp_Disch_Press_bar   : REAL;  // [bar] Compressor discharge pressure (PCD)
    rComp_Disch_Temp_C      : REAL;  // [°C] Compressor discharge temperature (TCD)

    // Combustor Shell & Exhaust
    rComb_Shell_Temp_C      : REAL;  // [°C] Combustor wrapper / shell temperature
    rExhaust_Temp_Avg_C     : REAL;  // [°C] Turbine exhaust gas average temperature
    rExhaust_Temp_Max_C     : REAL;  // [°C] Peak exhaust thermocouple temperature

    // Acoustic Combustion Dynamics (Piezoelectric dynamic pressure sensors)
    rAcoustic_Helmholtz_mbar: REAL;  // [mbar RMS] Intermediate frequency band (100-250 Hz)
    rAcoustic_Screech_mbar  : REAL;  // [mbar RMS] High frequency screech band (>400 Hz)

    // Rotor & Metal Temperatures
    rRotor_Surface_Temp_C   : REAL;  // [°C] Calculated rotor outer surface temperature
    rHRSG_HP_Drum_Press_bar : REAL;  // [bar] HRSG High Pressure steam drum pressure
END_STRUCT;
END_TYPE

TYPE ST_Fuel_Split_Demands :
STRUCT
    rFSR_Total_Pct          : REAL;  // [%] Fuel Stroke Reference (0-100% total fuel)
    rSplit_PM1_Primary_Pct  : REAL;  // [%] Primary manifold split
    rSplit_PM2_Secondary_Pct: REAL;  // [%] Secondary manifold split
    rSplit_TFR_Transfer_Pct : REAL;  // [%] Transfer / center nozzle split
    rSplit_Q4_Quaternary_Pct: REAL;  // [%] Quaternary manifold split
END_STRUCT;
END_TYPE

TYPE ST_Compressor_Actuation :
STRUCT
    rVIGV_Angle_Deg         : REAL;  // [Degrees] Variable Inlet Guide Vane position (-15° to +38°)
    rBleed_Valve_Stg9_Pct   : REAL;  // [%] Stage 9 anti-surge bleed valve demand (0-100%)
    rBleed_Valve_Stg14_Pct  : REAL;  // [%] Stage 14 anti-surge bleed valve demand (0-100%)
END_STRUCT;
END_TYPE

TYPE ST_Rotor_Fatigue_Status :
STRUCT
    rBore_Temp_C            : REAL;  // [°C] Calculated inner bore temperature
    rMean_Temp_C            : REAL;  // [°C] Bulk mean rotor temperature
    rThermal_Stress_MPa     : REAL;  // [MPa] Radial/Tangential thermal stress
    rMechanical_Stress_MPa  : REAL;  // [MPa] Centrifugal stress at bore
    rVonMises_Stress_MPa    : REAL;  // [MPa] Equivalent combined Von Mises stress
    rCumulative_Damage_LCF  : REAL;  // [Dimensionless] Miner's sum fraction (0.0 to 1.0)
    rRemaining_Life_Hours   : REAL;  // [Hours] Projected remaining rotor operating hours
    bStress_Limit_Active    : BOOL;  // Rotor thermal stress governor hold active
END_STRUCT;
END_TYPE

TYPE ST_Synthetic_Inertia_Status :
STRUCT
    rFiltered_RoCoF_Hz_s    : REAL;  // [Hz/s] Filtered Rate of Change of Frequency
    rInertial_Power_MW      : REAL;  // [MW] Instantaneous synthetic inertia power demand
    rDroop_Power_MW         : REAL;  // [MW] Fast primary frequency droop demand
    rTotal_FFR_Power_MW     : REAL;  // [MW] Total fast frequency power demand
    bFast_Boost_Triggered   : BOOL;  // True when +10% 500ms fast ramp is firing
    rEnergy_Delivered_MJ    : REAL;  // [MJ] Fast frequency energy injected during event
END_STRUCT;
END_TYPE

TYPE ST_HRSG_Bypass_Command :
STRUCT
    rHP_Bypass_Valve_Pct    : REAL;  // [%] HRSG High Pressure steam bypass to cold reheat
    rIP_Bypass_Valve_Pct    : REAL;  // [%] HRSG Intermediate Pressure steam bypass to condenser
    rFuel_Prepos_Bias_Pct   : REAL;  // [%] Pre-positioning bias on fuel gas control valve
END_STRUCT;
END_TYPE

// =============================================================================
// SUB-FUNCTION BLOCK: FB_RoCoF_Synthetic_Inertia
// High-Order Low-Pass Filtered Frequency Derivative & Virtual Synchronous Inertia
// =============================================================================

FUNCTION_BLOCK FB_RoCoF_Synthetic_Inertia
VAR_INPUT
    rGrid_Freq              : REAL;   // [Hz] Actual grid frequency
    rNominal_Freq           : REAL;   // [Hz] Nominal frequency (50.0 / 60.0)
    rRated_Power_MW         : REAL;   // [MW] Plant rated power (500.0)
    rInertia_Constant_H     : REAL;   // [s] Virtual inertia constant (e.g. 4.5 s)
    rDroop_Percent          : REAL;   // [%] Droop regulation slope (e.g. 4.0%)
    rDeadband_Hz            : REAL;   // [Hz] Frequency deadband (e.g. 0.03 Hz)
    rCycle_Time_s           : REAL;   // [s] Task cycle time (0.010 s)
    bEnable_SI              : BOOL;   // Enable Synthetic Inertia
    bEnable_FFR_Boost       : BOOL;   // Enable +10% 500ms fast ramp boost
END_VAR
VAR_OUTPUT
    rRoCoF_Hz_s             : REAL;   // [Hz/s] Filtered df/dt
    rP_Inertia_MW           : REAL;   // [MW] Inertial response power demand
    rP_Droop_MW             : REAL;   // [MW] Primary droop power demand
    rP_Total_Fast_MW        : REAL;   // [MW] Total fast frequency demand
    bFast_Ramp_Active       : BOOL;   // Active fast pulse injection
    eGrid_State             : E_GRID_STATUS;
END_VAR
VAR
    // 2nd-Order Low-Pass Butterworth Filter States
    rFreq_Filt_z1           : REAL := 50.0;
    rFreq_Filt_z2           : REAL := 50.0;
    rFreq_Prev              : REAL := 50.0;

    // Fast Boost Pulse Management
    rBoost_Timer_s          : REAL := 0.0;
    rBoost_Magnitude_MW     : REAL := 0.0;

    // Filter coefficients for fc = 5 Hz at Ts = 0.01 s
    // b0=0.0181, b1=0.0362, b2=0.0181, a1=-1.5610, a2=0.6414
    r_b0                    : REAL := 0.0181;
    r_b1                    : REAL := 0.0362;
    r_b2                    : REAL := 0.0181;
    r_a1                    : REAL := -1.5610;
    r_a2                    : REAL := 0.6414;
    rFreq_Raw_z1            : REAL := 50.0;
    rFreq_Raw_z2            : REAL := 50.0;

    rDelta_Freq             : REAL;
    rFiltered_Freq          : REAL;
END_VAR

// 1. Second-Order Butterworth Low-Pass Filtering of Frequency
rFiltered_Freq := (r_b0 * rGrid_Freq) + (r_b1 * rFreq_Raw_z1) + (r_b2 * rFreq_Raw_z2) 
                  - (r_a1 * rFreq_Filt_z1) - (r_a2 * rFreq_Filt_z2);

rFreq_Raw_z2   := rFreq_Raw_z1;
rFreq_Raw_z1   := rGrid_Freq;
rFreq_Filt_z2  := rFreq_Filt_z1;
rFreq_Filt_z1  := rFiltered_Freq;

// 2. High-Precision Derivative Calculation (df/dt)
IF rCycle_Time_s > 0.0001 THEN
    rRoCoF_Hz_s := (rFiltered_Freq - rFreq_Prev) / rCycle_Time_s;
ELSE
    rRoCoF_Hz_s := 0.0;
END_IF;
rFreq_Prev := rFiltered_Freq;

// 3. Grid Status Classification
rDelta_Freq := rFiltered_Freq - rNominal_Freq;

IF rFiltered_Freq < (rNominal_Freq - 2.5) THEN
    eGrid_State := GRID_UNDERFREQUENCY_TRIP;
ELSIF rFiltered_Freq > (rNominal_Freq + 2.5) THEN
    eGrid_State := GRID_OVERFREQUENCY_TRIP;
ELSIF ABS(rRoCoF_Hz_s) >= 0.50 THEN
    eGrid_State := GRID_ROCOF_EVENT;
ELSIF ABS(rDelta_Freq) > rDeadband_Hz THEN
    eGrid_State := GRID_DEADBAND_EXCEEDED;
ELSE
    eGrid_State := GRID_NORMAL;
END_IF;

// 4. Virtual Synchronous Inertia Power (Swing Equation)
IF bEnable_SI AND (rNominal_Freq > 1.0) THEN
    // P_SI = -2 * H * (S_n / f_0) * (df/dt)
    rP_Inertia_MW := -2.0 * rInertia_Constant_H * (rRated_Power_MW / rNominal_Freq) * rRoCoF_Hz_s;
    // Bound synthetic inertia to +/- 15% rated power (+/- 75 MW)
    rP_Inertia_MW := LIMIT(-75.0, rP_Inertia_MW, 75.0);
ELSE
    rP_Inertia_MW := 0.0;
END_IF;

// 5. Primary Frequency Droop Power Response
IF ABS(rDelta_Freq) > rDeadband_Hz AND (rDroop_Percent > 0.1) THEN
    // P_droop = -(1 / (R/100)) * ((f - f0) / f0) * P_rated
    rP_Droop_MW := -(100.0 / rDroop_Percent) * (rDelta_Freq / rNominal_Freq) * rRated_Power_MW;
    // Limit continuous droop response to +15% / -30% of rated capacity
    rP_Droop_MW := LIMIT(-150.0, rP_Droop_MW, 75.0);
ELSE
    rP_Droop_MW := 0.0;
END_IF;

// 6. Fast Ramp Trigger (+10% rated power / 50 MW within 500 ms)
IF bEnable_FFR_Boost AND (eGrid_State = GRID_ROCOF_EVENT) AND (rRoCoF_Hz_s < -0.60) AND NOT bFast_Ramp_Active THEN
    bFast_Ramp_Active   := TRUE;
    rBoost_Timer_s      := 0.0;
    rBoost_Magnitude_MW := 50.0; // +10% of 500 MW
END_IF;

IF bFast_Ramp_Active THEN
    rBoost_Timer_s := rBoost_Timer_s + rCycle_Time_s;
    IF rBoost_Timer_s <= 0.50 THEN
        // Linear ramp up to full 50 MW boost in 100 ms, hold until 500 ms
        IF rBoost_Timer_s <= 0.10 THEN
            rBoost_Magnitude_MW := 50.0 * (rBoost_Timer_s / 0.10);
        ELSE
            rBoost_Magnitude_MW := 50.0;
        END_IF;
    ELSIF rBoost_Timer_s <= 2.0 THEN
        // Smoothly taper off boost over 1.5 seconds back to primary droop
        rBoost_Magnitude_MW := 50.0 * (1.0 - ((rBoost_Timer_s - 0.50) / 1.50));
    ELSE
        bFast_Ramp_Active   := FALSE;
        rBoost_Magnitude_MW := 0.0;
        rBoost_Timer_s      := 0.0;
    END_IF;
END_IF;

// Total Fast Frequency Response Demand
rP_Total_Fast_MW := rP_Inertia_MW + rP_Droop_MW + rBoost_Magnitude_MW;
rP_Total_Fast_MW := LIMIT(-150.0, rP_Total_Fast_MW, 100.0);

END_FUNCTION_BLOCK


// =============================================================================
// SUB-FUNCTION BLOCK: FB_Helmholtz_Phase_Compensator
// Combustion Acoustic Oscillation Suppression via Dynamic Phase Lead-Lag
// =============================================================================

FUNCTION_BLOCK FB_Helmholtz_Phase_Compensator
VAR_INPUT
    rAcoustic_Helmholtz_mbar: REAL;   // [mbar RMS] 100-250 Hz acoustic pressure amplitude
    rAcoustic_Screech_mbar  : REAL;   // [mbar RMS] >400 Hz screech acoustic amplitude
    rT_Shell_C              : REAL;   // [°C] Combustor wrapper shell temperature
    rCycle_Time_s           : REAL;   // [s] Cycle time (0.010 s)
    bEnable_Compensator     : BOOL;   // Enable phase compensation
END_VAR
VAR_OUTPUT
    rQuat_Bias_Trimming_Pct : REAL;   // [%] Dynamic bias added to Quaternary fuel split
    rCenter_Nozzle_Bias_Pct : REAL;   // [%] Dynamic bias added to Transfer/Center nozzle
    bAcoustic_High_Alarm    : BOOL;   // Acoustic pressure exceeds threshold (> 25 mbar)
    bCombustion_Trip_Req    : BOOL;   // Critical acoustic pressure trip (> 60 mbar)
END_VAR
VAR
    // Lead-Lag State Variables
    rLeadLag_State          : REAL := 0.0;
    rLead_Time_T1           : REAL := 0.012; // [s] Phase lead time constant
    rLag_Time_T2            : REAL := 0.003; // [s] Phase lag time constant
    rGain_Kp                : REAL := 0.085; // [% per mbar]
    rAcoustic_Filtered      : REAL := 0.0;
    rFilter_Alpha           : REAL := 0.15;
END_VAR

// 1. Acoustic Pressure Filtering & Threshold Supervision
rAcoustic_Filtered := (rFilter_Alpha * rAcoustic_Helmholtz_mbar) + ((1.0 - rFilter_Alpha) * rAcoustic_Filtered);

IF rAcoustic_Filtered >= 25.0 THEN
    bAcoustic_High_Alarm := TRUE;
ELSE
    bAcoustic_High_Alarm := FALSE;
END_IF;

IF (rAcoustic_Filtered >= 60.0) OR (rAcoustic_Screech_mbar >= 40.0) THEN
    bCombustion_Trip_Req := TRUE;
ELSE
    bCombustion_Trip_Req := FALSE;
END_IF;

// 2. Dynamic Phase Lead-Lag Compensation Calculation
// Transfer Function: G(s) = Kp * (1 + T1*s) / (1 + T2*s)
// Discrete Formulation via Tustin / Euler:
IF bEnable_Compensator AND (rLag_Time_T2 > 0.0001) THEN
    rLeadLag_State := rLeadLag_State + (rCycle_Time_s / rLag_Time_T2) * (rAcoustic_Filtered - rLeadLag_State);

    // Output calculation with lead ratio
    rQuat_Bias_Trimming_Pct := rGain_Kp * (rLeadLag_State + (rLead_Time_T1 / rLag_Time_T2) * (rAcoustic_Filtered - rLeadLag_State));

    // Thermal wrapper correction (hotter wrapper increases acoustic damping sensitivity)
    IF rT_Shell_C > 380.0 THEN
        rQuat_Bias_Trimming_Pct := rQuat_Bias_Trimming_Pct * (1.0 + ((rT_Shell_C - 380.0) / 200.0));
    END_IF;

    // Clamp dynamic trimming between 0.0% and +8.0%
    rQuat_Bias_Trimming_Pct := LIMIT(0.0, rQuat_Bias_Trimming_Pct, 8.0);

    // Trimming transfer center nozzle in opposite direction to shift flame anchor
    rCenter_Nozzle_Bias_Pct := -0.50 * rQuat_Bias_Trimming_Pct;
ELSE
    rQuat_Bias_Trimming_Pct := 0.0;
    rCenter_Nozzle_Bias_Pct := 0.0;
END_IF;

END_FUNCTION_BLOCK


// =============================================================================
// SUB-FUNCTION BLOCK: FB_DLN26_Split_Scheduler
// Multi-Nozzle Dry Low NOx 2.6+ Fuel Gas Split Staging Matrix
// =============================================================================

FUNCTION_BLOCK FB_DLN26_Split_Scheduler
VAR_INPUT
    rActive_Power_MW        : REAL;   // [MW] Actual generator power (0 - 500 MW)
    rComb_Shell_Temp_C      : REAL;   // [°C] Combustor wrapper shell temperature
    rComp_Disch_Temp_C      : REAL;   // [°C] TCD compressor discharge temperature
    rQuat_Dyn_Bias_Pct      : REAL;   // [%] Dynamic acoustic suppression trimming
    rCenter_Dyn_Bias_Pct    : REAL;   // [%] Dynamic center nozzle trimming
    bFlame_On               : BOOL;   // Optical flame detector status
END_VAR
VAR_OUTPUT
    stFuel_Splits           : ST_Fuel_Split_Demands;
    eDLN_Mode               : E_DLN_MODE;
    bMode_Transition_Active : BOOL;
END_VAR
VAR
    rLoad_Fraction          : REAL;
    rPM1_Raw                : REAL;
    rPM2_Raw                : REAL;
    rTFR_Raw                : REAL;
    rQ4_Raw                 : REAL;
    rSum_Splits             : REAL;
END_VAR

// 1. Determine Load Fraction and Operating Mode
rLoad_Fraction := LIMIT(0.0, rActive_Power_MW / 500.0, 1.10);

IF NOT bFlame_On THEN
    eDLN_Mode := DLN_MODE_SHUTDOWN;
ELSIF rLoad_Fraction < 0.08 THEN
    eDLN_Mode := DLN_MODE_IGNITION;      // FSNL & Low Warm-up
ELSIF rLoad_Fraction < 0.28 THEN
    eDLN_Mode := DLN_MODE_LEAN_LEAN;     // 8% - 28% Load
ELSIF rLoad_Fraction < 0.52 THEN
    eDLN_Mode := DLN_MODE_TRANSFER;      // 28% - 52% Load Transition
ELSIF rLoad_Fraction < 0.85 THEN
    eDLN_Mode := DLN_MODE_PREMIX_STEADY; // 52% - 85% Premix
ELSE
    eDLN_Mode := DLN_MODE_PREMIX_QUAT;   // 85% - 100%+ High Load
END_IF;

// 2. Base Fuel Staging Split Synthesis based on Load & Combustor Shell Temp
CASE eDLN_Mode OF
    DLN_MODE_SHUTDOWN:
        rPM1_Raw := 0.0; rPM2_Raw := 0.0; rTFR_Raw := 0.0; rQ4_Raw := 0.0;

    DLN_MODE_IGNITION:
        // 100% Primary ignition manifold
        rPM1_Raw := 100.0;
        rPM2_Raw := 0.0;
        rTFR_Raw := 0.0;
        rQ4_Raw  := 0.0;

    DLN_MODE_LEAN_LEAN:
        // Lean-Lean: Primary 75% down to 50%, Secondary 25% up to 50%
        rPM1_Raw := 75.0 - ((rLoad_Fraction - 0.08) / 0.20) * 25.0;
        rPM2_Raw := 25.0 + ((rLoad_Fraction - 0.08) / 0.20) * 25.0;
        rTFR_Raw := 0.0;
        rQ4_Raw  := 0.0;

    DLN_MODE_TRANSFER:
        // Transfer mode: PM1 drops to 15%, PM2 scales to 65%, TFR pilots 20%
        rPM1_Raw := 50.0 - ((rLoad_Fraction - 0.28) / 0.24) * 35.0;
        rPM2_Raw := 50.0 + ((rLoad_Fraction - 0.28) / 0.24) * 15.0;
        rTFR_Raw := ((rLoad_Fraction - 0.28) / 0.24) * 20.0;
        rQ4_Raw  := 0.0;

    DLN_MODE_PREMIX_STEADY:
        // Premix Steady State: PM1 (10%), PM2/PM3 (75%), TFR (15%)
        rPM1_Raw := 15.0 - ((rLoad_Fraction - 0.52) / 0.33) * 5.0;
        rPM2_Raw := 65.0 + ((rLoad_Fraction - 0.52) / 0.33) * 10.0;
        rTFR_Raw := 20.0 - ((rLoad_Fraction - 0.52) / 0.33) * 5.0;
        // Quaternary starts opening above 75% load based on wrapper temperature
        IF (rLoad_Fraction > 0.75) AND (rComb_Shell_Temp_C > 350.0) THEN
            rQ4_Raw := ((rLoad_Fraction - 0.75) / 0.10) * 5.0;
        ELSE
            rQ4_Raw := 0.0;
        END_IF;

    DLN_MODE_PREMIX_QUAT:
        // Premix High Load: PM1 (8%), PM2/PM3 (72%), TFR (8%), Quaternary (12%)
        rPM1_Raw := 10.0 - ((rLoad_Fraction - 0.85) / 0.15) * 2.0;
        rPM2_Raw := 75.0 - ((rLoad_Fraction - 0.85) / 0.15) * 3.0;
        rTFR_Raw := 15.0 - ((rLoad_Fraction - 0.85) / 0.15) * 7.0;
        rQ4_Raw  := 5.0  + ((rLoad_Fraction - 0.85) / 0.15) * 7.0;
END_CASE;

// 3. Inject Dynamic Acoustic Suppression Bias
rQ4_Raw  := rQ4_Raw + rQuat_Dyn_Bias_Pct;
rTFR_Raw := MAX(0.0, rTFR_Raw + rCenter_Dyn_Bias_Pct);

// 4. Normalization: Ensure sum of all split fractions strictly equals 100.0%
rSum_Splits := rPM1_Raw + rPM2_Raw + rTFR_Raw + rQ4_Raw;

IF rSum_Splits > 0.01 THEN
    stFuel_Splits.rSplit_PM1_Primary_Pct   := (rPM1_Raw / rSum_Splits) * 100.0;
    stFuel_Splits.rSplit_PM2_Secondary_Pct := (rPM2_Raw / rSum_Splits) * 100.0;
    stFuel_Splits.rSplit_TFR_Transfer_Pct  := (rTFR_Raw / rSum_Splits) * 100.0;
    stFuel_Splits.rSplit_Q4_Quaternary_Pct := (rQ4_Raw  / rSum_Splits) * 100.0;
ELSE
    stFuel_Splits.rSplit_PM1_Primary_Pct   := 100.0;
    stFuel_Splits.rSplit_PM2_Secondary_Pct := 0.0;
    stFuel_Splits.rSplit_TFR_Transfer_Pct  := 0.0;
    stFuel_Splits.rSplit_Q4_Quaternary_Pct := 0.0;
END_IF;

END_FUNCTION_BLOCK


// =============================================================================
// SUB-FUNCTION BLOCK: FB_VIGV_Compressor_Aerodynamics
// 3D Airflow Mapping & Anti-Surge Bleed Staging Protection
// =============================================================================

FUNCTION_BLOCK FB_VIGV_Compressor_Aerodynamics
VAR_INPUT
    rShaft_Speed_RPM        : REAL;   // [RPM] Actual shaft speed
    rInlet_Temp_C           : REAL;   // [°C] Inlet air temperature
    rInlet_Press_bar        : REAL;   // [bar] Inlet air pressure
    rDisch_Press_bar        : REAL;   // [bar] PCD compressor discharge pressure
    rActive_Power_MW        : REAL;   // [MW] Generator MW output
    rExhaust_Temp_Avg_C     : REAL;   // [°C] Exhaust temperature for HRSG matching
    rTarget_Exhaust_Temp_C  : REAL;   // [°C] Optimal combined cycle exhaust SP (~615°C)
    bFast_Ramp_Active       : BOOL;   // Transient rapid ramp indicator
END_VAR
VAR_OUTPUT
    stActuation             : ST_Compressor_Actuation;
    rCorrected_Speed_RPM    : REAL;   // [RPM] Corrected aerodynamic speed
    rCompressor_PR          : REAL;   // [-] Compressor Pressure Ratio (CPR)
    rSurge_Margin_Pct       : REAL;   // [%] Current calculated surge margin
    bSurge_Warning          : BOOL;   // Low surge margin alarm (< 12%)
END_VAR
VAR
    rInlet_Temp_K           : REAL;
    rTheta                  : REAL;
    rSurge_Limit_PR         : REAL;
    rVIGV_Base              : REAL;
    rVIGV_Exhaust_Trim      : REAL;
END_VAR

// 1. Aerodynamic Normalization & Speed Correction
rInlet_Temp_K := rInlet_Temp_C + 273.15;
IF rInlet_Temp_K > 200.0 THEN
    rTheta := SQRT(rInlet_Temp_K / 288.15);
ELSE
    rTheta := 1.0;
END_IF;

IF rTheta > 0.01 THEN
    rCorrected_Speed_RPM := rShaft_Speed_RPM / rTheta;
ELSE
    rCorrected_Speed_RPM := rShaft_Speed_RPM;
END_IF;

// 2. Compressor Pressure Ratio (CPR)
IF rInlet_Press_bar > 0.1 THEN
    rCompressor_PR := rDisch_Press_bar / rInlet_Press_bar;
ELSE
    rCompressor_PR := 1.0;
END_IF;

// 3. 3D Compressor VIGV Schedule
// VIGV modulates between -15° (closed, start/FSNL) to +38° (full base load flow)
IF rActive_Power_MW < 50.0 THEN
    rVIGV_Base := -15.0 + (rActive_Power_MW / 50.0) * 15.0; // -15° to 0°
ELSIF rActive_Power_MW < 400.0 THEN
    rVIGV_Base := 0.0 + ((rActive_Power_MW - 50.0) / 350.0) * 30.0; // 0° to +30°
ELSE
    rVIGV_Base := 30.0 + ((rActive_Power_MW - 400.0) / 100.0) * 8.0; // +30° to +38°
END_IF;

// Exhaust Temperature Matching for Combined Cycle Heat Recovery:
// Modulate VIGVs to maintain high exhaust temp at part load for HRSG steam production
IF (rActive_Power_MW >= 150.0) AND (rExhaust_Temp_Avg_C < rTarget_Exhaust_Temp_C) THEN
    // Close VIGVs slightly to reduce airflow and raise exhaust gas temperature
    rVIGV_Exhaust_Trim := -0.12 * (rTarget_Exhaust_Temp_C - rExhaust_Temp_Avg_C);
    rVIGV_Exhaust_Trim := LIMIT(-6.0, rVIGV_Exhaust_Trim, 0.0);
ELSE
    rVIGV_Exhaust_Trim := 0.0;
END_IF;

stActuation.rVIGV_Angle_Deg := LIMIT(-15.0, rVIGV_Base + rVIGV_Exhaust_Trim, 38.0);

// 4. Surge Margin Calculation & Bleed Valve Staging
// Surge Line CPR limit polynomial: PR_surge = 0.0078 * Ncorr - 0.45
rSurge_Limit_PR := (0.0078 * rCorrected_Speed_RPM) - 0.45;
IF rCompressor_PR > 0.1 THEN
    rSurge_Margin_Pct := ((rSurge_Limit_PR - rCompressor_PR) / rCompressor_PR) * 100.0;
ELSE
    rSurge_Margin_Pct := 100.0;
END_IF;

IF rSurge_Margin_Pct < 12.0 THEN
    bSurge_Warning := TRUE;
ELSE
    bSurge_Warning := FALSE;
END_IF;

// Bleed Valve Staging Logic:
// Stage 9 and Stage 14 bleeds open during start-up, low load (<100 MW), or rapid transients
IF rActive_Power_MW < 60.0 THEN
    stActuation.rBleed_Valve_Stg9_Pct  := 100.0;
    stActuation.rBleed_Valve_Stg14_Pct := 100.0;
ELSIF rActive_Power_MW < 120.0 THEN
    stActuation.rBleed_Valve_Stg9_Pct  := 100.0 * (1.0 - ((rActive_Power_MW - 60.0) / 60.0));
    stActuation.rBleed_Valve_Stg14_Pct := 50.0  * (1.0 - ((rActive_Power_MW - 60.0) / 60.0));
ELSIF bFast_Ramp_Active AND (rSurge_Margin_Pct < 14.0) THEN
    // Emergency transient anti-surge bleed crack
    stActuation.rBleed_Valve_Stg9_Pct  := 25.0;
    stActuation.rBleed_Valve_Stg14_Pct := 15.0;
ELSE
    stActuation.rBleed_Valve_Stg9_Pct  := 0.0;
    stActuation.rBleed_Valve_Stg14_Pct := 0.0;
END_IF;

END_FUNCTION_BLOCK


// =============================================================================
// SUB-FUNCTION BLOCK: FB_Rotor_Bore_Stress_Model
// Real-Time 1D Transient Thermal Conduction & Cumulative LCF Damage Accumulator
// =============================================================================

FUNCTION_BLOCK FB_Rotor_Bore_Stress_Model
VAR_INPUT
    rRotor_Surface_Temp_C   : REAL;   // [°C] Measured/Calculated rotor outer rim temperature
    rShaft_Speed_RPM        : REAL;   // [RPM] Actual shaft speed
    rCycle_Time_s           : REAL;   // [s] Execution task cycle time
    bReset_Cumulative_Stats : BOOL;   // Reset maintenance tracker
END_VAR
VAR_OUTPUT
    stFatigue               : ST_Rotor_Fatigue_Status;
    bThermal_Stress_Hold    : BOOL;   // Hold turbine ramp rate when stress > 480 MPa
    bThermal_Stress_Trip    : BOOL;   // Trip turbine if stress exceeds 620 MPa
END_VAR
VAR
    // Thermal Model Constants (NiCrMoV Alloy Steel)
    rThermal_Diffusivity    : REAL := 1.15E-5; // [m2/s] Thermal diffusivity (alpha)
    rYoungs_Modulus_E       : REAL := 2.05E5;  // [MPa] Elastic Modulus
    rThermal_Exp_Alpha      : REAL := 1.25E-5; // [1/K] Thermal expansion coefficient
    rPoisson_Ratio_Nu       : REAL := 0.29;    // Poisson's ratio
    rRotor_Outer_Radius     : REAL := 0.65;    // [m] Rotor outer radius (R_out)
    rRotor_Inner_Radius     : REAL := 0.08;    // [m] Center bore radius (R_in)

    // Internal Numerical States (3-Node Radial Lumped Thermal Conduction)
    rT_Bore_State           : REAL := 25.0;
    rT_Mid_State            : REAL := 25.0;

    // Cycle Counting & Fatigue Parameters (Coffin-Manson)
    rStress_Range_Peak      : REAL := 0.0;
    rStress_Valley_Min      : REAL := 1000.0;
    rCycle_Count_Equiv      : REAL := 0.0;
    rFatigue_Exponent_c     : REAL := -0.60;
    rFatigue_Ductility_ef   : REAL := 0.38;
END_VAR

// 1. 1D Radial Transient Heat Conduction (Lumped Finite-Difference Time Step)
// dT_mid/dt = (2 * alpha / dr^2) * (T_surf - 2*T_mid + T_bore)
rT_Mid_State := rT_Mid_State + (rCycle_Time_s * 0.0082) * (rRotor_Surface_Temp_C - (2.0 * rT_Mid_State) + rT_Bore_State);

// dT_bore/dt = (alpha / dr^2) * (T_mid - T_bore)
rT_Bore_State := rT_Bore_State + (rCycle_Time_s * 0.0045) * (rT_Mid_State - rT_Bore_State);

stFatigue.rBore_Temp_C := rT_Bore_State;
stFatigue.rMean_Temp_C := (rRotor_Surface_Temp_C + (2.0 * rT_Mid_State) + rT_Bore_State) / 4.0;

// 2. Thermal Stress at Rotor Bore Surface
// Sigma_thermal = (E * alpha_T / (1 - nu)) * (T_mean - T_bore)
stFatigue.rThermal_Stress_MPa := ((rYoungs_Modulus_E * rThermal_Exp_Alpha) / (1.0 - rPoisson_Ratio_Nu)) * 
                                  (stFatigue.rMean_Temp_C - stFatigue.rBore_Temp_C);

// 3. Centrifugal Mechanical Stress at Bore
// Sigma_mech = rho * omega^2 * Function(R_in, R_out, nu)
stFatigue.rMechanical_Stress_MPa := 280.0 * EXPT(rShaft_Speed_RPM / 3000.0, 2.0);

// 4. Combined Von Mises Equivalent Elastic-Plastic Stress
stFatigue.rVonMises_Stress_MPa := SQRT(
    EXPT(stFatigue.rMechanical_Stress_MPa, 2.0) + 
    EXPT(stFatigue.rThermal_Stress_MPa, 2.0) + 
    (stFatigue.rMechanical_Stress_MPa * stFatigue.rThermal_Stress_MPa)
);

// 5. Stress Constraints and Ramp Rate Hold
IF stFatigue.rVonMises_Stress_MPa >= 480.0 THEN
    bThermal_Stress_Hold         := TRUE;
    stFatigue.bStress_Limit_Active := TRUE;
ELSE
    bThermal_Stress_Hold         := FALSE;
    stFatigue.bStress_Limit_Active := FALSE;
END_IF;

IF stFatigue.rVonMises_Stress_MPa >= 620.0 THEN
    bThermal_Stress_Trip := TRUE;
ELSE
    bThermal_Stress_Trip := FALSE;
END_IF;

// 6. Cumulative Low-Cycle Fatigue (LCF) Damage Accumulation
IF bReset_Cumulative_Stats THEN
    stFatigue.rCumulative_Damage_LCF := 0.0;
    stFatigue.rRemaining_Life_Hours  := 100000.0;
ELSE
    // Real-time incremental strain accumulation (Miner's Rule)
    // Rate of damage increases exponentially with stress over yield (380 MPa)
    IF stFatigue.rVonMises_Stress_MPa > 380.0 THEN
        stFatigue.rCumulative_Damage_LCF := stFatigue.rCumulative_Damage_LCF + 
            (rCycle_Time_s * 1.5E-8) * EXPT(stFatigue.rVonMises_Stress_MPa / 380.0, 4.8);
    ELSE
        stFatigue.rCumulative_Damage_LCF := stFatigue.rCumulative_Damage_LCF + (rCycle_Time_s * 1.0E-10);
    END_IF;

    stFatigue.rCumulative_Damage_LCF := LIMIT(0.0, stFatigue.rCumulative_Damage_LCF, 1.0);

    IF stFatigue.rCumulative_Damage_LCF < 0.999 THEN
        stFatigue.rRemaining_Life_Hours := (1.0 - stFatigue.rCumulative_Damage_LCF) * 100000.0;
    ELSE
        stFatigue.rRemaining_Life_Hours := 0.0;
    END_IF;
END_IF;

END_FUNCTION_BLOCK


// =============================================================================
// SUB-FUNCTION BLOCK: FB_HRSG_Bypass_Coordinator
// Fast Steam Cycle Energy Dump Coordination during Rapid Grid Transients
// =============================================================================

FUNCTION_BLOCK FB_HRSG_Bypass_Coordinator
VAR_INPUT
    rActive_Power_MW        : REAL;   // [MW] Current active power
    rFFR_Boost_MW           : REAL;   // [MW] Demanded fast frequency boost
    rHP_Drum_Press_bar      : REAL;   // [bar] HP steam drum pressure
    bFast_Ramp_Active       : BOOL;   // True during fast frequency boost
    rCycle_Time_s           : REAL;   // [s] Cycle time
END_VAR
VAR_OUTPUT
    stBypass_Cmd            : ST_HRSG_Bypass_Command;
    bDrum_Pressure_High     : BOOL;   // HP Drum overpressure protection flag
END_VAR
VAR
    rHP_Bypass_Target       : REAL;
    rIP_Bypass_Target       : REAL;
    rPressure_Error         : REAL;
END_VAR

// 1. HP Drum Pressure Threshold Supervision (Nominal 160 bar, Max 185 bar)
IF rHP_Drum_Press_bar >= 178.0 THEN
    bDrum_Pressure_High := TRUE;
ELSE
    bDrum_Pressure_High := FALSE;
END_IF;

// 2. Coordinated Steam Bypass Modulation
// When the gas turbine rapidly ramps fuel for grid support (+50 MW in 500 ms),
// thermal energy surged into the HRSG must be coordinated with steam turbine bypass
// to avoid drum swell / boiler trip and provide immediate shaft torque stabilization.
IF bFast_Ramp_Active THEN
    // Pre-position fuel gas control valve with +6.5% feedforward bias
    stBypass_Cmd.rFuel_Prepos_Bias_Pct := 6.5 * (rFFR_Boost_MW / 50.0);
    // Modulate HP bypass open by 15% to buffer steam transient
    rHP_Bypass_Target := 15.0 * (rFFR_Boost_MW / 50.0);
    rIP_Bypass_Target := 10.0 * (rFFR_Boost_MW / 50.0);
ELSE
    stBypass_Cmd.rFuel_Prepos_Bias_Pct := 0.0;
    rHP_Bypass_Target := 0.0;
    rIP_Bypass_Target := 0.0;
END_IF;

// High pressure drum override trim
IF bDrum_Pressure_High THEN
    rPressure_Error   := (rHP_Drum_Press_bar - 178.0) * 12.5; // Proportional dump
    rHP_Bypass_Target := MAX(rHP_Bypass_Target, rPressure_Error);
END_IF;

stBypass_Cmd.rHP_Bypass_Valve_Pct := LIMIT(0.0, rHP_Bypass_Target, 100.0);
stBypass_Cmd.rIP_Bypass_Valve_Pct := LIMIT(0.0, rIP_Bypass_Target, 100.0);

END_FUNCTION_BLOCK


// =============================================================================
// MASTER FUNCTION BLOCK: FB_GasTurbine_Governor
// 500 MW Heavy-Duty Gas Turbine Governor & Fast Grid Synthetic Inertia Master
// =============================================================================

FUNCTION_BLOCK FB_GasTurbine_Governor
VAR_INPUT
    stSensors               : ST_GT_Sensors;              // Comprehensive sensor bundle
    rPower_Setpoint_MW      : REAL := 450.0;              // [MW] Operator / AGC active power target
    rSpeed_Setpoint_RPM     : REAL := 3000.0;             // [RPM] Synchronous speed target
    rNominal_Freq_Hz        : REAL := 50.0;               // [Hz] Grid standard base frequency
    rInertia_H_Constant     : REAL := 4.5;                // [s] Virtual inertia constant
    rDroop_Percent          : REAL := 4.0;                // [%] Droop characteristic
    rRamp_Rate_Limit_MW_min : REAL := 45.0;               // [MW/min] Normal base-load ramp rate limit
    rTarget_Exhaust_Temp_C  : REAL := 618.0;              // [°C] Combined cycle optimal exhaust temp
    bMaster_Enable          : BOOL := TRUE;               // Master controller enable
    bFast_Inertia_Enable    : BOOL := TRUE;               // Enable synthetic inertia injection
    bEmergency_Trip_In      : BOOL := FALSE;              // Master external safety trip
END_VAR

VAR_OUTPUT
    // Final Actuator Commands
    stFuel_Splits           : ST_Fuel_Split_Demands;      // Staged DLN 2.6+ Fuel split outputs
    stCompressor_Actuation  : ST_Compressor_Actuation;    // VIGV and Bleed Valve positions
    stHRSG_Bypass_Cmd       : ST_HRSG_Bypass_Command;     // Steam cycle coordination

    // Status & Diagnostics
    stInertia_Status        : ST_Synthetic_Inertia_Status;// Real-time RoCoF & Inertia state
    stFatigue_Status        : ST_Rotor_Fatigue_Status;    // Rotor life consumption stats
    eCurrent_DLN_Mode       : E_DLN_MODE;                 // Active DLN mode
    eGrid_State             : E_GRID_STATUS;              // Grid frequency state

    // Alarms & Trip Interlocks
    bMaster_Trip_Active     : BOOL;                       // Unit master trip state
    bAcoustic_Alarm         : BOOL;                       // Combustor oscillation warning
    bSurge_Warning          : BOOL;                       // Compressor surge warning
    bStress_Hold_Active     : BOOL;                       // Rotor thermal stress ramp hold
    bActive_Power_Limited   : BOOL;                       // Gas turbine operating at thermal/temp limit
END_VAR

VAR
    // Sub-Module Instances
    fbSyntheticInertia      : FB_RoCoF_Synthetic_Inertia;
    fbHelmholtzCompensator  : FB_Helmholtz_Phase_Compensator;
    fbDLNSplitScheduler     : FB_DLN26_Split_Scheduler;
    fbVIGVAerodynamics      : FB_VIGV_Compressor_Aerodynamics;
    fbRotorStressModel      : FB_Rotor_Bore_Stress_Model;
    fbHRSGBypassCoordinator : FB_HRSG_Bypass_Coordinator;

    // Internal Control Signals
    rCycle_Time_s           : REAL := 0.010;              // 10.0 ms execution rate
    rRamped_Power_SP_MW     : REAL := 450.0;
    rMax_MW_Increment       : REAL;

    // Speed/Load Governor PID Channels
    rSpeed_Error_RPM        : REAL;
    rFSR_Speed_Demand       : REAL;
    rFSR_Power_Demand       : REAL;
    rFSR_Temp_Limit         : REAL;
    rFSR_Acceleration_Limit : REAL;
    rFSR_Min_Selected       : REAL;

    // Speed PID Integrator
    rSpeed_Integral_State   : REAL := 45.0;
    rPower_Integral_State   : REAL := 45.0;
    rSpeed_Kp               : REAL := 0.08;
    rSpeed_Ki               : REAL := 0.04;
    rPower_Kp               : REAL := 0.05;
    rPower_Ki               : REAL := 0.02;

    // Acceleration Tracking
    rShaft_Speed_Prev       : REAL := 3000.0;
    rRotor_Acceleration_RPM_s: REAL := 0.0;
END_VAR

// =============================================================================
// 1. MASTER SAFETY & TRIP SUPERVISION
// =============================================================================
IF bEmergency_Trip_In OR 
   (stSensors.rExhaust_Temp_Max_C >= 665.0) OR 
   (stSensors.rShaft_Speed_RPM >= 3360.0) THEN // 112% Mechanical Overspeed
    bMaster_Trip_Active := TRUE;
END_IF;

IF bMaster_Trip_Active OR NOT bMaster_Enable THEN
    // Safe shutdown state: Immediately isolate all fuel manifolds
    stFuel_Splits.rFSR_Total_Pct           := 0.0;
    stFuel_Splits.rSplit_PM1_Primary_Pct   := 100.0;
    stFuel_Splits.rSplit_PM2_Secondary_Pct := 0.0;
    stFuel_Splits.rSplit_TFR_Transfer_Pct  := 0.0;
    stFuel_Splits.rSplit_Q4_Quaternary_Pct := 0.0;

    // Open all bleed valves to relieve compressor pressure
    stCompressor_Actuation.rVIGV_Angle_Deg         := -15.0;
    stCompressor_Actuation.rBleed_Valve_Stg9_Pct   := 100.0;
    stCompressor_Actuation.rBleed_Valve_Stg14_Pct  := 100.0;

    // Full dump to steam bypass
    stHRSG_Bypass_Cmd.rHP_Bypass_Valve_Pct := 100.0;
    stHRSG_Bypass_Cmd.rIP_Bypass_Valve_Pct := 100.0;
    stHRSG_Bypass_Cmd.rFuel_Prepos_Bias_Pct:= 0.0;
    RETURN;
END_IF;

// =============================================================================
// 2. ROTOR ACCELERATION & FAST DYNAMICS TRACKING
// =============================================================================
IF rCycle_Time_s > 0.0001 THEN
    rRotor_Acceleration_RPM_s := (stSensors.rShaft_Speed_RPM - rShaft_Speed_Prev) / rCycle_Time_s;
ELSE
    rRotor_Acceleration_RPM_s := 0.0;
END_IF;
rShaft_Speed_Prev := stSensors.rShaft_Speed_RPM;

// =============================================================================
// 3. EXECUTE SYNTHETIC INERTIA & FAST FREQUENCY RESPONSE (FFR)
// =============================================================================
fbSyntheticInertia(
    rGrid_Freq        := stSensors.rGrid_Freq_Hz,
    rNominal_Freq     := rNominal_Freq_Hz,
    rRated_Power_MW   := 500.0,
    rInertia_Constant_H:= rInertia_H_Constant,
    rDroop_Percent    := rDroop_Percent,
    rDeadband_Hz      := 0.03,
    rCycle_Time_s     := rCycle_Time_s,
    bEnable_SI        := bFast_Inertia_Enable,
    bEnable_FFR_Boost := TRUE
);

stInertia_Status.rFiltered_RoCoF_Hz_s  := fbSyntheticInertia.rRoCoF_Hz_s;
stInertia_Status.rInertial_Power_MW    := fbSyntheticInertia.rP_Inertia_MW;
stInertia_Status.rDroop_Power_MW       := fbSyntheticInertia.rP_Droop_MW;
stInertia_Status.rTotal_FFR_Power_MW   := fbSyntheticInertia.rP_Total_Fast_MW;
stInertia_Status.bFast_Boost_Triggered := fbSyntheticInertia.bFast_Ramp_Active;
eGrid_State                            := fbSyntheticInertia.eGrid_State;

// Integrate Delivered Energy (MJ)
IF fbSyntheticInertia.bFast_Ramp_Active THEN
    stInertia_Status.rEnergy_Delivered_MJ := stInertia_Status.rEnergy_Delivered_MJ + 
                                             (fbSyntheticInertia.rP_Total_Fast_MW * rCycle_Time_s);
END_IF;

// =============================================================================
// 4. EXECUTE ROTOR THERMAL BORE STRESS & FATIGUE MODEL
// =============================================================================
fbRotorStressModel(
    rRotor_Surface_Temp_C   := stSensors.rRotor_Surface_Temp_C,
    rShaft_Speed_RPM        := stSensors.rShaft_Speed_RPM,
    rCycle_Time_s           := rCycle_Time_s,
    bReset_Cumulative_Stats := FALSE
);

stFatigue_Status    := fbRotorStressModel.stFatigue;
bStress_Hold_Active := fbRotorStressModel.bThermal_Stress_Hold;

IF fbRotorStressModel.bThermal_Stress_Trip THEN
    bMaster_Trip_Active := TRUE;
    RETURN;
END_IF;

// =============================================================================
// 5. EXECUTE ACOUSTIC COMBUSTION OSCILLATION PHASE COMPENSATOR
// =============================================================================
fbHelmholtzCompensator(
    rAcoustic_Helmholtz_mbar:= stSensors.rAcoustic_Helmholtz_mbar,
    rAcoustic_Screech_mbar  := stSensors.rAcoustic_Screech_mbar,
    rT_Shell_C              := stSensors.rComb_Shell_Temp_C,
    rCycle_Time_s           := rCycle_Time_s,
    bEnable_Compensator     := TRUE
);

bAcoustic_Alarm := fbHelmholtzCompensator.bAcoustic_High_Alarm;
IF fbHelmholtzCompensator.bCombustion_Trip_Req THEN
    bMaster_Trip_Active := TRUE;
    RETURN;
END_IF;

// =============================================================================
// 6. SPEED/LOAD & FAST SYNTHETIC INERTIA GOVERNOR AUCTIONEERING
// =============================================================================

// Rate-limited Power Setpoint tracking (with stress hold override)
rMax_MW_Increment := (rRamp_Rate_Limit_MW_min / 60.0) * rCycle_Time_s;

IF bStress_Hold_Active AND (rPower_Setpoint_MW > rRamped_Power_SP_MW) THEN
    // Hold ramp rate: Do not increase power setpoint while rotor is in high thermal stress
    rRamped_Power_SP_MW := rRamped_Power_SP_MW;
ELSE
    IF rPower_Setpoint_MW > (rRamped_Power_SP_MW + rMax_MW_Increment) THEN
        rRamped_Power_SP_MW := rRamped_Power_SP_MW + rMax_MW_Increment;
    ELSIF rPower_Setpoint_MW < (rRamped_Power_SP_MW - rMax_MW_Increment) THEN
        rRamped_Power_SP_MW := rRamped_Power_SP_MW - rMax_MW_Increment;
    ELSE
        rRamped_Power_SP_MW := rPower_Setpoint_MW;
    END_IF;
END_IF;

// Add fast synthetic inertia power demand directly to effective target
rRamped_Power_SP_MW := LIMIT(0.0, rRamped_Power_SP_MW + fbSyntheticInertia.rP_Total_Fast_MW, 550.0);

// Speed Governor Error & PI Control
rSpeed_Error_RPM := rSpeed_Setpoint_RPM - stSensors.rShaft_Speed_RPM;
rSpeed_Integral_State := LIMIT(0.0, rSpeed_Integral_State + (rSpeed_Ki * rSpeed_Error_RPM * rCycle_Time_s), 100.0);
rFSR_Speed_Demand := (rSpeed_Kp * rSpeed_Error_RPM) + rSpeed_Integral_State;

// Active Power Control Loop
rPower_Integral_State := LIMIT(0.0, rPower_Integral_State + (rPower_Ki * (rRamped_Power_SP_MW - stSensors.rActive_Power_MW) * rCycle_Time_s), 100.0);
rFSR_Power_Demand := (rPower_Kp * (rRamped_Power_SP_MW - stSensors.rActive_Power_MW)) + rPower_Integral_State;

// Exhaust Temperature Limit Controller (Base Load FSR Ceiling)
// TTRX Limit: FSR_Temp = K_temp * (640°C - T_exhaust)
rFSR_Temp_Limit := 55.0 + 0.45 * (640.0 - stSensors.rExhaust_Temp_Avg_C);
rFSR_Temp_Limit := LIMIT(0.0, rFSR_Temp_Limit, 100.0);

// Acceleration Limit Control (Protects shaft from torque shear: max 60 RPM/s)
IF rRotor_Acceleration_RPM_s > 60.0 THEN
    rFSR_Acceleration_Limit := 40.0 - (rRotor_Acceleration_RPM_s - 60.0) * 1.5;
ELSE
    rFSR_Acceleration_Limit := 100.0;
END_IF;

// Auctioneering: Minimum Selection of Control Demands (Min Select Gateway)
rFSR_Min_Selected := MIN(rFSR_Speed_Demand, rFSR_Power_Demand);
rFSR_Min_Selected := MIN(rFSR_Min_Selected, rFSR_Temp_Limit);
rFSR_Min_Selected := MIN(rFSR_Min_Selected, rFSR_Acceleration_Limit);

// Inject Feedforward Fast Pulse Bias from Steam Coordination
fbHRSGBypassCoordinator(
    rActive_Power_MW    := stSensors.rActive_Power_MW,
    rFFR_Boost_MW       := fbSyntheticInertia.rP_Total_Fast_MW,
    rHP_Drum_Press_bar  := stSensors.rHPSG_HP_Drum_Press_bar,
    bFast_Ramp_Active   := fbSyntheticInertia.bFast_Ramp_Active,
    rCycle_Time_s       := rCycle_Time_s
);

stHRSG_Bypass_Cmd := fbHRSGBypassCoordinator.stBypass_Cmd;

// Apply Pre-positioning Bias
stFuel_Splits.rFSR_Total_Pct := LIMIT(0.0, rFSR_Min_Selected + stHRSG_Bypass_Cmd.rFuel_Prepos_Bias_Pct, 100.0);

// Active Power Saturation Diagnostics
IF stFuel_Splits.rFSR_Total_Pct >= (rFSR_Temp_Limit - 0.5) THEN
    bActive_Power_Limited := TRUE;
ELSE
    bActive_Power_Limited := FALSE;
END_IF;

// =============================================================================
// 7. EXECUTE DLN 2.6+ FUEL SPLIT SCHEDULER
// =============================================================================
fbDLNSplitScheduler(
    rActive_Power_MW     := stSensors.rActive_Power_MW,
    rComb_Shell_Temp_C   := stSensors.rComb_Shell_Temp_C,
    rComp_Disch_Temp_C   := stSensors.rComp_Disch_Temp_C,
    rQuat_Dyn_Bias_Pct   := fbHelmholtzCompensator.rQuat_Bias_Trimming_Pct,
    rCenter_Dyn_Bias_Pct := fbHelmholtzCompensator.rCenter_Nozzle_Bias_Pct,
    bFlame_On            := (stSensors.rComb_Shell_Temp_C >= 260.0)
);

stFuel_Splits.rSplit_PM1_Primary_Pct   := fbDLNSplitScheduler.stFuel_Splits.rSplit_PM1_Primary_Pct;
stFuel_Splits.rSplit_PM2_Secondary_Pct := fbDLNSplitScheduler.stFuel_Splits.rSplit_PM2_Secondary_Pct;
stFuel_Splits.rSplit_TFR_Transfer_Pct  := fbDLNSplitScheduler.stFuel_Splits.rSplit_TFR_Transfer_Pct;
stFuel_Splits.rSplit_Q4_Quaternary_Pct := fbDLNSplitScheduler.stFuel_Splits.rSplit_Q4_Quaternary_Pct;
eCurrent_DLN_Mode                      := fbDLNSplitScheduler.eDLN_Mode;

// =============================================================================
// 8. EXECUTE COMPRESSOR VIGV & ANTI-SURGE ACTUATION
// =============================================================================
fbVIGVAerodynamics(
    rShaft_Speed_RPM       := stSensors.rShaft_Speed_RPM,
    rInlet_Temp_C          := stSensors.rInlet_Air_Temp_C,
    rInlet_Press_bar       := stSensors.rInlet_Air_Press_bar,
    rDisch_Press_bar       := stSensors.rComp_Disch_Press_bar,
    rActive_Power_MW       := stSensors.rActive_Power_MW,
    rExhaust_Temp_Avg_C    := stSensors.rExhaust_Temp_Avg_C,
    rTarget_Exhaust_Temp_C := rTarget_Exhaust_Temp_C,
    bFast_Ramp_Active      := fbSyntheticInertia.bFast_Ramp_Active
);

stCompressor_Actuation := fbVIGVAerodynamics.stActuation;
bSurge_Warning         := fbVIGVAerodynamics.bSurge_Warning;

END_FUNCTION_BLOCK
```

# Master-Tier Bioprocess Architecture: mRNA LNP Impingement Jet Microfluidic Synthesis & Encapsulation Controller

## 1. Engineering Process & Physics Rationale

### 1.1 Microfluidic Impingement Jet Thermodynamics & Hydrodynamics
The synthesis of messenger RNA (mRNA) lipid nanoparticles (LNPs) relies on rapid, controlled chaotic advective mixing within a microfluidic impingement chip (e.g., staggered herringbone mixer or planar cross-impinging jet geometry). The process introduces an ethanolic phase (dissolving ionizable cationic lipids, DSPC, cholesterol, and PEG-lipids) into an acidic aqueous phase containing single-stranded mRNA in sodium citrate buffer (pH 4.0). 

As the ethanol concentration drops rapidly below ~60% upon mixing, the hydrophobic domains of the lipids self-assemble around the negatively charged phosphate backbone of the mRNA via electrostatic condensation, forming electron-dense, inverted micellar core structures enclosed in a lipid bilayer.

To guarantee monodisperse self-assembly, the fluid flow must operate in the chaotic advection regime defined by the channel Reynolds ($Re$) and Dean ($De$) numbers:
$$D_h = \frac{2 \cdot w \cdot h}{w + h}$$
$$Re = \frac{\rho_{mix} \cdot v \cdot D_h}{\mu_{mix}} = \frac{\rho_{mix} \cdot (Q_{tot} / A) \cdot D_h}{\mu_{mix}}$$
$$De = Re \cdot \sqrt{\frac{D_h}{2 R_c}}$$

Where:
- $w, h$: Microchannel width ($200\,\mu\text{m}$) and height ($100\,\mu\text{m}$) yielding $A = 2.0 \times 10^{-8}\,\text{m}^2$ and $D_h = 133.33\,\mu\text{m}$.
- $R_c$: Curvature radius of Dean mixing loops ($1.5\,\text{mm}$).
- $\rho_{mix}, \mu_{mix}$: Density and dynamic viscosity of the binary ethanol-water mixture. The dynamic viscosity $\mu_{mix}$ exhibits a pronounced non-ideal excess peak around $40\text{--}50\text{ wt}\%$ EtOH at $20^\circ\text{C}$ (~2.85 mPa*s vs 1.0 mPa*s for pure water). We compute $\mu_{mix}$ using a 4th-order polynomial approximation across the mixing boundary.

### 1.2 Stoichiometric Nitrogen-to-Phosphate ($N/P$) Molar Ratio Regulation
The efficacy and encapsulation efficiency of mRNA-LNPs are governed by the molar ratio of positively ionizable amine groups ($N$) to negatively charged nucleotide phosphate groups ($P$):
$$\text{Molar Flow } \dot{n}_N = \frac{Q_{lipid} \cdot C_{lipid} \cdot n_N}{M_{lipid}}$$
$$\text{Molar Flow } \dot{n}_P = \frac{Q_{mRNA} \cdot C_{mRNA} \cdot n_P}{M_{nt}}$$
$$\text{Ratio } N/P = \frac{\dot{n}_N}{\dot{n}_P} = \left(\frac{Q_{lipid}}{Q_{mRNA}}\right) \cdot \left(\frac{C_{lipid} \cdot n_N}{M_{lipid}}\right) \cdot \left(\frac{M_{nt}}{C_{mRNA} \cdot n_P}\right)$$

Where:
- $M_{lipid}$: Molecular weight of ionizable lipid (e.g., $710.2\,\text{g/mol}$).
- $n_N$: Number of tertiary amine heads per lipid molecule ($1\,\text{amine/mol}$).
- $M_{nt}$: Average molecular weight of mRNA nucleotide ($330.0\,\text{g/mol}$, with $n_P = 1\,\text{phosphate/nt}$).
- $C_{lipid}, C_{mRNA}$: Stock solution concentrations in $\text{mg/mL}$ (or $\text{g/L}$).

The controller implements a high-speed decoupled ratio PID trim loop that modulates the organic-to-aqueous volumetric flow ratio around nominal (typically $1:3$, volumetric fraction $\phi_{EtOH} = 0.25$) to maintain $N/P$ strictly within $\pm 0.5\%$ of setpoint (e.g., $6.00 \pm 0.03$).

### 1.3 In-Line Dynamic Light Scattering (DLS) & Waste Diversion Gating
In-line DLS flow cells continuously measure the hydrodynamic Z-average particle diameter ($Z_{avg}$) and Polydispersity Index ($PDI$). 
- Target $Z_{avg}$: $65.0\,\text{nm}$ to $85.0\,\text{nm}$ ($75.0\,\text{nm}$ setpoint).
- Target $PDI$: $< 0.08$ (monodisperse).
- An ultrafast sanitary 3-way divert valve routes fluid to `WASTE` during startup priming, volumetric ramp transitions, flow oscillations, or whenever $Z_{avg} \notin [60.0, 90.0]\,\text{nm}$ or $PDI > 0.10$. Only fully qualified steady-state formulation is routed to `HARVEST`.

### 1.4 Tangential Flow Filtration (TFF) Diafiltration & Concentration
Post-synthesis LNP suspensions contain $25\%\,\text{v/v}$ residual ethanol and an acidic pH ($4.0$), which must be exchanged into neutral, isotonic storage buffer (PBS/Sucrose pH 7.4) via TFF:
- **Transmembrane Pressure (TMP)**:
  $$TMP = \frac{P_{Feed} + P_{Retentate}}{2} - P_{Permeate}$$
- **Shear Stress Protection**: Feed-to-retentate pressure drop $\Delta P = P_{Feed} - P_{Retentate} \le 1.2\,\text{bar}$ and $TMP \le 0.8\,\text{bar}$ to prevent mechanical shear rupture of vesicles.
- **Diafiltration Volumes (DV)**: Continuous diafiltration at constant retentate volume tracking $DV = V_{permeate} / V_{retentate\_init} \ge 10.0$ to guarantee residual ethanol $< 500\,\text{ppm}$.
- **Ultrafiltration Concentration**: Concentration factor ($CF = 4.0\times$) target.

### 1.5 Cryogenic Controlled-Rate Freeze-Down
Post-TFF, LNPs formulated with cryoprotectant (e.g., $10\%\,\text{w/v}$ sucrose/trehalose) undergo controlled freezing in a jacketed vessel at a linear rate of $-1.0^\circ\text{C/min}$ down to $-80.0^\circ\text{C}$ to minimize ice crystal lattice growth and prevent vesicle aggregation.

### 1.6 ISA-88 Batch Model & 21 CFR Part 11 Data Integrity
The system implements a rigid 14-state ISA-88 procedural state machine with Clean-In-Place (CIP with $0.5\,\text{M}$ NaOH), Steam-In-Place (SIP with $F_0 = \int 10^{(T-121.1)/10} dt \ge 30.0\,\text{min}$), and an electronic circular audit trail buffer recording cryptographic checksums, state transitions, operator electronic signatures, and process telemetry.

