FUNCTION_BLOCK FB_LNP_EncapsulationController
TITLE = 'mRNA LNP Impingement Jet Microfluidic Controller'
VERSION : '4.2'
AUTHOR : 'Lumina Bioprocess Automation Architect'

//=============================================================================
// CONSTANTS
//=============================================================================
VAR CONSTANT
